"""Verifier for the PD-RETAIL v4 monitoring estate.

Shipped-estate checks compare the agent's artifacts with the expected artifacts
computed when the estate was generated. Row artifacts are graded per account:
every account of the cycle belongs to exactly one trap family, and each family
check grades that family's rows in all four row files, so one wrong row costs
one family. Hidden-estate checks build fresh estates from EVAL_SEED with the
estate generator at the end of this file, run the delivered engine on them as an
unprivileged user, and compare its output byte for byte.

Every check returns False rather than raising. Estate generation and engine runs
are serialised behind one lock, so concurrent checks never see each other's
temporary state.
"""

from __future__ import annotations

import base64
import contextlib
import json
import os
import re
import shutil
import signal
import subprocess
import sys
import tempfile
import threading
import zlib
from pathlib import Path
from typing import Any

from rewardkit import criteria, criterion

EVAL_SEED = int("1972138169496734964")
PAYLOAD = ""

OUTPUTS = ["cohort.csv", "exclusions.csv", "score_selection.csv", "performance_windows.csv", "population_summary.json",
           "discrimination.json", "psi.json", "calibration.csv", "reconciliation.json"]
ROW_FILES = ["cohort.csv", "exclusions.csv", "score_selection.csv", "performance_windows.csv"]
METRIC_FILES = ["population_summary.json", "discrimination.json", "psi.json", "calibration.csv", "reconciliation.json"]
ENGINE_TIMEOUT = 900
EVAL_SCALE = 0.12
_SETPRIV = ["setpriv", "--reuid=nobody", "--regid=nogroup", "--clear-groups"]
_CACHE: dict[str, Any] = {}
_LOCK = threading.RLock()


def _payload() -> dict[str, Any]:
    with _LOCK:
        if "payload" not in _CACHE:
            _CACHE["payload"] = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)).decode("utf-8"))
        return _CACHE["payload"]


def _read(path: Path) -> str | None:
    try:
        return path.read_bytes().decode("utf-8")
    except (OSError, UnicodeDecodeError):
        return None


def _artifact(workspace: Path, name: str) -> str | None:
    return _read(workspace / "out" / name)


def _shipped_exact(workspace: Path, name: str) -> bool:
    return _artifact(workspace, name) == _payload()["expected"][name]


def _rows(text: str) -> dict[str, str]:
    return {ln.split(",", 1)[0]: ln for ln in text.split("\n")[1:] if ln}


def _universe() -> set[str]:
    with _LOCK:
        if "universe" not in _CACHE:
            expected = _payload()["expected"]
            _CACHE["universe"] = {key for name in ROW_FILES for key in _rows(expected[name])}
        return _CACHE["universe"]


def _family_ok(workspace: Path, family: str) -> bool:
    expected = _payload()["expected"]
    accounts = _payload()["families"][family]
    for name in ROW_FILES:
        text = _artifact(workspace, name)
        if text is None:
            return False
        got, want = _rows(text), _rows(expected[name])
        if any(got.get(a) != want.get(a) for a in accounts):
            return False
    return True


# ---- running the delivered engine --------------------------------------------
def _as_root() -> bool:
    return os.name == "posix" and os.geteuid() == 0


def _engine_ids() -> tuple[int, int] | None:
    if not _as_root():
        return None
    import grp
    import pwd
    return pwd.getpwnam("nobody").pw_uid, grp.getgrnam("nogroup").gr_gid


def _reap(uid: int) -> None:
    """Kill every process left running as the engine user, including daemons that left the group."""
    for _pass in range(3):
        found = False
        for entry in Path("/proc").iterdir():
            if not entry.name.isdigit():
                continue
            status = _read(entry / "status") or ""
            owner = re.search(r"^Uid:\s+(\d+)", status, re.M)
            if owner and int(owner.group(1)) == uid:
                found = True
                with contextlib.suppress(ProcessLookupError, PermissionError):
                    os.kill(int(entry.name), signal.SIGKILL)
        if not found:
            return


def _estate(kind: str) -> tuple[Path, dict[str, str]] | None:
    key = "estate:" + kind
    with _LOCK:
        if key not in _CACHE:
            try:
                root = Path(tempfile.mkdtemp(prefix=f"estate-{kind}-"))
                seed, scale, variant = {"eval": (EVAL_SEED, EVAL_SCALE, None),
                                        "truncated": (EVAL_SEED ^ 0x5A5A, EVAL_SCALE, "truncated"),
                                        "full": (EVAL_SEED ^ 0xF00D, 1.0, None)}[kind]
                data = root / "estate"
                expected = build_eval(seed, scale, data, variant)
                root.chmod(0o755)
                for path in [data, *data.iterdir()]:
                    path.chmod(0o755 if path.is_dir() else 0o644)
                _CACHE[key] = (data, expected)
            except Exception as exc:  # noqa: BLE001 - a broken generator must not abort grading
                print(f"estate {kind} could not be generated: {exc}", file=sys.stderr)
                _CACHE[key] = None
        return _CACHE[key]


def _staged_engine(workspace: Path) -> Path | None:
    """Root-owned, world-readable copy of the delivered engine, so the unprivileged run can open it whatever mode the agent left."""
    with _LOCK:
        if "engine" not in _CACHE:
            staged = None
            try:
                source = (workspace / "out" / "monitor.py").read_bytes()
                stage = Path(tempfile.mkdtemp(prefix="engine-stage-"))
                staged = stage / "monitor.py"
                staged.write_bytes(source)
                staged.chmod(0o644)
                stage.chmod(0o755)
            except OSError:
                staged = None
            _CACHE["engine"] = staged
        return _CACHE["engine"]


def _run_engine(workspace: Path, estate: Path, label: str) -> dict[str, str | None] | None:
    key = f"run:{label}:{estate}"
    with _LOCK:
        if key in _CACHE:
            return _CACHE[key]
        staged = _staged_engine(workspace)
        result = None
        if staged is not None:
            ids = _engine_ids()
            out = Path(tempfile.mkdtemp(prefix=f"engine-{label}-"))
            command = [sys.executable, str(staged), str(estate), str(out)]
            if ids is not None:
                os.chown(out, *ids)
                command = [*_SETPRIV, *command]
            env = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C.UTF-8", "LC_ALL": "C.UTF-8", "HOME": "/tmp",
                   "PYTHONHASHSEED": "random"}
            try:
                # No pipes to agent code: nothing it prints is buffered in this process.
                proc = subprocess.Popen(command, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                                        stderr=subprocess.DEVNULL, env=env, cwd="/tmp", start_new_session=True)
            except OSError:
                proc = None
            if proc is not None:
                try:
                    finished = proc.wait(timeout=ENGINE_TIMEOUT) == 0
                except subprocess.TimeoutExpired:
                    finished = False
                with contextlib.suppress(ProcessLookupError, PermissionError):
                    os.killpg(proc.pid, signal.SIGKILL)
                # Daemons that left the group with setsid() are killed by uid.
                if ids is not None:
                    _reap(ids[0])
                proc.wait()
                if finished:
                    result = {name: _read(out / name) for name in OUTPUTS}
        _CACHE[key] = result
        return result


def _eval_output(workspace: Path, kind: str) -> tuple[dict[str, str | None], dict[str, str]] | None:
    estate = _estate(kind)
    if estate is None:
        return None
    got = _run_engine(workspace, estate[0], kind)
    if got is None:
        return None
    return got, estate[1]


def _eval_files_exact(workspace: Path, kind: str, names: list[str]) -> bool:
    run = _eval_output(workspace, kind)
    return run is not None and all(run[0][name] == run[1][name] for name in names)


# ---- positive checks -----------------------------------------------------------
@criterion(description="All ten declared artifacts exist under /app/out")
def artifacts_exist(workspace: Path) -> bool:
    return (workspace / "out" / "monitor.py").is_file() and all((workspace / "out" / n).is_file() for n in OUTPUTS)


@criterion(description="Every artifact parses and carries the header row or top-level keys the specification defines")
def outputs_follow_declared_schema(workspace: Path) -> bool:
    expected = _payload()["expected"]
    for name in OUTPUTS:
        text = _artifact(workspace, name)
        if text is None:
            return False
        if name.endswith(".csv"):
            if text.split("\n", 1)[0] != expected[name].split("\n", 1)[0]:
                return False
        else:
            try:
                got = json.loads(text)
            except (ValueError, RecursionError):
                return False
            if not isinstance(got, dict) or sorted(got) != sorted(json.loads(expected[name])):
                return False
    return True


@criterion(description="The four row files use LF endings with a trailing newline and list cycle accounts in strictly ascending acct order")
def row_files_layout_exact(workspace: Path) -> bool:
    universe = _universe()
    for name in ROW_FILES:
        text = _artifact(workspace, name)
        if text is None or "\r" in text or not text.endswith("\n"):
            return False
        keys = [ln.split(",", 1)[0] for ln in text.split("\n")[1:-1]]
        if not keys or any(a >= b for a, b in zip(keys, keys[1:])) or not set(keys) <= universe:
            return False
    return True


