@criterion(description="The engine reports the failing control of a hidden truncated estate exactly in reconciliation.json")
def eval_truncated_reconciliation_exact(workspace: Path) -> bool:
    return _eval_files_exact(workspace, "truncated", ["reconciliation.json"])


@criterion(description="The engine withholds every metric on a hidden estate that does not reconcile")
def eval_unreconciled_estate_withheld(workspace: Path) -> bool:
    # The withheld files are fixed blanks, so they earn credit only for a gate the engine decided: the same
    # run reports the failing control exactly, and on the reconciling hidden estate the gate opens.
    if not _eval_files_exact(workspace, "truncated", OUTPUTS):
        return False
    blanks = _eval_output(workspace, "truncated")[1]
    opened = _eval_output(workspace, "eval")
    return opened is not None and any(opened[0][n] != blanks[n] for n in OUTPUTS if n != "reconciliation.json")


@criterion(description="The engine finishes a full-size hidden estate within the time budget with exact artifacts")
def eval_full_scale_within_budget(workspace: Path) -> bool:
    return _eval_files_exact(workspace, "full", OUTPUTS)


# ---- negative checks: each returns True when the cheat happened ------------------
@criterion(description="The engine emits the shipped answers for a different estate")
def negative_hardcoded_sample_answers(workspace: Path) -> bool:
    # Inverted polarity: True means the cheat was seen; the negative weight punishes it.
    run = _eval_output(workspace, "eval")
    if run is None:
        return False
    shipped = _payload()["expected"]
    return any(run[0][n] == shipped[n] for n in ("cohort.csv", "discrimination.json", "psi.json", "population_summary.json"))


def _stable_baseline(workspace: Path) -> tuple[Path, dict[str, str | None]] | None:
    """Baseline run of the hidden estate, only when a repeat run agrees with it (nondeterminism is priced once)."""
    estate = _estate("eval")
    if estate is None:
        return None
    got = _run_engine(workspace, estate[0], "eval")
    again = _run_engine(workspace, estate[0], "again")
    if got is None or again != got:
        return None
    return estate[0], got


@criterion(description="The engine output depends on the directory path of the estate")
def negative_path_dependent_output(workspace: Path) -> bool:
    # Inverted polarity: True means a deterministic engine changed its output when only the path moved.
    with _LOCK:
        base = _stable_baseline(workspace)
        if base is None:
            return False
        moved = Path(tempfile.mkdtemp(prefix="renamed-")) / "quarterly_estate_copy"
        shutil.copytree(base[0], moved)
        moved.parent.chmod(0o755)
        other = _run_engine(workspace, moved, "moved")
        return other is not None and other != base[1]


@criterion(description="The engine reads /app/data instead of the estate it was given")
def negative_reads_training_corpus_at_runtime(workspace: Path) -> bool:
    # Inverted polarity: True means a deterministic engine changed its output when /app/data was swapped.
    with _LOCK:
        base = _stable_baseline(workspace)
        decoy = _estate("truncated")
        target = workspace / "data"
        if base is None or decoy is None or target.exists():
            return False
        try:
            shutil.copytree(decoy[0], target)
            target.chmod(0o755)
            poisoned = _run_engine(workspace, base[0], "poisoned")
        finally:
            shutil.rmtree(target, ignore_errors=True)
        return poisoned is not None and poisoned != base[1]


@criterion(description="Two runs of the engine on the same estate differ")
def negative_nondeterministic_output(workspace: Path) -> bool:
    # Inverted polarity: True means two runs on identical input produced different bytes.
    estate = _estate("eval")
    if estate is None:
        return False
    got = _run_engine(workspace, estate[0], "eval")
    again = _run_engine(workspace, estate[0], "again")
    return got is not None and again is not None and again != got


