# =============================================================================
# Hidden estate generator. build_eval(seed, scale, out_dir, variant) writes a
# fresh estate with the shipped layout under the documented rules and returns
# its expected artifacts; the checks above call it at grade time.
# =============================================================================

from pathlib import Path


# ---------------------------------------------------------------------------
# Truth engine: turns the generated world into the expected monitoring
# artifacts of a hidden estate.
# ---------------------------------------------------------------------------
import calendar as _cal
import datetime as _dt
import json as _json
from decimal import Decimal, ROUND_HALF_EVEN, ROUND_HALF_UP, localcontext
from fractions import Fraction

SEGMENTS = ["CARD", "PLOAN", "AUTO", "MORT", "OVDR", "BNPL"]
MARKET_CCY = {"GB": "GBP", "PL": "PLN", "SE": "SEK", "CZ": "CZK",
              "HU": "HUF", "CH": "CHF", "DK": "DKK", "NO": "NOK"}
MARKETS = list(MARKET_CCY)
GROUP_A = ("GB", "PL", "SE", "CZ")
EXCLUSION_ORDER = ["WINDOW", "WITHDRAWN", "DUPLICATE", "NO_SCORE", "STAFF",
                   "LEGAL_HOLD", "INSOLVENCY", "REDRESS", "DECEASED", "FRAUD",
                   "CENSORED", "INSUFFICIENT", "INDETERMINATE"]
COHORT_START = (2025, 1)
COHORT_END = (2025, 6)
EPOCH = _dt.datetime(1970, 1, 1)
DAY = 86400


def ym_index(y, m):
    return y * 12 + (m - 1)


def ym_of_index(i):
    return (i // 12, i % 12 + 1)


def ym_str(i):
    y, m = ym_of_index(i)
    return f"{y:04d}-{m:02d}"


def date_of_secs(s):
    return (EPOCH + _dt.timedelta(seconds=s)).date()


def secs_of_dt(d):
    return int((d - EPOCH).total_seconds())


def month_end(i):
    y, m = ym_of_index(i)
    return _dt.date(y, m, _cal.monthrange(y, m)[1])


def month_start(i):
    y, m = ym_of_index(i)
    return _dt.date(y, m, 1)


def _last_sunday(y, m):
    d = _dt.date(y, m, _cal.monthrange(y, m)[1])
    return d - _dt.timedelta(days=(d.weekday() + 1) % 7)


def dst_active(ts):
    y = date_of_secs(ts).year
    start = secs_of_dt(_dt.datetime.combine(_last_sunday(y, 3), _dt.time(1, 0)))
    end = secs_of_dt(_dt.datetime.combine(_last_sunday(y, 10), _dt.time(1, 0)))
    return start <= ts < end


def utc_offset(market, ts):
    base = 0 if market == "GB" else 3600
    return base + (3600 if dst_active(ts) else 0)


def local_to_utc(market, local_secs):
    base = 0 if market == "GB" else 3600
    cands = [u for u in (local_secs - base - 3600, local_secs - base)
             if utc_offset(market, u) == local_secs - u]
    if cands:
        return min(cands)
    return local_secs - base


def utc_to_local(market, ts):
    return ts + utc_offset(market, ts)


def iso_utc(ts):
    return (EPOCH + _dt.timedelta(seconds=ts)).strftime("%Y-%m-%dT%H:%M:%SZ")


def frac_round(fr, dp, mode="even"):
    """Round an exact Fraction to dp decimals, returning a fixed-point string."""
    fr = Fraction(fr)
    scale = 10 ** dp
    num = fr.numerator * scale
    den = fr.denominator
    neg = num < 0
    num = abs(num)
    q, r = divmod(num, den)
    twice = 2 * r
    if twice > den or (twice == den and (mode == "up" or q % 2 == 1)):
        q += 1
    if neg and q:
        q = -q
    sign = "-" if q < 0 else ""
    q = abs(q)
    whole, frac = divmod(q, scale)
    return f"{sign}{whole}.{frac:0{dp}d}" if dp else f"{sign}{whole}"


def dec_round(d, dp):
    return str(d.quantize(Decimal(1).scaleb(-dp), rounding=ROUND_HALF_EVEN))


# ---------------------------------------------------------------------------
class Result:
    def __init__(self):
        self.reconciled = False
        self.failed_controls = []
        self.record_total = 0
        self.hash_total = 0
        self.files_checked = 0
        self.exclusions = {}
        self.score_rows = {}
        self.window_rows = {}
        self.cohort = {}


def reconcile(L, R):
    ring = L["ring"]
    declared_rows = {}
    declared_hash = {}
    for _name, info in ring["files"].items():
        for target, kind, value in info["acks"]:
            (declared_rows if kind == "rows" else declared_hash)[target] = value
    failed = set()
    for cid in ring["expected_ids"]:
        info = ring["by_id"].get(cid)
        if info is None:
            failed.add(cid)
            continue
        if declared_rows.get(cid) != info["rows"] or declared_hash.get(cid) != info["hash"]:
            failed.add(cid)
    R.failed_controls = sorted(failed)
    R.files_checked = len(ring["files"])
    R.record_total = sum(info["rows"] for info in ring["files"].values())
    R.hash_total = sum(info["hash"] for info in ring["files"].values())
    R.reconciled = not failed and R.files_checked == len(ring["expected_ids"])


def _resolve_cust(L, cust):
    seen = set()
    cust = L["alias"].get(cust, cust)
    merges = L["merge_map"]
    while cust in merges and cust not in seen:
        seen.add(cust)
        cust = merges[cust]
    return cust


def _approved(L, version, segment, d):
    ok = False
    for ver, segs, start, end in L["approvals"]:
        if ver == version and segment in segs and start <= d and (end is None or d <= end):
            ok = True
    if not ok:
        return False
    for ver, start in L["version_withdrawals"]:
        if ver == version and d >= start:
            return False
    return True


def _business_day(L, market, d):
    return d.weekday() < 5 and d not in L["holidays"].get(market, ())


def run_rules(L, ignore_gate=False):
    R = Result()
    reconcile(L, R)
    if not R.reconciled and not ignore_gate:
        return R
    quarantine = L["quarantine"]
    acct_appid = {acct: app_id for app_id, acct in L["appid_xwalk"].items()}

    # --- applications: final revision per account -------------------------
    final = {}
    for rec in L["apps"]:
        if (rec["file"], rec["recno"]) in quarantine:
            continue
        key = (rec["revision"], rec["received_utc"], rec["order"])
        cur = final.get(rec["acct"])
        if cur is None or key > cur[0]:
            final[rec["acct"]] = (key, rec)
    accounts = {}
    for acct, (_k, rec) in final.items():
        branch = rec["branch"]
        if branch.startswith("BR-"):
            branch = L["branch_xwalk"].get(branch, branch)
        market = None
        if rec["decision_utc"] is not None:
            day = date_of_secs(rec["decision_utc"])
        else:
            day = date_of_secs(rec["decision_local"])
        for mkt, start, end in L["branches"].get(branch, ()):
            if start <= day and (end is None or day <= end):
                market = mkt
        if market is None:
            if ignore_gate:
                continue
            raise ValueError(f"no market for branch {branch} of {acct}")
        if rec["product_code"] not in L["prodmap"] and ignore_gate:
            continue
        if rec["decision_utc"] is not None:
            dec_utc = rec["decision_utc"]
        else:
            dec_utc = local_to_utc(market, rec["decision_local"])
        local = utc_to_local(market, dec_utc)
        ddate = date_of_secs(local)
        code = rec["product_code"]
        if rec["product_basis"] == "current":
            later = sorted((m for m in L["migrations"].get(acct, ()) if m[2] > ddate),
                           key=lambda m: (m[2], m[3]))
            if later:
                code = later[0][0]
        if code not in L["prodmap"] and ignore_gate:
            continue
        accounts[acct] = {
            "acct": acct, "cust": _resolve_cust(L, rec["cust"]),
            "app_id": rec["app_id"] or acct_appid.get(acct),
            "market": market, "product": L["prodmap"][code], "decision_utc": dec_utc,
            "ddate": ddate, "cmonth": ym_index(ddate.year, ddate.month),
            "limit": rec["limit"],
        }
    R.decisions = accounts  # read by plant_tie_fixtures only; no rule below reads it
    R.final_recs = {acct: rec for acct, (_k, rec) in final.items()}

    excl = R.exclusions
    lo = ym_index(*COHORT_START)
    hi = ym_index(*COHORT_END)
    alive = []
    for acct in sorted(accounts):
        a = accounts[acct]
        if not lo <= a["cmonth"] <= hi:
            excl[acct] = "WINDOW"
            continue
        wd = [d for d in L["withdrawals"].get(acct, ()) if 0 <= (d - a["ddate"]).days <= 14]
        if wd and acct not in L["withdrawal_reversed"]:
            excl[acct] = "WITHDRAWN"
            continue
        alive.append(a)

    groups = {}
    for a in alive:
        groups.setdefault((a["cust"], a["product"]), []).append(a)
    survivors = []
    for key in sorted(groups):
        kept = None
        for a in sorted(groups[key], key=lambda x: (x["decision_utc"], x["acct"])):
            if kept is not None and (a["ddate"] - kept["ddate"]).days <= 30:
                excl[a["acct"]] = "DUPLICATE"
            else:
                kept = a
                survivors.append(a)
    survivors.sort(key=lambda x: x["acct"])

    # --- score selection (point in time) -----------------------------------
    by_acct = {}
    for ev in L["scores"]:
        if (ev["file"], ev["recno"]) in quarantine:
            continue
        by_acct.setdefault(ev["acct"], []).append(ev)
    scored = []
    for a in survivors:
        best = None
        for ev in by_acct.get(a["acct"], ()):
            run = L["runs"].get(ev["run_id"])
            if run is None:
                continue
            node, version, status = run
            if status != "OK" or node == "9" or ev["run_id"] in L["void_runs"]:
                continue
            if not _approved(L, version, a["product"], a["ddate"]):
                continue
            ts = ev["score_ts"] + L["skew"].get(ev["run_id"], 0)
            if ts > a["decision_utc"]:
                continue
            key = (ts, ev["event_num"])
            if best is None or key > best[0]:
                best = (key, ev, version, ts)
        if best is None:
            excl[a["acct"]] = "NO_SCORE"
            R.score_rows[a["acct"]] = None
            continue
        _k, ev, version, ts = best
        a["score"] = ev["score"]
        R.score_rows[a["acct"]] = (ev["event_id"], ev["run_id"], version, ts, ev["score"])
        scored.append(a)

    # --- policy exclusions -------------------------------------------------
    intervals = {}
    for emp, starts in L["staff_starts"].items():
        leaves = sorted(L["staff_leaves"].get(emp, ()))
        used = set()
        for cust, start in sorted(starts, key=lambda s: s[1]):
            end = None
            for i, lv in enumerate(leaves):
                if lv > start and i not in used:
                    end = lv
                    used.add(i)
                    break
            intervals.setdefault(_resolve_cust(L, cust), []).append((start, end))
    deceased = {}
    for cust, d in L["deceased"]:
        m = _resolve_cust(L, cust)
        if m not in deceased or d < deceased[m]:
            deceased[m] = d
    fraud = {}
    for case, acct, d in L["fraud_alerts"]:
        if L["fraud_disp"].get(case) == "CONFIRMED":
            if acct not in fraud or d < fraud[acct]:
                fraud[acct] = d
    candidates = []
    for a in scored:
        acct, d = a["acct"], a["ddate"]
        wend = month_end(a["cmonth"] + 12)
        a["wend"] = wend
        if any(s <= d and (e is None or d < e) for s, e in intervals.get(a["cust"], ())):
            excl[acct] = "STAFF"
        elif any(s <= d and (e is None or d <= e) for s, e in L["holds"].get(acct, ())):
            excl[acct] = "LEGAL_HOLD"
        elif acct in L["insolvency"] and L["insolvency"][acct] <= wend:
            excl[acct] = "INSOLVENCY"
        elif acct in L["redress"]:
            excl[acct] = "REDRESS"
        elif a["cust"] in deceased and deceased[a["cust"]] <= wend:
            excl[acct] = "DECEASED"
        elif acct in fraud and fraud[acct] <= wend:
            excl[acct] = "FRAUD"
        else:
            candidates.append(a)

    # --- performance window --------------------------------------------------
    snaps = {}
    certified = L["certified"]
    for rec in L["snaps"]:
        if (rec["file"], rec["recno"]) in quarantine:
            continue
        snaps.setdefault((rec["acct"], rec["month"]), []).append(rec)
    forbear = {}
    for gid, (acct, start, end) in L["forbear_grants"].items():
        if gid in L["forbear_revoked"]:
            continue
        end = max([end] + L["forbear_ext"].get(gid, []))
        forbear.setdefault(acct, set()).update(range(start, end + 1))
    co_events = {}
    for eid, acct, d in L["co_events"]:
        rev = L["co_reversals"].get(eid)
        if rev is not None and (rev - d).days <= 60:
            continue
        co_events.setdefault(acct, []).append(d)
    closures = {}
    for acct, d in L["closures"]:
        if acct not in closures or d < closures[acct]:
            closures[acct] = d
    cohort = []
    for a in candidates:
        acct, c = a["acct"], a["cmonth"]
        threshold = L["thresholds"][a["product"]]
        fb = forbear.get(acct, ())
        valid = {}
        bad_month = None
        max_dpd = 0
        for mo in range(c + 1, c + 13):
            recs = snaps.get((acct, mo))
            want = certified.get((mo, a["market"]))
            recs = [r for r in recs or () if r["file"] == want]
            if not recs:
                continue
            rec = max(recs, key=lambda r: r["recno"])
            dpd, status = rec["dpd"], rec["status"]
            key = (acct, mo)
            if key in L["errata"]:
                dpd = L["errata"][key]
            elif key in L["xml_corr"]:
                dpd = L["xml_corr"][key]
            elif key in L["mail_corr"]:
                dpd = L["mail_corr"][key]
            elif key in L["system_error"]:
                dpd = 0
            if dpd is None:
                continue
            eff = 0 if mo in fb else dpd
            valid[mo] = eff
            max_dpd = max(max_dpd, eff)
            if (eff >= threshold or status == "CO") and bad_month is None:
                bad_month = mo
        for d in co_events.get(acct, ()):
            if a["ddate"] < d <= a["wend"]:
                mo = ym_index(d.year, d.month)
                if bad_month is None or mo < bad_month:
                    bad_month = mo
        closed = closures.get(acct)
        last_required = c + 12
        if closed is not None:
            last_required = min(last_required, ym_index(closed.year, closed.month))
        if bad_month is not None:
            outcome = "BAD"
        elif any(mo not in valid for mo in range(c + 1, last_required + 1)):
            outcome = "CENSORED"
        elif closed is not None and closed < month_start(c + 6):
            outcome = "INSUFFICIENT"
        elif max_dpd >= 30:
            outcome = "INDETERMINATE"
        else:
            outcome = "GOOD"
        R.window_rows[acct] = (ym_str(c + 1), ym_str(c + 12), len(valid), max_dpd,
                               ym_str(bad_month) if bad_month is not None else "", outcome)
        if outcome in ("CENSORED", "INSUFFICIENT", "INDETERMINATE"):
            excl[acct] = outcome
            continue
        a["bad"] = 1 if outcome == "BAD" else 0
        if acct in L["audit"]:
            a["bad"] = 1 if L["audit"][acct] == "BAD" else 0
        cohort.append(a)

    # --- weights and exposure ------------------------------------------------
    for a in cohort:
        acct = a["acct"]
        pi = L["pi_override"].get(acct)
        if pi is None:
            pi = L["pi"].get(acct)
        if pi is None and a["app_id"] is not None:
            pi = L["pi_by_appid"].get(a["app_id"])
        if pi is None:
            if ignore_gate:
                continue
            raise ValueError(f"no inclusion probability for {acct}")
        w = 1 / Fraction(pi)
        if w.denominator != 1:
            if ignore_gate:
                continue
            raise ValueError(f"non-integer weight for {acct}")
        a["weight"] = int(w)
        mend = month_end(a["cmonth"])
        limit = a["limit"]
        best = None
        for eff, new_limit, amend_id in L["limit_amends"].get(acct, ()):
            if a["ddate"] <= eff <= mend and (best is None or (eff, amend_id) > best[0]):
                best = ((eff, amend_id), new_limit)
        if best is not None:
            limit = best[1]
        ccy = L["redenom"].get(acct, MARKET_CCY[a["market"]])
        day = mend
        while not _business_day(L, a["market"], day):
            day -= _dt.timedelta(days=1)
        series = L["fx"].get(ccy, ())
        fix = None
        for fdate, eur, per in series:
            if fdate <= day:
                fix = (eur, per)
            else:
                break
        if fix is None:
            if ignore_gate:
                continue
            raise ValueError(f"no fixing for {ccy} on {day}")
        eur, per = fix
        a["exposure"] = (limit * eur / per).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        cuts = L["cuts"][a["product"]]
        band = 1
        for cut in cuts:
            if a["score"] > cut:
                band += 1
        a["band"] = band
        R.cohort[acct] = a
    return R


# ---------------------------------------------------------------------------
def _segment_stats(L, members):
    W = sum(a["weight"] for a in members)
    WB = sum(a["weight"] for a in members if a["bad"])
    WG = W - WB
    exp_total = sum((a["exposure"] * a["weight"] for a in members), Decimal(0))
    exp_bad = sum((a["exposure"] * a["weight"] for a in members if a["bad"]), Decimal(0))
    pop = {
        "accounts": len(members),
        "bads": sum(1 for a in members if a["bad"]),
        "weighted_accounts": W,
        "weighted_bads": WB,
        "bad_rate": frac_round(Fraction(WB, W), 6) if W else None,
        "exposure_eur": str(exp_total.quantize(Decimal("0.01"))),
        "exposure_bad_rate": frac_round(Fraction(exp_bad) / Fraction(exp_total), 6) if exp_total else None,
    }
    by_score = {}
    for a in members:
        g, b = by_score.get(a["score"], (0, 0))
        if a["bad"]:
            b += a["weight"]
        else:
            g += a["weight"]
        by_score[a["score"]] = (g, b)
    scores = sorted(by_score)
    num2 = 0
    good_below = 0
    for s in scores:
        g, b = by_score[s]
        num2 += b * (2 * (WG - good_below - g) + g)
        good_below += g
    auc = Fraction(num2, 2 * WB * WG) if WB and WG else None
    best = None
    cg = cb = 0
    for s in scores:
        g, b = by_score[s]
        cg += g
        cb += b
        diff = abs(Fraction(cb, WB) - Fraction(cg, WG)) if WB and WG else Fraction(0)
        if best is None or diff > best[0]:
            best = (diff, s)
    disc = {
        "auc": frac_round(auc, 6) if auc is not None else None,
        "gini": frac_round(2 * auc - 1, 6) if auc is not None else None,
        "ks": frac_round(best[0], 6) if best else None,
        "ks_score": best[1] if best else None,
    }
    return pop, disc


def _psi(L, seg, members):
    cuts = L["cuts"][seg]
    dev = [0] * 10
    for (s_seg, score), count in L["dev"].items():
        if s_seg != seg:
            continue
        band = 1 + sum(1 for c in cuts if score > c)
        dev[band - 1] += count
    act = [0] * 10
    for a in members:
        act[a["band"] - 1] += a["weight"]
    dev_total = sum(dev)
    act_total = sum(act)
    floor = Decimal("0.0001")
    bins = []
    with localcontext() as ctx:
        ctx.prec = 50
        total = Decimal(0)
        for i in range(10):
            e = Decimal(dev[i]) / Decimal(dev_total)
            a = Decimal(act[i]) / Decimal(act_total)
            ef, af = max(e, floor), max(a, floor)
            total += (af - ef) * (af / ef).ln()
            bins.append({"band": i + 1, "expected": dec_round(e, 6), "actual": dec_round(a, 6)})
        return {"psi": dec_round(total, 6), "bins": bins}


def _calibration_rows(L, seg, members):
    rows = []
    for band in range(1, 11):
        mem = [a for a in members if a["band"] == band]
        W = sum(a["weight"] for a in mem)
        WB = sum(a["weight"] for a in mem if a["bad"])
        expected = sum((Fraction(L["calib"][(seg, a["score"])]) * a["weight"] for a in mem), Fraction(0))
        rows.append([seg, band, len(mem), W, WB, frac_round(expected, 6),
                     frac_round(Fraction(WB, W), 6) if W else "",
                     frac_round(expected / W, 6) if W else ""])
    return rows


def _csv(header, rows):
    out = [",".join(header)]
    for row in rows:
        out.append(",".join("" if v is None else str(v) for v in row))
    return ("\n".join(out) + "\n").encode("utf-8")


def _js(obj):
    return (_json.dumps(obj, indent=2, sort_keys=True) + "\n").encode("utf-8")


OUTPUT_NAMES = ["cohort.csv", "exclusions.csv", "score_selection.csv", "performance_windows.csv",
                "population_summary.json", "discrimination.json", "psi.json", "calibration.csv",
                "reconciliation.json"]


def render_outputs(L, R):
    status = "RECONCILED" if R.reconciled else "UNRECONCILED"
    recon = {"status": status, "files_checked": R.files_checked,
             "failed_controls": R.failed_controls,
             "estate_record_total": R.record_total, "estate_hash_total": R.hash_total}
    hdr = {
        "cohort.csv": ["acct", "segment", "market", "cohort_month", "decision_utc", "score",
                       "score_band", "bad", "weight", "exposure_eur"],
        "exclusions.csv": ["acct", "reason"],
        "score_selection.csv": ["acct", "event_id", "run_id", "model_version", "score_ts_utc", "score"],
        "performance_windows.csv": ["acct", "window_start", "window_end", "months_observed",
                                    "max_dpd", "bad_month", "outcome"],
        "calibration.csv": ["segment", "band", "accounts", "weighted_accounts", "weighted_bads",
                            "expected_bads", "actual_rate", "expected_rate"],
    }
    if not R.reconciled:
        out = {name: _csv(cols, []) for name, cols in hdr.items()}
        for name in ("population_summary.json", "discrimination.json", "psi.json"):
            out[name] = _js({"status": status, "segments": {}})
        out["reconciliation.json"] = _js(recon)
        return out
    cohort = [R.cohort[k] for k in sorted(R.cohort)]
    out = {}
    out["cohort.csv"] = _csv(hdr["cohort.csv"], [
        [a["acct"], a["product"], a["market"], ym_str(a["cmonth"]), iso_utc(a["decision_utc"]),
         a["score"], a["band"], a["bad"], a["weight"], a["exposure"]] for a in cohort])
    out["exclusions.csv"] = _csv(hdr["exclusions.csv"], [[k, R.exclusions[k]] for k in sorted(R.exclusions)])
    rows = []
    for k in sorted(R.score_rows):
        v = R.score_rows[k]
        rows.append([k, "", "", "", "", ""] if v is None else [k, v[0], v[1], v[2], iso_utc(v[3]), v[4]])
    out["score_selection.csv"] = _csv(hdr["score_selection.csv"], rows)
    out["performance_windows.csv"] = _csv(hdr["performance_windows.csv"],
                                          [[k, *R.window_rows[k]] for k in sorted(R.window_rows)])
    pop_all, disc_all = {}, {}
    psi_all = {}
    cal_rows = []
    for seg in SEGMENTS + ["ALL"]:
        members = [a for a in cohort if seg == "ALL" or a["product"] == seg]
        pop, disc = _segment_stats(L, members)
        pop_all[seg] = pop
        disc_all[seg] = disc
        if seg != "ALL":
            psi_all[seg] = _psi(L, seg, members)
            cal_rows.extend(_calibration_rows(L, seg, members))
    out["population_summary.json"] = _js({"status": status, "segments": pop_all})
    out["discrimination.json"] = _js({"status": status, "segments": disc_all})
    out["psi.json"] = _js({"status": status, "segments": psi_all})
    out["calibration.csv"] = _csv(hdr["calibration.csv"], cal_rows)
    out["reconciliation.json"] = _js(recon)
    return out


