D = _dt.date


def wchoice(rng, pairs):
    total = sum(w for _, w in pairs)
    x = rng.random() * total
    for v, w in pairs:
        x -= w
        if x < 0:
            return v
    return pairs[-1][0]


def easter(y):
    a = y % 19
    b, c = divmod(y, 100)
    d, e = divmod(b, 4)
    f = (b + 8) // 25
    g = (b - f + 1) // 3
    h = (19 * a + b - d - g + 15) % 30
    i, k = divmod(c, 4)
    l_ = (32 + 2 * e + 2 * i - h - k) % 7
    m = (a + 11 * h + 22 * l_) // 451
    month = (h + l_ - 7 * m + 114) // 31
    day = (h + l_ - 7 * m + 114) % 31 + 1
    return D(y, month, day)


def market_holidays(y):
    """Return {market: [(date, name, category)]} for one year."""
    e = easter(y)
    gf, em = e - _dt.timedelta(days=2), e + _dt.timedelta(days=1)
    asc, wm = e + _dt.timedelta(days=39), e + _dt.timedelta(days=50)
    cc = e + _dt.timedelta(days=60)

    def first_monday(m):
        d = D(y, m, 1)
        return d + _dt.timedelta(days=(7 - d.weekday()) % 7)

    def last_monday(m):
        d = D(y, m, _cal.monthrange(y, m)[1])
        return d - _dt.timedelta(days=d.weekday())

    midsummer = next(D(y, 6, dd) for dd in range(19, 26) if D(y, 6, dd).weekday() == 4)
    H = {
        "GB": [(D(y, 1, 1), "New Year's Day"), (gf, "Good Friday"), (em, "Easter Monday"),
               (first_monday(5), "Early May bank holiday"), (last_monday(5), "Spring bank holiday"),
               (last_monday(8), "Summer bank holiday"), (D(y, 12, 25), "Christmas Day"),
               (D(y, 12, 26), "Boxing Day")],
        "PL": [(D(y, 1, 1), "Nowy Rok"), (D(y, 1, 6), "Trzech Kroli"), (em, "Poniedzialek Wielkanocny"),
               (D(y, 5, 1), "Swieto Pracy"), (D(y, 5, 3), "Swieto Konstytucji"), (cc, "Boze Cialo"),
               (D(y, 8, 15), "Wniebowziecie"), (D(y, 11, 1), "Wszystkich Swietych"),
               (D(y, 11, 11), "Swieto Niepodleglosci"), (D(y, 12, 25), "Boze Narodzenie"),
               (D(y, 12, 26), "Drugi dzien Swiat")],
        "SE": [(D(y, 1, 1), "Nyarsdagen"), (D(y, 1, 6), "Trettondedag jul"), (gf, "Langfredagen"),
               (em, "Annandag pask"), (D(y, 5, 1), "Forsta maj"), (asc, "Kristi himmelsfard"),
               (D(y, 6, 6), "Nationaldagen"), (midsummer, "Midsommarafton"),
               (D(y, 12, 24), "Julafton"), (D(y, 12, 25), "Juldagen"), (D(y, 12, 26), "Annandag jul"),
               (D(y, 12, 31), "Nyarsafton")],
        "CZ": [(D(y, 1, 1), "Novy rok"), (gf, "Velky patek"), (em, "Velikonocni pondeli"),
               (D(y, 5, 1), "Svatek prace"), (D(y, 5, 8), "Den vitezstvi"), (D(y, 7, 5), "Cyril a Metodej"),
               (D(y, 7, 6), "Jan Hus"), (D(y, 9, 28), "Den ceske statnosti"), (D(y, 10, 28), "Vznik statu"),
               (D(y, 11, 17), "Den boje za svobodu"), (D(y, 12, 24), "Stedry den"),
               (D(y, 12, 25), "1. svatek vanocni"), (D(y, 12, 26), "2. svatek vanocni")],
        "HU": [(D(y, 1, 1), "Ujev"), (D(y, 3, 15), "Nemzeti unnep"), (gf, "Nagypentek"),
               (em, "Husvethetfo"), (D(y, 5, 1), "A munka unnepe"), (wm, "Punkosdhetfo"),
               (D(y, 8, 20), "Allamalapitas"), (D(y, 10, 23), "Nemzeti unnep okt"),
               (D(y, 11, 1), "Mindenszentek"), (D(y, 12, 25), "Karacsony"), (D(y, 12, 26), "Karacsony 2")],
        "CH": [(D(y, 1, 1), "Neujahr"), (D(y, 1, 2), "Berchtoldstag"), (gf, "Karfreitag"),
               (em, "Ostermontag"), (asc, "Auffahrt"), (wm, "Pfingstmontag"), (D(y, 8, 1), "Bundesfeier"),
               (D(y, 12, 25), "Weihnachten"), (D(y, 12, 26), "Stephanstag")],
        "DK": [(D(y, 1, 1), "Nytarsdag"), (e - _dt.timedelta(days=3), "Skaertorsdag"), (gf, "Langfredag"),
               (em, "2. paskedag"), (asc, "Kristi himmelfartsdag"),
               (asc + _dt.timedelta(days=1), "Bankernes lukkedag"), (wm, "2. pinsedag"),
               (D(y, 6, 5), "Grundlovsdag"), (D(y, 12, 24), "Juleaften"), (D(y, 12, 25), "Juledag"),
               (D(y, 12, 26), "2. juledag"), (D(y, 12, 31), "Nytarsaften")],
        "NO": [(D(y, 1, 1), "Forste nyttarsdag"), (e - _dt.timedelta(days=3), "Skjaertorsdag"),
               (gf, "Langfredag"), (em, "Andre paskedag"), (D(y, 5, 1), "Arbeidernes dag"),
               (D(y, 5, 17), "Grunnlovsdag"), (asc, "Kristi himmelfartsdag"), (wm, "Andre pinsedag"),
               (D(y, 12, 25), "Forste juledag"), (D(y, 12, 26), "Andre juledag")],
    }
    return H


class World:
    def __init__(self, seed, scale):
        self.seed = seed
        self.scale = scale
        self.rng = _random.Random(seed)
        self.recs = {name: [] for name, *_ in FILES}
        self.meta = {name: {"type": t, "kind": k, "decoy": dc} for name, t, k, dc in FILES}
        self.traps = []          # semantic traps: dicts
        self.docs = {}
        self.L = None
        self.facts = {}

    def n(self, x, lo=40):
        return max(lo, int(round(x * self.scale)))

    def trap_codes_all(self):
        if not hasattr(self, "_codes"):
            self._codes = {}
        return self._codes

    def cap_for(self, file, base):
        return base + getattr(self, "cap_adj", {}).get(file, 0)

    def trap_codes(self, file):
        if not hasattr(self, "_codes"):
            self._codes = {}
        return self._codes.setdefault(file, set())

    def trap(self, file, family, code, recno=None, accts=(), impact=None, desc="", rule="", direction=""):
        self.trap_codes(file).add(code)
        self.traps.append({"file": file, "family": family, "code": code, "recno": recno,
                           "accts": list(accts), "impact": impact, "desc": desc, "rule": rule,
                           "direction": direction})


def _digits(rng, used, lo=1000000, hi=9999999):
    while True:
        v = rng.randint(lo, hi)
        if v not in used:
            used.add(v)
            return v


def acct_id(v):
    return f"AC{v:07d}"


def cust_id(v):
    return f"CU{v:07d}"


def build_world(seed, scale=1.0):
    W = World(seed, scale)
    rng = W.rng
    used_acct, used_cust, used_misc = set(), set(), set()
    F = W.facts

    # ---------------- calendars -------------------------------------------
    hol = {m: {} for m in MARKETS}
    for y in range(1990, 2036):
        for mkt, rows in market_holidays(y).items():
            for d, name in rows:
                hol[mkt][d] = (name, "PUBLIC-HOLIDAY")
    # special bank closures and observances that do not close the market
    hol["CZ"][D(2025, 3, 31)] = ("Core banking migration closure", "BANK-CLOSURE")
    hol["HU"][D(2025, 1, 31)] = ("Settlement system cut-over", "BANK-CLOSURE")
    hol["SE"][D(2025, 4, 30)] = ("Valborgsmassoafton", "OBSERVANCE")
    hol["NO"][D(2025, 6, 30)] = ("Bank staff observance", "OBSERVANCE")
    hol["PL"][D(2025, 2, 28)] = ("Tlusty czwartek", "OBSERVANCE")
    F["holidays"] = hol
    W.L_holidays = {m: {d for d, (_n, cat) in v.items() if cat != "OBSERVANCE"} for m, v in hol.items()}

    target_closed = set()
    for y in range(2023, 2027):
        e = easter(y)
        target_closed |= {D(y, 1, 1), e - _dt.timedelta(days=2), e + _dt.timedelta(days=1),
                          D(y, 5, 1), D(y, 12, 25), D(y, 12, 26)}
    fx_days = []
    d = D(2024, 1, 1)
    while d <= D(2026, 6, 30):
        if d.weekday() < 5 and d not in target_closed:
            fx_days.append(d)
        d += _dt.timedelta(days=1)
    fx = {}
    for ccy, base in EUR_RATE.items():
        per = 100 if ccy == "HUF" else 1
        level = base * per
        series = []
        for i, day in enumerate(fx_days):
            level *= 1 + (rng.random() - 0.5) * 0.008
            series.append((day, Decimal(f"{level:.6f}"), per))
        fx[ccy] = series
    # publication gaps: the treasury did not publish a fixing on these days
    gaps = {("HUF", D(2025, 3, 31)), ("PLN", D(2025, 6, 30)), ("SEK", D(2025, 1, 31)),
            ("CHF", D(2025, 4, 30)), ("NOK", D(2025, 2, 28))}
    for ccy in fx:
        fx[ccy] = [row for row in fx[ccy] if (ccy, row[0]) not in gaps]
    F["fx"] = fx
    F["fx_gaps"] = sorted(gaps)

    # ---------------- branches ----------------------------------------------
    branches = {}       # old code -> list of (market, start, end)
    branch_rows = []
    by_market = {m: [] for m in MARKETS}
    used_b = set()
    nb = W.n(5200, 300)
    reused = []
    for i in range(nb):
        mkt = wchoice(rng, MKT_SHARE)
        code = f"B{_digits(rng, used_b, 10000, 99999):05d}"
        start = D(1990 + rng.randint(0, 30), rng.randint(1, 12), rng.randint(1, 28))
        end = None
        if rng.random() < 0.08:
            end = D(2016 + rng.randint(0, 7), rng.randint(1, 12), rng.randint(1, 28))
            if rng.random() < 0.5:
                reused.append((code, end))
        branches[code] = [(mkt, start, end)]
        if end is None:
            by_market[mkt].append(code)
    for code, end in reused:
        old_mkt = branches[code][0][0]
        new_mkt = rng.choice([m for m in MARKETS if m != old_mkt])
        start2 = end + _dt.timedelta(days=rng.randint(30, 400))
        branches[code].append((new_mkt, start2, None))
        by_market[new_mkt].append(code)
    F["branches"] = branches
    F["reused_branches"] = [c for c, _ in reused]
    xwalk = {}
    used_nb = set()
    for code in branches:
        xwalk[f"BR-{_digits(rng, used_nb, 10000, 99999):05d}"] = code
    F["branch_xwalk"] = xwalk
    old_to_new = {v: k for k, v in xwalk.items()}
    F["old_to_new"] = old_to_new

    # ---------------- product codes -----------------------------------------
    prodmap = {}
    codes_by_product = {p: [] for p in SEGMENTS}
    used_pc = set()
    for p in SEGMENTS:
        for _ in range(W.n(860, 60)):
            v = _digits(rng, used_pc, 1000, 9999)
            code = f"{CODE_PREFIX[p]}-{v:04d}{rng.choice('ABCDEFGH')}"
            prodmap[code] = p
            codes_by_product[p].append(code)
    F["prodmap"] = prodmap
    active_codes = {p: codes_by_product[p][:max(8, len(codes_by_product[p]) // 6)] for p in SEGMENTS}

    # ---------------- customers -----------------------------------------------
    alias = {}
    merges = []           # (merged, survivor, status, decided, source)
    legacy_cust = {}

    # ---------------- cohort accounts -----------------------------------------
    accts = []
    month_days = {m: _cal.monthrange(2025, m)[1] for m in range(1, 7)}

    def new_account(cm, day=None, secs=None, market=None, product=None):
        mkt = market or wchoice(rng, MKT_SHARE)
        prod = product or wchoice(rng, SEG_SHARE)
        y, mo = cm
        if day is None:
            day = rng.randint(1, _cal.monthrange(y, mo)[1])
        if secs is None:
            secs = rng.randint(7 * 3600, 22 * 3600)
        local = secs_of_dt(_dt.datetime(y, mo, day)) + secs
        utc = local_to_utc(mkt, local)
        local_raw = local
        a = {"acct": acct_id(_digits(rng, used_acct)), "cust": cust_id(_digits(rng, used_cust)),
             "market": mkt, "product": prod, "decision_utc": utc, "local": utc_to_local(mkt, utc),
             "branch": rng.choice(by_market[mkt]), "code": rng.choice(active_codes[prod])}
        a["local_raw"] = local_raw
        a["ddate"] = date_of_secs(a["local"])
        a["cmonth"] = ym_index(a["ddate"].year, a["ddate"].month)
        pd = SEG_BASE_PD[prod] * _math.exp(rng.random() * 2.4 - 1.2)
        pd = min(0.6, pd)
        a["pd"] = pd
        logit = _math.log(pd / (1 - pd))
        score = int(round(760 - 70 * (logit + 2.7) + (rng.random() - 0.5) * 70))
        a["score"] = max(300, min(1199, score))
        a["bad_intent"] = rng.random() < pd * 1.3
        ccy = MARKET_CCY[mkt]
        lo_, hi_ = LIMIT_EUR[prod]
        eur = lo_ + (hi_ - lo_) * rng.random() ** 2
        a["ccy"] = ccy
        if mkt in ("PL", "HU") and prod in ("MORT", "AUTO") and rng.random() < 0.35:
            a["ccy"] = "CHF"
        local_limit = eur / EUR_RATE[a["ccy"]]
        if prod in ("MORT", "AUTO", "PLOAN"):
            local_limit = round(local_limit, -2)
        a["limit"] = Decimal(f"{local_limit:.2f}")
        a["app_id"] = f"APP{_digits(rng, used_misc, 10000000, 99999999):08d}"
        a["pi"] = wchoice(rng, [(Fraction(1), 30), (Fraction(1, 2), 25), (Fraction(1, 4), 25),
                                (Fraction(1, 5), 12), (Fraction(1, 8), 8)])
        a["file_month"] = mo if (y, mo) in [(2025, k) for k in range(1, 7)] else None
        a["notes"] = []
        return a

    for mo in range(1, 7):
        for _ in range(W.n(5600, 60)):
            a = new_account((2025, mo))
            a["file_month"] = mo
            accts.append(a)
        # boundary accounts recorded in this month's partition file
        for _ in range(W.n(25, 3)):
            if mo == 1:
                a = new_account((2024, 12), day=31, secs=rng.randint(22 * 3600, 24 * 3600 - 60))
            elif mo == 6:
                a = new_account((2025, 7), day=1, secs=rng.randint(0, 2 * 3600))
            else:
                a = new_account((2025, mo), day=month_days[mo], secs=rng.randint(23 * 3600, 24 * 3600 - 30))
            a["file_month"] = mo
            a["notes"].append("boundary")
            accts.append(a)
        if mo == 3:
            # decisions recorded inside the spring-forward gap (local 02:00-03:00)
            for _ in range(W.n(12, 2)):
                a = new_account((2025, 3), day=30, secs=2 * 3600 + rng.randint(0, 3599),
                                market=rng.choice(["PL", "CZ", "HU", "SE"]))
                a["file_month"] = 3
                a["notes"].append("dst_gap")
                accts.append(a)
    # UTC/local boundary for the 2025-06 partition: GB late evening stays June, CET early July leaves
    for _ in range(W.n(15, 2)):
        a = new_account((2025, 6), day=30, secs=rng.randint(23 * 3600, 24 * 3600 - 60), market="GB")
        a["file_month"] = 6
        a["notes"].append("boundary")
        accts.append(a)

    # duplicate applications from the same person (entity resolution)
    dup_sets = []
    base_pool = [a for a in accts if "boundary" not in a["notes"]]
    for a in rng.sample(base_pool, W.n(1300, 8)):
        chain = [a]
        hops = 2 if rng.random() < 0.22 else 1
        for _h in range(hops):
            prev = chain[-1]
            gap = rng.choice([rng.randint(1, 30), rng.randint(1, 30), rng.randint(31, 45), 30, 31])
            nd = prev["ddate"] + _dt.timedelta(days=gap)
            if nd > D(2025, 6, 29):
                break
            b = new_account((nd.year, nd.month), day=nd.day, market=prev["market"], product=prev["product"])
            b["file_month"] = nd.month
            b["notes"].append("dup_of:" + prev["acct"])
            mode = rng.random()
            if mode < 0.35:
                b["cust"] = a["cust"]
            elif mode < 0.65:
                al = cust_id(_digits(rng, used_cust))
                alias[al] = a["cust"]
                b["cust"] = al
            else:
                mg = cust_id(_digits(rng, used_cust))
                status = "APPROVED" if rng.random() < 0.85 else rng.choice(["REJECTED", "PENDING"])
                src = "docx" if rng.random() < 0.6 else "tsv"
                merges.append((mg, a["cust"], status, D(2025, rng.randint(1, 12), rng.randint(1, 28)) if src == "docx"
                               else D(2026, rng.randint(1, 5), rng.randint(1, 28)), src))
                b["cust"] = mg
            chain.append(b)
            accts.append(b)
        dup_sets.append(chain)
    F["dup_sets"] = dup_sets

    acct_by_id = {a["acct"]: a for a in accts}
    W.accts = accts
    W.acct_by_id = acct_by_id
    cohort_like = [a for a in accts if a["cmonth"] >= ym_index(2025, 1) and a["cmonth"] <= ym_index(2025, 6)]

    # noise population (other books of the bank) for bank-wide registers
    other_accts = [acct_id(_digits(rng, used_acct)) for _ in range(W.n(60000, 600))]
    other_custs = [cust_id(_digits(rng, used_cust)) for _ in range(W.n(40000, 400))]

    # alias noise and chained merges for the customer master
    for _ in range(W.n(5200, 60)):
        alias[cust_id(_digits(rng, used_cust))] = rng.choice(other_custs)
    for _ in range(W.n(10600, 120)):
        mg, sv = cust_id(_digits(rng, used_cust)), rng.choice(other_custs)
        src = "docx" if rng.random() < 0.5 else "tsv"
        merges.append((mg, sv, wchoice(rng, [("APPROVED", 80), ("REJECTED", 12), ("PENDING", 8)]),
                       D(2024 + (src == "tsv") + (src == "tsv"), rng.randint(1, 5), rng.randint(1, 28)), src))
    # a merge whose survivor is itself merged later (transitive chain)
    for a in rng.sample(cohort_like, W.n(60, 3)):
        new_master = cust_id(_digits(rng, used_cust))
        merges.append((a["cust"], new_master, "APPROVED", D(2026, 2, rng.randint(1, 28)), "tsv"))
        a["notes"].append("chain_merge")
    # legacy customer ids in the 2026 merge feed, mapped through the ML workbook's legacy sheet
    legacy_used = set()
    for i, (mg, sv, st, dd, src) in enumerate(merges):
        if src == "tsv" and rng.random() < 0.25:
            lc = f"LCU{_digits(rng, legacy_used, 100000, 999999):06d}"
            legacy_cust[lc] = mg
            merges[i] = (lc, sv, st, dd, src)
    for _ in range(W.n(5200, 60)):
        legacy_cust[f"LCU{_digits(rng, legacy_used, 100000, 999999):06d}"] = rng.choice(other_custs)
    F["alias"], F["merges"], F["legacy_cust"] = alias, merges, legacy_cust

    # ---------------- application revisions ---------------------------------
    for a in accts:
        a["rev"] = 1
        a["received"] = a["decision_utc"] + rng.randint(60, 3 * 3600)
        a["apps"] = []   # list of (file, record dict)
    app_recs = {f: [] for f in APP_FILES.values()}
    for a in accts:
        rec = {"acct": a["acct"], "cust": a["cust"], "app_id": a["app_id"], "branch": a["branch"],
               "code": a["code"], "decision_utc": a["decision_utc"], "local": a["local_raw"],
               "market": a["market"], "limit": a["limit"], "rev": 1, "received": a["received"]}
        app_recs[APP_FILES[a["file_month"]]].append(rec)
        a["final_rec"] = rec
    W.superseded = []
    for a in rng.sample(cohort_like, W.n(380, 6)):
        old = dict(a["final_rec"])
        a["final_rec"]["rev"] = 2
        old["rev"] = 1
        old["limit"] = (a["limit"] * Decimal("0.8")).quantize(Decimal("0.01"))
        if rng.random() < 0.4:
            old["branch"] = rng.choice(by_market[a["market"]])
        target = APP_FILES[a["file_month"]] if rng.random() < 0.6 else APP_FILES[rng.randint(1, 6)]
        app_recs[target].append(old)
        W.superseded.append((a["acct"], target))
    resent = set()
    for a in rng.sample(cohort_like, W.n(90, 3)):
        # same revision re-sent later with a corrected limit: the later receipt wins
        resend = dict(a["final_rec"])
        resend["received"] = a["final_rec"]["received"] + rng.randint(600, 86400)
        resend["limit"] = (a["limit"] + Decimal("100.00")).quantize(Decimal("0.01"))
        a["limit"] = resend["limit"]
        app_recs[APP_FILES[a["file_month"]]].append(resend)
        resent.add(a["acct"])
    # same revision and same receipt: the later delivery wins, and within one delivery the later record
    twins_pool = [a for a in cohort_like if a["acct"] not in resent]
    for a in rng.sample(twins_pool, W.n(120, 8)):
        twin = dict(a["final_rec"])
        twin["limit"] = (a["limit"] + Decimal("200.00")).quantize(Decimal("0.01"))
        if rng.random() < 0.5:
            target = APP_FILES[a["file_month"]]
        else:
            target = APP_FILES[rng.choice([m for m in range(1, 7) if m != a["file_month"]])]
        app_recs[target].append(twin)
    for f in app_recs:
        rng.shuffle(app_recs[f])
    W.app_recs = app_recs

    # current-basis product codes in the 2025-05 workbook (product migrations)
    migrations = []
    used_mig = set()
    for a in accts:
        if rng.random() < 0.06:
            eff = a["ddate"] + _dt.timedelta(days=rng.randint(20, 380))
            to_prod = rng.choice(["PLOAN", a["product"]]) if a["product"] in ("CARD", "OVDR", "BNPL") else a["product"]
            to_code = rng.choice(active_codes[to_prod])
            mid = f"MIG{_digits(rng, used_mig, 100000, 999999):06d}"
            migrations.append((a["acct"], a["code"], to_code, eff, mid))
            if rng.random() < 0.3:
                eff2 = eff + _dt.timedelta(days=rng.randint(10, 200))
                to2 = rng.choice(active_codes[prodmap[to_code]])
                migrations.append((a["acct"], to_code, to2, eff2, f"MIG{_digits(rng, used_mig, 100000, 999999):06d}"))
    # migrations dated before the decision never roll back anything (noise)
    for _ in range(W.n(3300, 40)):
        p = rng.choice(SEGMENTS)
        migrations.append((rng.choice(other_accts), rng.choice(active_codes[p]), rng.choice(active_codes[p]),
                           D(2025, rng.randint(1, 12), rng.randint(1, 28)),
                           f"MIG{_digits(rng, used_mig, 100000, 999999):06d}"))
    F["migrations"] = migrations

    # ---------------- withdrawals ------------------------------------------
    withdrawals = []
    reversed_wd = set()
    for a in cohort_like:
        r = rng.random()
        if r < 0.012:
            withdrawals.append((a["acct"], a["ddate"] + _dt.timedelta(days=rng.choice([0, 3, 7, 13, 14]))))
            if rng.random() < 0.2:
                reversed_wd.add(a["acct"])
        elif r < 0.017:
            withdrawals.append((a["acct"], a["ddate"] + _dt.timedelta(days=rng.choice([15, 20, 40]))))
    for _ in range(W.n(5000, 60)):
        withdrawals.append((rng.choice(other_accts), D(2024 + rng.randint(0, 1), rng.randint(1, 12), rng.randint(1, 28))))
    F["withdrawals"], F["reversed_wd"] = withdrawals, reversed_wd

    # ---------------- scores ------------------------------------------------
    runs = {}            # run_id -> dict(node, version, status, start)
    run_key = {}
    used_run = set()
    used_ev = set()

    def get_run(node, version, ts):
        key = (node, version, ts // (2 * 3600))
        rid = run_key.get(key)
        if rid is None:
            rid = f"R{_digits(rng, used_run, 100000, 999999):06d}"
            run_key[key] = rid
            status = "ABORTED" if rng.random() < 0.012 else "OK"
            runs[rid] = {"node": node, "version": version, "status": status,
                         "start": (ts // (2 * 3600)) * 2 * 3600, "events": []}
        return rid

    events = []

    def add_event(a, node, version, true_ts, score, kind):
        rid = get_run(node, version, true_ts)
        num = _digits(rng, used_ev, 100000000, 999999999)
        ev = {"event_id": f"EV{num:09d}", "event_num": num, "acct": a["acct"], "run_id": rid,
              "version": version, "true_ts": true_ts, "score": max(300, min(1199, score)),
              "node": node, "kind": kind, "market": a["market"]}
        runs[rid]["events"].append(ev)
        events.append(ev)
        return ev

    node_w = [("1", 12), ("2", 12), ("3", 12), ("4", 13), ("5", 12), ("6", 11), ("7", 11),
              ("8", 13), ("BF", 6)]
    for a in accts:
        d = a["ddate"]
        r = rng.random()
        if a["product"] in ("CARD", "BNPL") and d >= D(2025, 2, 1) and r < 0.45:
            ver = "v4.0.1"
        elif a["product"] in ("CARD", "PLOAN", "OVDR") and d >= D(2025, 3, 1) and r < 0.6:
            ver = "v4.0.2"
        else:
            ver = "v4.0.0"
        if rng.random() < 0.006:
            ver = "v4.0.1" if a["product"] not in ("CARD", "BNPL") else "v4.0.2"
            a["notes"].append("unapproved_version")
        node = wchoice(rng, node_w)
        lag = rng.randint(5, 900)
        if rng.random() < 0.01:
            lag = -rng.randint(1, 90)          # decision score logged after the decision instant
            a["notes"].append("late_decision_score")
        add_event(a, node, ver, a["decision_utc"] - lag, a["score"], "decision")
        if rng.random() < 0.45:
            off = rng.randint(3600, 10 * 86400)
            if rng.random() < 0.02:
                off = lag                      # exact tie with the decision score
                a["notes"].append("tie")
            add_event(a, wchoice(rng, node_w), "v4.0.0", a["decision_utc"] - off,
                      a["score"] + rng.randint(-40, 40), "prelim")
        if rng.random() < 0.62:
            later = a["decision_utc"] + rng.randint(86400, 300 * 86400)
            if rng.random() < 0.5:
                add_event(a, "8C", "v4.1-rc", later, a["score"] + rng.randint(-60, 60), "rescore")
            else:
                add_event(a, wchoice(rng, node_w), "v4.0.0", later, a["score"] + rng.randint(-50, 50), "rescore")
        if rng.random() < 0.08:
            add_event(a, "8C", "v4.0.0", a["decision_utc"] - rng.randint(1800, 5 * 86400),
                      a["score"] + rng.randint(-30, 30), "prelim_c")

    # minimum density per score source
    target = W.n(5150, 45)
    file_of_node = lambda ev: NODE_FILES.get(ev["node"]) if ev["node"] != "8" else None

    def node8_file(ev):
        if ev["true_ts"] < secs_of_dt(_dt.datetime(2025, 4, 1)):
            return "score_batches_2025_q1.jsonl"
        return "score_batches_2025_q2_a.jsonl" if int(ev["run_id"][1:]) % 2 else "score_batches_2025_q2_b.jsonl"

    def ev_file(ev):
        return node8_file(ev) if ev["node"] == "8" else NODE_FILES[ev["node"]]

    counts = {}
    for ev in events:
        counts[ev_file(ev)] = counts.get(ev_file(ev), 0) + 1
    score_files = [f for f in set(NODE_FILES.values()) if f != NODE_FILES["9"]] + [
        "score_batches_2025_q1.jsonl", "score_batches_2025_q2_a.jsonl", "score_batches_2025_q2_b.jsonl"]
    early = [a for a in accts if a["decision_utc"] < secs_of_dt(_dt.datetime(2025, 3, 1))]
    apr1 = secs_of_dt(_dt.datetime(2025, 4, 1))
    for f in sorted(score_files):
        guard = 0
        while counts.get(f, 0) < target and guard < 50 * target:
            guard += 1
            if f in NODE_FILES.values():
                node = next(k for k, v in NODE_FILES.items() if v == f)
            else:
                node = "8"
            if f == "score_batches_2025_q1.jsonl":
                a = rng.choice(early)
                ts = rng.randint(a["decision_utc"] + 86400, apr1 - 3600)
            else:
                a = rng.choice(accts)
                ts = max(a["decision_utc"] + rng.randint(86400, 200 * 86400), apr1 + 3600)
            ev = add_event(a, node, "v4.1-rc" if node == "8C" else "v4.0.0", ts,
                           a["score"] + rng.randint(-50, 50), "filler")
            if ev_file(ev) != f:
                events.pop()
                runs[ev["run_id"]]["events"].pop()
                continue
            counts[f] = counts.get(f, 0) + 1

    # clock skew on nodes 3 and 6 (recorded = true - offset)
    skew = {}
    for rid, run in runs.items():
        if run["node"] in ("3", "6"):
            skew[rid] = rng.choice([o for o in range(-900, 901, 15) if o != 0])
    for ev in events:
        ev["rec_ts"] = ev["true_ts"] - skew.get(ev["run_id"], 0)
    # voided runs (published only by the DR replay host) and replays of node 4
    candidate_runs = sorted(r for r, v in runs.items() if v["node"] != "9" and v["status"] == "OK")
    void_runs = set(rng.sample(candidate_runs, max(3, len(candidate_runs) * 15 // 1000)))
    replays = []
    for ev in events:
        if ev["node"] == "4" and rng.random() < 0.97:
            rid = get_run("9", ev["version"], ev["true_ts"] + 30 * 86400)
            rep = dict(ev)
            rep["run_id"] = rid
            rep["node"] = "9"
            if rng.random() < 0.05:
                rep["score"] = max(300, min(1199, ev["score"] + rng.randint(-25, 25)))
            replays.append(rep)
    F["runs"], F["skew"], F["void_runs"] = runs, skew, void_runs
    W.events, W.replays = events, replays
    # skew corrections cover every run in the cycle (zero where the node clock was sound)
    F["skew_rows"] = sorted(runs)

    # ---------------- policy registers ------------------------------------
    staff_starts, staff_leaves = {}, {}
    used_emp = set()

    def new_emp():
        return f"E{_digits(rng, used_emp, 100000, 999999):06d}"

    for a in cohort_like:
        r = rng.random()
        if r < 0.010:
            e = new_emp()
            cust = a["cust"]
            if rng.random() < 0.3:
                al = cust_id(_digits(rng, used_cust))
                alias[al] = a["cust"]
                cust = al
            staff_starts[e] = [(cust, a["ddate"] - _dt.timedelta(days=rng.randint(30, 3000)))]
            if rng.random() < 0.5:
                staff_leaves[e] = [a["ddate"] + _dt.timedelta(days=rng.choice([1, 40, 300]))]
        elif r < 0.015:
            e = new_emp()
            staff_starts[e] = [(a["cust"], a["ddate"] - _dt.timedelta(days=rng.randint(400, 3000)))]
            staff_leaves[e] = [a["ddate"] - _dt.timedelta(days=rng.choice([0, 0, 5, 100]))]
        elif r < 0.018:
            e = new_emp()
            s1 = a["ddate"] - _dt.timedelta(days=2000)
            staff_starts[e] = [(a["cust"], s1), (a["cust"], a["ddate"] - _dt.timedelta(days=rng.randint(0, 200)))]
            staff_leaves[e] = [s1 + _dt.timedelta(days=700)]
        elif r < 0.020:
            e = new_emp()
            staff_starts[e] = [(a["cust"], a["ddate"] + _dt.timedelta(days=rng.randint(1, 90)))]
    while len(staff_starts) < W.n(5200, 60):
        e = new_emp()
        s = D(2000 + rng.randint(0, 25), rng.randint(1, 12), rng.randint(1, 28))
        staff_starts[e] = [(rng.choice(other_custs), s)]
        if rng.random() < 0.97:
            staff_leaves.setdefault(e, []).append(s + _dt.timedelta(days=rng.randint(100, 4000)))
    leave_rows = sum(len(v) for v in staff_leaves.values())
    pool = sorted(staff_starts)
    while leave_rows < W.n(5100, 50):
        e = rng.choice(pool)
        s = max(st for _c, st in staff_starts[e])
        staff_leaves.setdefault(e, []).append(s + _dt.timedelta(days=rng.randint(5000, 9000)))
        leave_rows += 1
    F["staff_starts"], F["staff_leaves"] = staff_starts, staff_leaves

    holds = []
    for a in cohort_like:
        r = rng.random()
        if r < 0.006:
            holds.append((a["acct"], a["ddate"] - _dt.timedelta(days=rng.randint(0, 200)),
                          rng.choice([None, a["ddate"], a["ddate"] + _dt.timedelta(days=rng.randint(1, 400))])))
        elif r < 0.009:
            holds.append((a["acct"], a["ddate"] + _dt.timedelta(days=rng.choice([1, 20])), None))
        elif r < 0.011:
            holds.append((a["acct"], a["ddate"] - _dt.timedelta(days=300), a["ddate"] - _dt.timedelta(days=1)))
    while len(holds) < W.n(5100, 60):
        s = D(2018 + rng.randint(0, 7), rng.randint(1, 12), rng.randint(1, 28))
        holds.append((rng.choice(other_accts), s, rng.choice([None, s + _dt.timedelta(days=rng.randint(10, 900))])))
    F["holds"] = holds

    insolvency, redress, audit = {}, set(), {}
    for a in cohort_like:
        wend = month_end(a["cmonth"] + 12)
        r = rng.random()
        if r < 0.005:
            insolvency[a["acct"]] = a["ddate"] + _dt.timedelta(days=rng.randint(10, (wend - a["ddate"]).days))
        elif r < 0.007:
            insolvency[a["acct"]] = wend + _dt.timedelta(days=rng.choice([1, 30]))
        r = rng.random()
        if r < 0.005:
            redress.add(a["acct"])
    while len(insolvency) < W.n(5100, 60):
        insolvency[rng.choice(other_accts)] = D(2020 + rng.randint(0, 6), rng.randint(1, 12), rng.randint(1, 28))
    while len(redress) < W.n(5100, 60):
        redress.add(rng.choice(other_accts))
    F["insolvency"], F["redress"] = insolvency, redress

    deceased_reg, deceased_feed, deceased_civil = [], [], []
    for a in cohort_like:
        wend = month_end(a["cmonth"] + 12)
        r = rng.random()
        cust = a["cust"]
        if r < 0.004:
            d = a["ddate"] + _dt.timedelta(days=rng.randint(5, (wend - a["ddate"]).days))
            (deceased_reg if d.year == 2025 and rng.random() < 0.5 else deceased_feed).append((cust, d))
        elif r < 0.0055:
            deceased_feed.append((cust, wend + _dt.timedelta(days=rng.randint(1, 60))))
        elif r < 0.0065:
            deceased_civil.append((cust, a["ddate"] + _dt.timedelta(days=rng.randint(5, 200))))
    while len(deceased_reg) < W.n(5100, 60):
        deceased_reg.append((rng.choice(other_custs), D(2015 + rng.randint(0, 10), rng.randint(1, 12), rng.randint(1, 28))))
    while len(deceased_feed) < W.n(5100, 60):
        deceased_feed.append((rng.choice(other_custs), D(2025 + rng.randint(0, 1), rng.randint(1, 6), rng.randint(1, 28))))
    F["deceased_reg"], F["deceased_feed"], F["deceased_civil"] = deceased_reg, deceased_feed, deceased_civil

    used_case = set()
    alerts25, alerts26, disp = [], [], {}
    for a in cohort_like:
        wend = month_end(a["cmonth"] + 12)
        r = rng.random()
        if r < 0.032:
            case = f"FC{_digits(rng, used_case, 1000000, 9999999):07d}"
            if r < 0.010:
                status, d = "CONFIRMED", a["ddate"] + _dt.timedelta(days=rng.randint(1, (wend - a["ddate"]).days))
            elif r < 0.012:
                status, d = "CONFIRMED", wend + _dt.timedelta(days=rng.randint(1, 90))
            elif r < 0.029:
                status, d = "CLEARED", a["ddate"] + _dt.timedelta(days=rng.randint(1, 300))
            else:
                status, d = "OPEN", a["ddate"] + _dt.timedelta(days=rng.randint(1, 300))
            (alerts25 if d.year == 2025 else alerts26).append((case, a["acct"], d))
            disp[case] = status
    while len(alerts25) < W.n(5100, 60):
        case = f"FC{_digits(rng, used_case, 1000000, 9999999):07d}"
        alerts25.append((case, rng.choice(other_accts), D(2025, rng.randint(1, 12), rng.randint(1, 28))))
        disp[case] = wchoice(rng, [("CONFIRMED", 30), ("CLEARED", 60), ("OPEN", 10)])
    while len(alerts26) < W.n(5100, 60):
        case = f"FC{_digits(rng, used_case, 1000000, 9999999):07d}"
        alerts26.append((case, rng.choice(other_accts), D(2026, rng.randint(1, 6), rng.randint(1, 28))))
        disp[case] = wchoice(rng, [("CONFIRMED", 30), ("CLEARED", 60), ("OPEN", 10)])
    F["alerts25"], F["alerts26"], F["disp"] = alerts25, alerts26, disp

    # ---------------- closures ------------------------------------------------
    closures25, closures26 = [], []
    for a in accts:
        c = a["cmonth"]
        r = rng.random()
        a["closure"] = None
        if a["bad_intent"]:
            continue
        if r < 0.03:
            k = rng.randint(c + 1, c + 5)
            y, m = ym_of_index(k)
            a["closure"] = D(y, m, rng.randint(1, _cal.monthrange(y, m)[1]))
        elif r < 0.034:
            a["closure"] = month_start(c + 6)
        elif r < 0.074:
            k = rng.randint(c + 6, c + 12)
            y, m = ym_of_index(k)
            a["closure"] = D(y, m, rng.randint(1, _cal.monthrange(y, m)[1]))
        if a["closure"] is not None:
            (closures25 if a["closure"].year == 2025 else closures26).append((a["acct"], a["closure"]))
    while len(closures25) < W.n(5100, 60):
        closures25.append((rng.choice(other_accts), D(2025, rng.randint(1, 12), rng.randint(1, 28))))
    while len(closures26) < W.n(5100, 60):
        closures26.append((rng.choice(other_accts), D(2026, rng.randint(1, 6), rng.randint(1, 28))))
    F["closures25"], F["closures26"] = closures25, closures26

    # ---------------- snapshot paths ------------------------------------------
    last_month = ym_index(2026, 6)
    paths = {}
    co_events = []
    used_co = set()
    grants, extensions, revoked = {}, {}, {}
    used_g = set()
    W.censor_drop = []
    for a in accts:
        c = a["cmonth"]
        months = [m for m in range(c + 1, c + 13) if m <= last_month]
        if a["closure"] is not None:
            k = ym_index(a["closure"].year, a["closure"].month)
            months = [m for m in months if m <= k]
        p = {m: [0, "OPEN"] for m in months}
        for m in months:
            if rng.random() < 0.05:
                p[m][0] = rng.randint(1, 29)
        thr = 60 if a["product"] == "BNPL" else 90
        a["trigger"] = None
        if a["bad_intent"] and months:
            t = rng.choice(months[2:] or months)
            kind = wchoice(rng, [("dpd", 70), ("co_status", 15), ("co_event", 15)])
            idx = months.index(t)
            if kind == "dpd":
                for j, val in zip(range(idx - 3, idx + 1), (30, 60, 90 if thr == 90 else 60, 90 + rng.randint(0, 60))):
                    if j >= 0:
                        p[months[j]][0] = val
                for j in range(idx + 1, len(months)):
                    p[months[j]][0] = min(360, p[months[j - 1]][0] + 30) if rng.random() < 0.8 else 0
                if rng.random() < 0.25:
                    gid = f"FB{_digits(rng, used_g, 100000, 999999):06d}"
                    lo_i = max(0, idx - 3)
                    mode = rng.random()
                    end_i = len(months) - 1
                    for j in range(idx + 1, len(months)):
                        p[months[j]][0] = 0
                    hi_i = min(end_i, idx + 1)
                    if mode < 0.4:
                        grants[gid] = (a["acct"], months[lo_i], months[hi_i])
                        a["notes"].append("forbear_full")
                    elif mode < 0.75:
                        grants[gid] = (a["acct"], months[lo_i], months[max(lo_i, idx - 1)])
                        extensions.setdefault(gid, []).append(months[hi_i])
                        a["notes"].append("forbear_ext")
                    else:
                        grants[gid] = (a["acct"], months[lo_i], months[hi_i])
                        revoked[gid] = date_of_secs(a["decision_utc"]) + _dt.timedelta(days=200)
                        a["notes"].append("forbear_revoked")
            elif kind == "co_status":
                p[t][0] = 999
                p[t][1] = "CO"
                for j in range(idx + 1, len(months)):
                    del p[months[j]]
                y, m = ym_of_index(t)
                eid = f"CO{_digits(rng, used_co, 1000000, 9999999):07d}"
                co_events.append((eid, a["acct"], D(y, m, rng.randint(1, _cal.monthrange(y, m)[1]))))
            else:
                p[t][0] = 60
                y, m = ym_of_index(t)
                eid = f"CO{_digits(rng, used_co, 1000000, 9999999):07d}"
                co_events.append((eid, a["acct"], D(y, m, rng.randint(1, _cal.monthrange(y, m)[1]))))
                a["notes"].append("co_event_only")
                a["co_eid"] = eid
            a["trigger"] = (kind, t)
        elif months and rng.random() < 0.09:
            s = rng.choice(months)
            peak = rng.choice([30, 30, 60, 60, 75] if a["product"] == "BNPL" else [30, 30, 60, 89])
            p[s][0] = peak
            if rng.random() < 0.15:
                gid = f"FB{_digits(rng, used_g, 100000, 999999):06d}"
                grants[gid] = (a["acct"], s, s)
                a["notes"].append("forbear_indet")
        if months and not a["bad_intent"] and rng.random() < 0.016:
            req = [m for m in months]
            gone = rng.choice(req)
            mode = rng.choice(["drop", "sentinel", "quarantine"])
            if mode == "drop":
                del p[gone]
            elif mode == "sentinel":
                p[gone][0] = -1
            W.censor_drop.append((a["acct"], gone, mode))
            a["notes"].append("censor_" + mode)
        if a["closure"] is not None:
            k = ym_index(a["closure"].year, a["closure"].month)
            if k in p:
                p[k][1] = "CLOSED"
        paths[a["acct"]] = p
    # charge-off reversals: only the consolidated events feed carries them
    co_reversals = {}
    for a in accts:
        if "co_event_only" in a["notes"]:
            r = rng.random()
            eid = a["co_eid"]
            d = next(x[2] for x in co_events if x[0] == eid)
            if r < 0.22:
                co_reversals[eid] = d + _dt.timedelta(days=rng.choice([1, 30, 60]))
            elif r < 0.30:
                co_reversals[eid] = d + _dt.timedelta(days=rng.choice([61, 120]))
    co_all = list(co_events)
    while len([x for x in co_all if x[2].year == 2025]) < W.n(5100, 60):
        co_all.append((f"CO{_digits(rng, used_co, 1000000, 9999999):07d}", rng.choice(other_accts),
                       D(2025, rng.randint(1, 12), rng.randint(1, 28))))
    while len([x for x in co_all if x[2].year == 2026]) < W.n(5100, 60):
        co_all.append((f"CO{_digits(rng, used_co, 1000000, 9999999):07d}", rng.choice(other_accts),
                       D(2026, rng.randint(1, 6), rng.randint(1, 28))))
    rev_noise = rng.sample(co_all, W.n(5100, 60))
    for eid, _a, d in rev_noise:
        if eid not in co_reversals and eid not in {x[0] for x in co_events}:
            co_reversals[eid] = d + _dt.timedelta(days=rng.randint(1, 200))
    legacy_acct = {}
    used_l = set()
    for eid, acct, d in co_all:
        if d.year == 2025 and rng.random() < 0.3:
            legacy_acct[f"L-{_digits(rng, used_l, 1000000, 9999999):07d}"] = acct
    while len(legacy_acct) < W.n(5100, 60):
        legacy_acct[f"L-{_digits(rng, used_l, 1000000, 9999999):07d}"] = rng.choice(other_accts)
    F["co_all"], F["co_reversals"], F["legacy_acct"] = co_all, co_reversals, legacy_acct
    F["paths"], F["grants"], F["extensions"], F["revoked"] = paths, grants, extensions, revoked
    while len(grants) < W.n(5100, 60):
        m0 = rng.randint(ym_index(2023, 1), ym_index(2026, 3))
        grants[f"FB{_digits(rng, used_g, 100000, 999999):06d}"] = (rng.choice(other_accts), m0, m0 + rng.randint(0, 3))
    gpool = sorted(grants)
    while sum(len(v) for v in extensions.values()) < W.n(5100, 60):
        g = rng.choice(gpool)
        extensions.setdefault(g, []).append(grants[g][2] + rng.randint(1, 4))
    while len(revoked) < W.n(5100, 60):
        # revocations of grants booked in other portfolios of the bank
        revoked[f"FB{_digits(rng, used_g, 100000, 999999):06d}"] = D(2025, rng.randint(1, 12), rng.randint(1, 28))

    # ---------------- corrections -------------------------------------------
    keys = [(a["acct"], m) for a in cohort_like for m in paths[a["acct"]]]
    interesting = [(a["acct"], a["trigger"][1]) for a in cohort_like
                   if a["trigger"] and a["trigger"][0] == "dpd" and a["trigger"][1] in paths[a["acct"]]]
    errata_rows, xml_rows, mail_rows = [], [], []
    used_er = set()
    eday = D(2026, 3, 1)
    for k in rng.sample(interesting, min(len(interesting), W.n(260, 4))):
        errata_rows.append((k, 0, "APPLIED", eday + _dt.timedelta(days=rng.randint(0, 60))))
    for k in rng.sample(keys, W.n(160, 4)):
        errata_rows.append((k, 120, "APPLIED", eday + _dt.timedelta(days=rng.randint(0, 60))))
    for k in rng.sample(interesting, min(len(interesting), W.n(120, 3))):
        errata_rows.append((k, 0, "REJECTED", eday + _dt.timedelta(days=rng.randint(0, 60))))
    # the same key raised twice: the later applied erratum wins
    for k in rng.sample(keys, W.n(40, 2)):
        errata_rows.append((k, 120, "APPLIED", D(2026, 2, 1)))
        errata_rows.append((k, 0, "APPLIED", D(2026, 4, 1)))
    while len(errata_rows) < W.n(5100, 60):
        errata_rows.append(((rng.choice(other_accts), rng.randint(ym_index(2024, 1), last_month)),
                            rng.choice([0, 30, 60, 90]), rng.choice(["APPLIED", "REJECTED"]),
                            eday + _dt.timedelta(days=rng.randint(0, 90))))
    for i, row in enumerate(errata_rows):
        errata_rows[i] = (f"ER-{_digits(rng, used_er, 10000, 99999):05d}",) + row
    seqn = 1000
    for k in rng.sample(interesting, min(len(interesting), W.n(300, 4))):
        seqn += rng.randint(1, 5)
        xml_rows.append((seqn, k, 0))
        if rng.random() < 0.3:
            seqn += rng.randint(1, 5)
            xml_rows.append((seqn, k, 95))
    for k in rng.sample(keys, W.n(200, 4)):
        seqn += rng.randint(1, 5)
        xml_rows.append((seqn, k, rng.choice([0, 120])))
    while len(xml_rows) < W.n(5100, 60):
        seqn += rng.randint(1, 5)
        xml_rows.append((seqn, (rng.choice(other_accts), rng.randint(ym_index(2024, 1), last_month)),
                         rng.choice([0, 30, 60, 90])))
    order = list(range(len(xml_rows)))
    rng.shuffle(order)
    xml_rows = [xml_rows[i] for i in order]
    used_msg = set()
    mail_base = secs_of_dt(_dt.datetime(2026, 1, 5, 9, 0))
    for k in rng.sample(interesting, min(len(interesting), W.n(300, 4))):
        mail_rows.append({"kind": "corr", "key": k, "dpd": 0})
    for k in rng.sample(keys, W.n(220, 4)):
        mail_rows.append({"kind": "corr", "key": k, "dpd": rng.choice([0, 120])})
    while len(mail_rows) < W.n(4400, 50):
        mail_rows.append({"kind": "corr", "key": (rng.choice(other_accts), rng.randint(ym_index(2024, 1), last_month)),
                          "dpd": rng.choice([0, 30, 60])})
    for m in mail_rows:
        m["msgid"] = f"<corr.{_digits(rng, used_msg, 10000000, 99999999)}@servicing.example-bank.eu>"
        m["ts"] = mail_base + rng.randint(0, 120 * 86400)
    corr = [m for m in mail_rows if m["kind"] == "corr"]
    for m in rng.sample(corr, W.n(400, 6)):
        mail_rows.append({"kind": "retract", "target": m["msgid"], "ts": m["ts"] + rng.randint(600, 30 * 86400),
                          "msgid": f"<retract.{_digits(rng, used_msg, 10000000, 99999999)}@servicing.example-bank.eu>"})
    # a later correction for the same key supersedes an earlier one
    for m in rng.sample(corr, W.n(150, 3)):
        mail_rows.append({"kind": "corr", "key": m["key"], "dpd": 0 if m["dpd"] else 120,
                          "ts": m["ts"] + rng.randint(3600, 10 * 86400),
                          "msgid": f"<corr.{_digits(rng, used_msg, 10000000, 99999999)}@servicing.example-bank.eu>"})
    while len(mail_rows) < W.n(5100, 60):
        mail_rows.append({"kind": "chatter", "ts": mail_base + rng.randint(0, 120 * 86400),
                          "msgid": f"<ops.{_digits(rng, used_msg, 10000000, 99999999)}@servicing.example-bank.eu>"})
    mail_rows.sort(key=lambda m: (m["ts"], m["msgid"]))
    F["errata_rows"], F["xml_rows"], F["mail_rows"] = errata_rows, xml_rows, mail_rows

    # ---------------- sampling ------------------------------------------------
    pi_v2_bait = {}
    for a in cohort_like:
        if a["cmonth"] <= ym_index(2025, 5) and rng.random() < 0.05:
            pi_v2_bait[a["acct"]] = rng.choice([Fraction(1), Fraction(1, 2), Fraction(1, 4)])
    pi_override = []
    for a in cohort_like:
        r = rng.random()
        if r < 0.02:
            pi_override.append((a["acct"], rng.choice([Fraction(1), Fraction(1, 2), Fraction(1, 5)]), "APPROVED"))
        elif r < 0.025:
            pi_override.append((a["acct"], rng.choice([Fraction(1, 8), Fraction(1, 4)]), "REJECTED"))
    while len(pi_override) < W.n(5100, 60):
        pi_override.append((rng.choice(other_accts), rng.choice([Fraction(1), Fraction(1, 2)]),
                            rng.choice(["APPROVED", "REJECTED"])))
    future_pi = [(acct_id(_digits(rng, used_acct)), rng.choice([Fraction(1), Fraction(1, 2), Fraction(1, 4)]))
                 for _ in range(W.n(600, 10))]
    F["pi_v2_bait"], F["pi_override"], F["future_pi"] = pi_v2_bait, pi_override, future_pi

    # ---------------- limits and currencies ------------------------------------
    amends_inc, amends_dec = [], []
    used_am = set()
    for a in cohort_like:
        mend = month_end(a["cmonth"])
        r = rng.random()
        if r < 0.05:
            eff = a["ddate"] + _dt.timedelta(days=rng.randint(0, max(0, (mend - a["ddate"]).days)))
            kind = "inc" if rng.random() < 0.6 else "dec"
        elif r < 0.06:
            eff = mend
            kind = "inc"
        elif r < 0.14:
            eff = mend + _dt.timedelta(days=rng.randint(1, 200))
            kind = "inc" if rng.random() < 0.6 else "dec"
        elif r < 0.15:
            eff = a["ddate"] - _dt.timedelta(days=rng.randint(1, 30))
            kind = "dec"
        else:
            continue
        factor = Decimal("1.25") if kind == "inc" else Decimal("0.70")
        new = (a["limit"] * factor).quantize(Decimal("0.01"))
        row = (a["acct"], eff, new, f"LA{_digits(rng, used_am, 1000000, 9999999):07d}")
        (amends_inc if kind == "inc" else amends_dec).append(row)
        if r < 0.05 and rng.random() < 0.2:
            row2 = (a["acct"], eff, (new * Decimal("1.1")).quantize(Decimal("0.01")),
                    f"LA{_digits(rng, used_am, 1000000, 9999999):07d}")
            amends_inc.append(row2)
    while len(amends_inc) < W.n(10300, 120):
        amends_inc.append((rng.choice(other_accts), D(2025, rng.randint(1, 12), rng.randint(1, 28)),
                           Decimal(f"{rng.randint(500, 90000)}.00"), f"LA{_digits(rng, used_am, 1000000, 9999999):07d}"))
    while len(amends_dec) < W.n(5100, 60):
        amends_dec.append((rng.choice(other_accts), D(2025, rng.randint(1, 12), rng.randint(1, 28)),
                           Decimal(f"{rng.randint(200, 50000)}.00"), f"LA{_digits(rng, used_am, 1000000, 9999999):07d}"))
    F["amends_inc"], F["amends_dec"] = amends_inc, amends_dec
    redenom = {}
    for a in accts:
        if a["ccy"] != MARKET_CCY[a["market"]]:
            redenom[a["acct"]] = a["ccy"]
        elif rng.random() < 0.01:
            redenom[a["acct"]] = a["ccy"]
    while len(redenom) < W.n(5100, 60):
        redenom[rng.choice(other_accts)] = rng.choice(["CHF", "EUR", "USD", "GBP"])
    F["redenom"] = redenom

    # ---------------- model documentation -------------------------------------
    shift = {"CARD": 0.0, "PLOAN": 0.25, "AUTO": 0.7, "MORT": 1.2, "OVDR": -0.2, "BNPL": -0.1}
    calib, reissue = {}, {}
    for seg in SEGMENTS:
        for s in range(300, 1200):
            pd = 1 / (1 + _math.exp((s - 610) / 72 + shift[seg]))
            calib[(seg, s)] = f"{pd:.6f}"
            reissue[(seg, s)] = f"{pd * (0.85 + 0.3 * rng.random()):.6f}"
    retro = {}
    for seg in SEGMENTS:
        for s in rng.sample(range(560, 980), W.n(14, 3)):
            retro[(seg, s)] = f"{float(calib[(seg, s)]) * (1.4 + rng.random() * 0.4):.6f}"
    dev = {}
    cuts = {}
    for seg in SEGMENTS:
        base = SEG_BASE_PD[seg]
        mu = 760 - 70 * (_math.log(base / (1 - base)) + 2.7) + rng.randint(-12, 12)
        sd = 55 + rng.randint(-6, 6)
        total = 0
        for s in range(300, 1200):
            cnt = int(round(42000 * _math.exp(-0.5 * ((s - mu) / sd) ** 2) / (sd * 2.5066) * (0.9 + 0.2 * rng.random())))
            dev[(seg, s)] = cnt
            total += cnt
        acc, cl, nxt = 0, [], 1
        for s in range(300, 1200):
            acc += dev[(seg, s)]
            while nxt <= 9 and acc >= total * nxt / 10:
                cl.append(s)
                nxt += 1
        cuts[seg] = cl
    F["calib"], F["reissue"], F["retro"], F["dev"], F["cuts_doc"] = calib, reissue, retro, dev, cuts
    cuts_eff = {k: list(v) for k, v in cuts.items()}
    cuts_eff["MORT"][4] = cuts["MORT"][4] + 7
    F["cuts_eff"] = cuts_eff
    F["thresholds"] = {s: 90 for s in SEGMENTS}
    F["thresholds"]["BNPL"] = 60

    # ---------------- change control and registries -----------------------------
    used_cr = set()

    def cr_id():
        return f"CR-{_digits(rng, used_cr, 10000, 99999):05d}"

    crs = {}
    for key, status in [("E-002", "APPROVED"), ("E-004", "APPROVED"), ("E-006", "REJECTED"),
                        ("E-009", "PENDING"), ("BDS-V5", "DRAFT"), ("REG-V41", "DRAFT"),
                        ("REG-V402-WD", "APPROVED"), ("CAL-REISSUE", "APPROVED"), ("SAMP-V2", "APPROVED"),
                        ("E-011", "APPROVED")]:
        crs[key] = (cr_id(), status)
    F["crs"] = crs
    cr_rows = []
    for key, (cid, status) in crs.items():
        # every governed CR carries a superseded history row first
        cr_rows.append((cid, key, "SUBMITTED", D(2025, 9, rng.randint(1, 28))))
        cr_rows.append((cid, key, status, D(2026, 1, rng.randint(1, 28))))
    while len(cr_rows) < W.n(5100, 60):
        cid = cr_id()
        cr_rows.append((cid, rng.choice(["SCHEMA", "FEED", "REPORT", "MODEL", "ACCESS"]) + f"-{rng.randint(100, 999)}",
                        wchoice(rng, [("APPROVED", 60), ("REJECTED", 15), ("PENDING", 10), ("SUBMITTED", 10), ("DRAFT", 5)]),
                        D(2019 + rng.randint(0, 7), rng.randint(1, 12), rng.randint(1, 28))))
    rng.shuffle(cr_rows)
    F["cr_rows"] = cr_rows
    F["approvals"] = [("v4.0.0", set(SEGMENTS), D(2024, 10, 1), None),
                      ("v4.0.1", {"CARD", "BNPL"}, D(2025, 2, 1), None),
                      ("v4.0.2", {"CARD", "PLOAN", "OVDR"}, D(2025, 3, 1), None)]
    F["withdrawals_ver"] = [("v4.0.2", D(2025, 5, 15))]
    W.cohort_like = cohort_like
    W.other_accts = other_accts
    W.other_custs = other_custs
    return W


# ---------------------------------------------------------------------------
# Assembly: per-file record lists, cross-file registers, controls, and the
# clean logical estate the rule engine consumes.
# ---------------------------------------------------------------------------
EXTRACT_DATE = D(2026, 6, 30)
CYCLE = "2026-Q2-MON"
LOCAL_APP_FILES = {"applications_2025_01.csv", "applications_2025_03.txt", "applications_2025_05.xlsx"}


def current_code(F, acct, code):
    for m in sorted((m for m in F["mig_by_acct"].get(acct, ()) if m[3] <= EXTRACT_DATE), key=lambda m: (m[3], m[4])):
        if m[1] == code:
            code = m[2]
    return code


def assemble(W):
    rng = _random.Random(W.seed ^ 0x5A5A5A)
    F = W.facts
    R = W.recs
    mig_by_acct = {}
    for m in F["migrations"]:
        mig_by_acct.setdefault(m[0], []).append(m)
    F["mig_by_acct"] = mig_by_acct

    # applications -------------------------------------------------------
    for mo, f in APP_FILES.items():
        for rec in W.app_recs[f]:
            r = dict(rec)
            if f == "applications_2025_04.csv":
                r["app_id"] = None
            if f == "applications_2025_05.xlsx":
                r["code"] = current_code(F, r["acct"], r["code"])
            if f == "applications_2025_06.jsonl":
                r["branch"] = F["old_to_new"][r["branch"]]
            r["_h"] = digits_of(r["acct"])
            R[f].append(r)
    april = [a for a in W.accts if a["file_month"] == 4]
    for a in april:
        r = dict(a["final_rec"])
        if rng.random() < 0.04:
            r["limit"] = (r["limit"] * Decimal("1.05")).quantize(Decimal("0.01"))
            W.trap("applications_2025_04_reextract.csv", "T16", "reextract_limit_drift", accts=[a["acct"]],
                   desc="re-extract limit differs from the certified partition", direction="pull")
        elif rng.random() < 0.02:
            r["branch"] = rng.choice(sorted(F["branches"]))
            W.trap("applications_2025_04_reextract.csv", "T16", "reextract_branch_cleansed", accts=[a["acct"]],
                   desc="re-extract carries a cleansed branch", direction="pull")
        r["_h"] = digits_of(r["acct"])
        R["applications_2025_04_reextract.csv"].append(r)
    rng.shuffle(R["applications_2025_04_reextract.csv"])
    for a in W.accts:
        if not (ym_index(2025, 1) <= a["cmonth"] <= ym_index(2025, 6)):
            continue
        r = dict(a["final_rec"])
        r["reversed"] = a["acct"] in F["reversed_wd"]
        if rng.random() < 0.04:
            r["branch"] = rng.choice(sorted(F["branches"]))
            W.trap("applications_master_2025h1.parquet", "T16", "master_branch_drift", accts=[a["acct"]],
                   desc="master extract carries a cleansed branch", direction="pull")
        r["_h"] = digits_of(r["acct"])
        R["applications_master_2025h1.parquet"].append(r)

    # snapshots ------------------------------------------------------------
    def scope_ok(scope, mkt):
        if scope == "ALL":
            return True
        if scope == "A":
            return mkt in GROUP_A
        if scope == "B":
            return mkt not in GROUP_A
        if scope == "A-CZ":
            return mkt in GROUP_A and mkt != "CZ"
        return mkt == scope

    certified = {}
    for ms, parts in SNAP_LAYOUT.items():
        mi = ym_index(int(ms[:4]), int(ms[5:]))
        for f, scope in parts:
            for mkt in MARKETS:
                if scope_ok(scope, mkt):
                    certified[(mi, mkt)] = f
    F["certified"] = certified
    snap_targets = {}
    for a in W.accts:
        p = F["paths"][a["acct"]]
        for mi, (dpd, status) in p.items():
            f = certified.get((mi, a["market"]))
            if f is None:
                continue
            bal = (a["limit"] * Decimal(rng.randint(0, 95)) / 100).quantize(Decimal("0.01"))
            snap_targets.setdefault(f, []).append({"acct": a["acct"], "month": mi, "dpd": dpd,
                                                   "status": status, "balance": bal, "market": a["market"]})
    for f in sorted(set(certified.values())):
        months = sorted({mi for (mi, _m), ff in certified.items() if ff == f})
        mkts = sorted({m for (_mi, m), ff in certified.items() if ff == f})
        for _ in range(W.n(2600, 30)):
            acct = rng.choice(W.other_accts)
            st = "OPEN" if rng.random() < 0.95 else "CLOSED"
            snap_targets[f].append({"acct": acct, "month": rng.choice(months), "dpd": rng.choice([0] * 12 + [15, 30, 60, 90, -1]),
                                    "status": st, "balance": Decimal(rng.randint(0, 9000000)) / 100,
                                    "market": rng.choice(mkts)})
    W.snap_dups = []
    for f, rows in snap_targets.items():
        rng.shuffle(rows)
        out = []
        for r in rows:
            if rng.random() < 0.003:
                early = dict(r)
                early["dpd"] = 0 if r["dpd"] else 95
                out.append(early)
                W.snap_dups.append((f, r["acct"], r["month"]))
            out.append(r)
        if f == "servicing_snapshots_2025q3.db" or f == "servicing_snapshots_2026q1.db":
            pass
        for r in out:
            r["_h"] = digits_of(r["acct"])
        R[f].extend(out)
    # non-certified copies
    def drifted(rows, rate, fname, family="T16"):
        res = []
        for r in rows:
            c = dict(r)
            if rng.random() < rate and c["status"] == "OPEN" and c["dpd"] >= 0:
                c["dpd"] = 0 if c["dpd"] else rng.choice([35, 95])
                W.trap(fname, family, "copy_value_drift", accts=[c["acct"]],
                       desc="non-certified copy disagrees with the certified partition", direction="pull")
            res.append(c)
        return res
    m11 = ym_index(2025, 11)
    rev2 = []
    for a in W.accts:
        if a["market"] in GROUP_A and m11 in F["paths"][a["acct"]]:
            dpd, status = F["paths"][a["acct"]][m11]
            rev2.append({"acct": a["acct"], "month": m11, "dpd": dpd, "status": status,
                         "balance": (a["limit"] * Decimal(rng.randint(0, 95)) / 100).quantize(Decimal("0.01")),
                         "market": a["market"]})
    rev2_cz = [r for r in rev2 if r["market"] == "CZ"]
    rev2_other = drifted([r for r in rev2 if r["market"] != "CZ"], 0.04, "snapshots_2025_11_a_rev2.csv")
    R["snapshots_2025_11_a_rev2.csv"] = [x for x in rev2_cz + rev2_other]
    rng.shuffle(R["snapshots_2025_11_a_rev2.csv"])
    for r in R["snapshots_2025_11_a_rev2.csv"]:
        r["_h"] = digits_of(r["acct"])
    restated = drifted([dict(r) for r in R["snapshots_2025_10_b.tsv"]], 0.04, "snapshots_2025_10_b_restated.tsv")
    syserr = set()
    for r in restated:
        r["reason"] = ""
        if r["dpd"] > 0 and r["status"] == "OPEN" and rng.random() < 0.08:
            r["reason"] = "SYSTEM_ERROR"
            syserr.add((r["acct"], r["month"]))
    for r in rng.sample(restated, max(3, len(restated) // 200)):
        if not r["reason"]:
            r["reason"] = "SYSTEM_ERROR"
            syserr.add((r["acct"], r["month"]))
    F["system_error"] = syserr
    # an applied erratum still prevails over a SYSTEM_ERROR restatement (governance 2.1 and 3.12)
    used_er = {int(row[0][3:]) for row in F["errata_rows"]}
    cohort_ids = {a["acct"] for a in W.cohort_like}
    voided = sorted(k for k in syserr if k[0] in cohort_ids)
    for k in rng.sample(voided, min(len(voided), W.n(60, 6))):
        F["errata_rows"].append((f"ER-{_digits(rng, used_er, 10000, 99999):05d}", k, 120, "APPLIED", D(2026, 6, 1)))
    R["snapshots_2025_10_b_restated.tsv"] = restated
    replica = []
    for f in ("snapshots_2025_08_a.csv", "snapshots_2025_08_b.tsv", "snapshots_2025_09.xlsx", "snapshots_2025_10_a.csv",
              "snapshots_2025_10_b.tsv"):
        for r in drifted([dict(x) for x in R[f]], 0.04, "snapshots_servicing_replica.db"):
            r["_table"] = "snap_" + ym_str(r["month"]).replace("-", "_")
            replica.append(r)
    R["snapshots_servicing_replica.db"] = replica

    # scores ------------------------------------------------------------------
    def ev_file(ev):
        if ev["node"] == "8":
            if ev["true_ts"] < secs_of_dt(_dt.datetime(2025, 4, 1)):
                return "score_batches_2025_q1.jsonl"
            return "score_batches_2025_q2_a.jsonl" if int(ev["run_id"][1:]) % 2 else "score_batches_2025_q2_b.jsonl"
        return NODE_FILES[ev["node"]]
    for ev in sorted(W.events, key=lambda e: (e["rec_ts"], e["event_num"])):
        r = {"event_id": ev["event_id"], "event_num": ev["event_num"], "acct": ev["acct"], "run_id": ev["run_id"],
             "version": ev["version"], "ts": ev["rec_ts"], "score": ev["score"], "market": ev["market"],
             "_h": digits_of(ev["acct"])}
        R[ev_file(ev)].append(r)
    xc = R["score_batches_2025_q2_c.jsonl"]
    used_r = set(F["runs"])
    for k in range(max(3, len(xc) // 400)):
        src = dict(rng.choice(xc))
        src["run_id"] = f"R{_digits(rng, used_r, 100000, 999999):06d}"
        src["event_num"] = 100000000 + k
        src["event_id"] = f"EV{src['event_num']:09d}"
        xc.append(src)
    for r in xc:
        if F["runs"].get(r["run_id"], {}).get("version") == "v4.1-rc" and r["event_num"] % 53 == 0:
            r["version"] = "v4.0.0"
        r["null_acct"] = r["event_num"] % 401 == 7
        if r["null_acct"]:
            r["_h"] = 0
    for f in ("score_events_node5.parquet", "score_events_node7.tsv", "score_events_backfill.csv",
              "score_batches_2025_q2_c.jsonl"):
        rng.shuffle(R[f])
    replay = [{"kind": "SCORE", "event_id": e["event_id"], "event_num": e["event_num"], "acct": e["acct"],
               "run_id": e["run_id"], "version": e["version"], "ts": e["rec_ts"], "score": e["score"],
               "logged": e["true_ts"] + 30 * 86400, "_h": digits_of(e["acct"])} for e in W.replays]
    for rid in sorted(F["void_runs"]):
        run = F["runs"][rid]
        replay.append({"kind": "VOID", "run_id": rid, "logged": run["start"] + 40 * 86400, "_h": digits_of(rid)})
    replay.sort(key=lambda r: (r["logged"], r["run_id"], r.get("event_num", 0)))
    R["scoring_engine_node9.log"] = replay

    # run registers ---------------------------------------------------------
    apr1 = secs_of_dt(_dt.datetime(2025, 4, 1))
    for rid in sorted(F["runs"], key=lambda r: (F["runs"][r]["start"], r)):
        run = F["runs"][rid]
        f = "model_registry_v4.toml" if run["start"] < apr1 else "scoring_runs_2025q2.toml"
        R[f].append({"run_id": rid, "node": run["node"], "version": run["version"], "status": run["status"],
                     "start": run["start"], "_h": digits_of(rid)})
    R["score_clock_skew_corrections.json"] = [{"run_id": rid, "offset": F["skew"].get(rid, 0), "_h": digits_of(rid)}
                                             for rid in sorted(F["runs"])]

    # events ----------------------------------------------------------------
    legacy_rev = {}
    for lid, acct in F["legacy_acct"].items():
        legacy_rev.setdefault(acct, []).append(lid)
    co_ids = {x[0] for x in F["co_all"]}
    for eid, acct, d in F["co_all"]:
        ref = acct
        if d.year == 2025 and acct in legacy_rev and rng.random() < 0.8:
            ref = legacy_rev[acct][0]
        rec = {"eid": eid, "ref": ref, "date": d, "amount": Decimal(rng.randint(100, 900000)) / 100, "_h": digits_of(ref)}
        R["status_events_chargeoff_2025.csv" if d.year == 2025 else "chargeoff_events_2026.parquet"].append(rec)
    for f in ("status_events_chargeoff_2025.csv", "chargeoff_events_2026.parquet"):
        rng.shuffle(R[f])
    R["account_closures_2025.json"] = [{"acct": a, "date": d, "_h": digits_of(a)} for a, d in F["closures25"]]
    R["account_closures_2026h1.csv"] = [{"acct": a, "date": d, "_h": digits_of(a)} for a, d in F["closures26"]]
    for f in ("account_closures_2025.json", "account_closures_2026h1.csv"):
        rng.shuffle(R[f])
    R["fraud_alerts_2025.jsonl"] = [{"case": c, "acct": a, "date": d, "_h": digits_of(c)} for c, a, d in F["alerts25"]]
    R["fraud_alerts_2026.xml"] = [{"case": c, "acct": a, "date": d, "_h": digits_of(c)} for c, a, d in F["alerts26"]]
    for f in ("fraud_alerts_2025.jsonl", "fraud_alerts_2026.xml"):
        rng.shuffle(R[f])
    R["fraud_case_dispositions.json"] = [{"case": c, "status": s, "_h": digits_of(c)} for c, s in sorted(F["disp"].items())]
    R["application_withdrawals.json"] = [{"acct": a, "date": d, "_h": digits_of(a)} for a, d in F["withdrawals"]]
    rng.shuffle(R["application_withdrawals.json"])
    consol = []
    for c, a, d in F["alerts25"] + F["alerts26"]:
        consol.append({"type": "FRAUD", "subject": a, "date": d, "ref": c, "source": "CASE-MGMT"})
    for eid, acct, d in F["co_all"]:
        consol.append({"type": "CHARGEOFF", "subject": acct, "date": d, "ref": eid, "source": "COLLECTIONS"})
    for eid, d in F["co_reversals"].items():
        acct = next((x[1] for x in F["co_all"] if x[0] == eid), None) if False else None
        consol.append({"type": "CO_REVERSAL", "subject": "", "date": d, "ref": eid, "source": "COLLECTIONS"})
    for cust, d in F["deceased_feed"][: len(F["deceased_feed"]) // 2]:
        consol.append({"type": "DECEASED", "subject": cust, "date": d, "ref": "", "source": "BRANCH-NOTICE"})
    for cust, d in F["deceased_civil"]:
        consol.append({"type": "DECEASED", "subject": cust, "date": d, "ref": "", "source": "CIVIL_REGISTRY"})
    rng.shuffle(consol)
    for r in consol:
        r["_h"] = digits_of(r["ref"] or r["subject"])
    R["status_events_consolidated.json"] = consol
    R["deceased_notifications_register.pdf"] = [{"cust": c, "date": d, "_h": digits_of(c)} for c, d in F["deceased_reg"]]
    R["deceased_notifications_feed.xml"] = [{"cust": c, "date": d, "_h": digits_of(c)} for c, d in F["deceased_feed"]]
    rng.shuffle(R["deceased_notifications_register.pdf"])
    rng.shuffle(R["deceased_notifications_feed.xml"])

    # policy registers --------------------------------------------------------
    R["exclusion_policy.docx"] = sorted(
        ({"emp": e, "cust": cust, "date": d, "_h": digits_of(e)} for e, rows in F["staff_starts"].items() for cust, d in rows),
        key=lambda r: (r["emp"], r["date"]))
    R["employee_leavers.tsv"] = [{"emp": e, "date": d, "_h": digits_of(e)} for e, ds in F["staff_leaves"].items() for d in ds]
    rng.shuffle(R["employee_leavers.tsv"])
    used_h = set()
    R["litigation_hold_register.html"] = [{"hold": f"LH{_digits(rng, used_h, 100000, 999999):06d}", "acct": a, "from": s,
                                           "to": e, "_h": digits_of(a)} for a, s, e in F["holds"]]
    rng.shuffle(R["litigation_hold_register.html"])
    R["regulatory_exclusion_letter_2026.pdf"] = [{"acct": a, "date": d, "_h": digits_of(a)}
                                                  for a, d in sorted(F["insolvency"].items())]
    R["consumer_redress_programme.pdf"] = [{"acct": a, "programme": rng.choice(["RDR-FEES-2024", "RDR-APR-2025", "RDR-INS-2023"]),
                                            "_h": digits_of(a)} for a in sorted(F["redress"])]
    audit = {}
    for a in W.cohort_like:
        if rng.random() < 0.012:
            audit[a["acct"]] = "GOOD" if a["bad_intent"] else "BAD"
        elif rng.random() < 0.01:
            audit[a["acct"]] = "BAD" if a["bad_intent"] else "GOOD"
    while len(audit) < W.n(5100, 60):
        audit[rng.choice(W.other_accts)] = rng.choice(["GOOD", "BAD"])
    F["audit"] = audit
    R["audit_label_confirmations.pdf"] = [{"acct": a, "label": l, "_h": digits_of(a)} for a, l in sorted(audit.items())]
    R["customer_merge_decisions.docx"] = [{"merged": m, "survivor": s, "status": st, "date": d, "_h": digits_of(m)}
                                          for m, s, st, d, src in F["merges"] if src == "docx"]
    R["customer_merges_2026.tsv"] = [{"merged": m, "survivor": s, "status": st, "date": d, "_h": digits_of(m)}
                                     for m, s, st, d, src in F["merges"] if src == "tsv"]
    for f in ("customer_merge_decisions.docx", "customer_merges_2026.tsv"):
        R[f].sort(key=lambda r: (r["date"], r["merged"]))
    R["sampling_methodology.docx"] = [{"acct": a, "pi": p, "status": s, "_h": digits_of(a)} for a, p, s in F["pi_override"]]
    rng.shuffle(R["sampling_methodology.docx"])
    R["bad_definition_standard.docx"] = [{"gid": g, "acct": a, "start": s, "end": e, "_h": digits_of(g)}
                                         for g, (a, s, e) in sorted(F["grants"].items())]
    R["forbearance_extensions_register.pdf"] = [{"gid": g, "end": e, "_h": digits_of(g)}
                                                for g, ends in sorted(F["extensions"].items()) for e in ends]
    R["bad_definition_standard_v5.docx"] = [{"gid": g, "date": d, "acct": F["grants"][g][0] if g in F["grants"] else rng.choice(W.other_accts),
                                             "status": "REVOKED", "_h": digits_of(g)} for g, d in sorted(F["revoked"].items())]
    R["limit_management_policy.docx"] = [{"acct": a, "date": d, "limit": l, "id": i, "_h": digits_of(a)}
                                         for a, d, l, i in F["amends_dec"]]
    R["limit_amendments_2025.xlsx"] = [{"acct": a, "date": d, "limit": l, "id": i, "_h": digits_of(a),
                                        "_sheet": "H1" if d <= D(2025, 6, 30) else "H2"} for a, d, l, i in F["amends_inc"]]
    for f in ("limit_management_policy.docx", "limit_amendments_2025.xlsx"):
        rng.shuffle(R[f])
    R["product_migrations_2025.xlsx"] = [{"acct": a, "from": fc, "to": tc, "date": d, "id": i, "_h": digits_of(a)}
                                         for a, fc, tc, d, i in F["migrations"]]
    rng.shuffle(R["product_migrations_2025.xlsx"])

    # sampling ---------------------------------------------------------------
    groups = {"sampling_inclusion_gb_pl_se.yaml": ("GB", "PL", "SE"), "sampling_inclusion_cz_hu_ch.yaml": ("CZ", "HU", "CH"),
              "sampling_inclusion_dk_no.yaml": ("DK", "NO")}
    pi_acct, pi_app = {}, {}
    for a in W.accts:
        if not (ym_index(2025, 1) <= a["cmonth"] <= ym_index(2025, 6)):
            continue
        if a["cmonth"] == ym_index(2025, 6):
            R["sampling_design_v2.yaml"].append({"key": a["acct"], "pi": a["pi"], "cohort": "2025-06", "market": a["market"],
                                                 "_h": digits_of(a["acct"])})
            pi_acct[a["acct"]] = a["pi"]
            continue
        f = next(k for k, v in groups.items() if a["market"] in v)
        if a["cmonth"] == ym_index(2025, 4):
            R[f].append({"key": a["app_id"], "pi": a["pi"], "cohort": "2025-04", "market": a["market"],
                         "_h": digits_of(a["app_id"])})
            pi_app[a["app_id"]] = a["pi"]
        else:
            R[f].append({"key": a["acct"], "pi": a["pi"], "cohort": ym_str(a["cmonth"]), "market": a["market"],
                         "_h": digits_of(a["acct"])})
            pi_acct[a["acct"]] = a["pi"]
    for acct, p in F["pi_v2_bait"].items():
        a = W.acct_by_id[acct]
        R["sampling_design_v2.yaml"].append({"key": acct, "pi": p, "cohort": ym_str(a["cmonth"]), "market": a["market"],
                                             "_h": digits_of(acct)})
    for acct, p in F["future_pi"]:
        R["sampling_design_v2.yaml"].append({"key": acct, "pi": p, "cohort": "2026-01", "market": rng.choice(MARKETS),
                                             "_h": digits_of(acct)})
    for f in list(groups) + ["sampling_design_v2.yaml"]:
        rng.shuffle(R[f])
    F["pi_acct"], F["pi_app"] = pi_acct, pi_app

    # currencies and treasury ------------------------------------------------
    iso_num = {"GBP": "826", "PLN": "985", "SEK": "752", "CZK": "203", "HUF": "348", "CHF": "756", "DKK": "208",
               "NOK": "578", "EUR": "978", "USD": "840", "JPY": "392", "CAD": "124", "AUD": "036", "RON": "946",
               "BGN": "975", "ISK": "352", "TRY": "949", "CNY": "156", "INR": "356", "BRL": "986", "MXN": "484",
               "ZAR": "710", "KRW": "410", "SGD": "702", "HKD": "344", "NZD": "554", "THB": "764", "ILS": "376",
               "PHP": "608", "IDR": "360", "MYR": "458", "RSD": "941", "UAH": "980"}
    F["iso_num"] = iso_num
    R["currency_redenomination.ini"] = [{"acct": a, "ccy": c, "_h": digits_of(a)} for a, c in sorted(F["redenom"].items())]
    fx_rows = []
    for ccy, series in sorted(F["fx"].items()):
        for day, eur, per in series:
            fx_rows.append({"ccy": ccy, "date": day, "eur": eur, "per": per, "rev": 1, "_h": digits_of(day.isoformat())})
    # superseded fixings: a revision 2 corrects the published value
    final_fx = {(r["ccy"], r["date"]): r for r in fx_rows}
    for r in rng.sample(fx_rows, max(4, len(fx_rows) // 150)):
        wrong = dict(r)
        wrong["eur"] = (r["eur"] * Decimal("1.02")).quantize(Decimal("0.000001"))
        corrected = dict(r)
        corrected["rev"] = 2
        r.update(wrong)
        fx_rows.append(corrected)
    rng.shuffle(fx_rows)
    R["treasury_fixings_2024_2026.xml"] = fx_rows
    ecb = []
    for ccy, series in sorted(F["fx"].items()):
        lookup = {d: (e, p) for d, e, p in series}
        cur = None
        day = D(2024, 1, 1)
        while day <= D(2026, 6, 30):
            if day in lookup:
                e, p = lookup[day]
                cur = (Decimal(p) / e).quantize(Decimal("0.0001"))
            if cur is not None:
                ecb.append({"ccy": ccy, "date": day, "rate": cur, "_h": digits_of(day.isoformat())})
            day += _dt.timedelta(days=1)
    R["fx_rates_ecb_mirror.xml"] = ecb
    W.ecb_codes = sorted(iso_num.items())

    # customer master ------------------------------------------------------------
    custs = sorted({a["cust"] for a in W.accts} | set(W.other_custs[: W.n(6000, 60)]))
    R["customer_master.db"] = ([{"_table": "customers", "cust": c, "since": D(1995 + rng.randint(0, 29), rng.randint(1, 12), 1),
                                 "_h": digits_of(c)} for c in custs] +
                               [{"_table": "customer_alias", "alias": al, "master": m, "_h": digits_of(al)}
                                for al, m in sorted(F["alias"].items())])
    R["merge_candidates_ml.xlsx"] = []
    used_mc = set()
    for _ in range(W.n(5200, 60)):
        a, b = rng.choice(custs), rng.choice(custs)
        R["merge_candidates_ml.xlsx"].append({"_sheet": "candidates", "cand": f"MC{_digits(rng, used_mc, 100000, 999999):06d}",
                                              "a": a, "b": b, "p": Decimal(rng.randint(500, 999)) / 1000,
                                              "_h": digits_of(a)})
    for a in rng.sample(W.cohort_like, W.n(80, 3)):
        partner = cust_id(_digits(rng, set(), 1000000, 9999999))
        R["merge_candidates_ml.xlsx"].append({"_sheet": "candidates", "cand": f"MC{_digits(rng, used_mc, 100000, 999999):06d}",
                                              "a": partner, "b": a["cust"], "p": Decimal("0.995"), "_h": digits_of(partner)})
        W.trap("merge_candidates_ml.xlsx", "T16", "ml_candidate_not_decision", accts=[a["acct"]],
               desc="high-score ML candidate that was never decided", direction="pull")
    for lc, c in sorted(F["legacy_cust"].items()):
        R["merge_candidates_ml.xlsx"].append({"_sheet": "legacy_refs", "legacy": lc, "cust": c, "_h": digits_of(lc)})

    # reference crosswalks ------------------------------------------------------
    R["product_code_crosswalk.ini"] = [{"code": c, "product": p, "_h": digits_of(c)} for c, p in sorted(F["prodmap"].items())]
    R["legacy_account_map.ini"] = [{"legacy": l, "acct": a, "_h": digits_of(l)} for l, a in sorted(F["legacy_acct"].items())]
    rows = []
    for code, spans in sorted(F["branches"].items()):
        for mkt, s, e in spans:
            rows.append({"code": code, "market": mkt, "from": s, "to": e, "_h": digits_of(code)})
    rows.sort(key=lambda r: (r["market"], r["code"], r["from"]))
    R["branch_directory.html"] = rows
    bnames = ["Hauptstraße", "København City", "Göteborg Centrum", "Zürich Paradeplatz", "Kraków Rynek",
              "Brno Střed", "Győr", "Tromsø", "Manchester Deansgate"]
    R["branch_directory_2026.html"] = [{"new": n, "old": o, "market": ("NORDIC" if F["branches"][o][-1][0] in ("SE", "DK", "NO")
                                                                      else F["branches"][o][-1][0]),
                                        "bname": bnames[digits_of(n) % len(bnames)], "opened": D(2026, 1, 1 + digits_of(n) % 28),
                                        "bstatus": "MERGED" if digits_of(o) % 17 == 0 else "ACTIVE", "_h": digits_of(n)}
                                       for n, o in sorted(F["branch_xwalk"].items())]

    # model documentation -----------------------------------------------------
    R["model_documentation_v4.pdf"] = [{"seg": s, "score": sc, "pd": F["calib"][(s, sc)], "_h": sc}
                                       for s in SEGMENTS for sc in range(300, 1200)]
    R["calibration_reissue_2026.pdf"] = ([{"_part": "reissue", "seg": s, "score": sc, "pd": F["reissue"][(s, sc)], "_h": sc}
                                          for s in SEGMENTS for sc in range(300, 1200)] +
                                         [{"_part": "reissue", "seg": "SME", "score": sc, "pd": "0.050000", "_h": sc}
                                          for sc in range(600, 640)] +
                                         [{"_part": "retro", "seg": s, "score": sc, "pd": pd, "_h": sc}
                                          for (s, sc), pd in sorted(F["retro"].items(), key=lambda kv: (kv[0][1] % 7, kv[0]))] +
                                         [{"_part": "retro", "seg": "AUTO", "score": 1250, "pd": "0.000100", "_h": 1250}])
    first = sorted(F["retro"].items())[0]
    R["calibration_reissue_2026.pdf"].insert(len(R["calibration_reissue_2026.pdf"]) - len(F["retro"]) - 1,
                                             {"_part": "retro", "seg": first[0][0], "score": first[0][1], "pd": "0.999999",
                                              "_h": first[0][1]})
    R["monitoring_spec_v4.md"] = [{"seg": s, "score": sc, "count": F["dev"][(s, sc)], "_h": sc}
                                  for s in SEGMENTS for sc in range(300, 1200)]
    R["model_registry_v4_1.toml"] = [{"seg": s, "score": sc, "pd": F["reissue"][(s, sc)], "_h": sc}
                                     for s in SEGMENTS for sc in range(300, 1200)]
    for sc in range(300, 1200, 97):
        R["model_registry_v4_1.toml"].append({"seg": "CARD", "score": sc, "pd": F["calib"][("CARD", sc)], "_h": sc})
    R["governance_precedence_policy.docx"] = [{"cr": c, "subject": k, "status": st, "date": d, "_h": digits_of(c)}
                                              for c, k, st, d in F["cr_rows"]]

    # corrections -------------------------------------------------------------
    R["errata_register.md"] = [{"id": i, "acct": k[0], "month": k[1], "dpd": v, "status": st, "date": d, "_h": digits_of(i)}
                               for i, k, v, st, d in F["errata_rows"]]
    R["snapshot_corrections_feed.xml"] = [{"seq": s, "acct": k[0], "month": k[1], "dpd": v, "_h": digits_of(k[0])}
                                          for s, k, v in F["xml_rows"]]
    R["ops_corrections.mbox"] = [dict(m, _h=digits_of(m["msgid"])) for m in F["mail_rows"]]

    # calendar ------------------------------------------------------------------
    hol_rows = []
    for mkt in MARKETS:
        for d, (name, cat) in sorted(F["holidays"][mkt].items()):
            hol_rows.append({"market": mkt, "date": d, "name": name, "cat": cat, "_h": digits_of(d.isoformat())})
        for y in range(2015, 2031):
            for mo in range(1, 13):
                d = D(y, mo, 15)
                hol_rows.append({"market": mkt, "date": d, "name": "Settlement cut-off", "cat": "SETTLEMENT-CUTOFF",
                                 "time": "16:30", "_h": digits_of(d.isoformat())})
    merged = []
    by_key = {(r["market"], r["date"]): r for r in hol_rows if r["cat"] == "PUBLIC-HOLIDAY"}
    drop = set()
    for mkt in ("DK", "SE", "CZ"):
        for y in range(1990, 2036):
            days = [D(y, 12, 24), D(y, 12, 25), D(y, 12, 26)]
            if all((mkt, d) in by_key for d in days):
                drop |= {(mkt, d) for d in days}
                merged.append({"market": mkt, "date": days[0], "end": D(y, 12, 27), "name": "Christmas closure",
                               "cat": "PUBLIC-HOLIDAY", "_h": digits_of(days[0].isoformat())})
    hol_rows = [r for r in hol_rows if not (r["cat"] == "PUBLIC-HOLIDAY" and (r["market"], r["date"]) in drop)] + merged
    rng.shuffle(hol_rows)
    R["market_holidays.ics"] = hol_rows

    # natural record order: sheet by sheet, table by table in name order
    sheet_rank = {"A": 0, "B": 1, "H1": 0, "H2": 1, "candidates": 0, "legacy_refs": 1}
    for f in ("snapshots_2025_05.xlsx", "snapshots_2025_09.xlsx", "snapshots_2025_12.xlsx", "snapshots_2026_03.xlsx"):
        R[f].sort(key=lambda r: 0 if r["market"] in GROUP_A else 1)
    for f in ("limit_amendments_2025.xlsx", "merge_candidates_ml.xlsx"):
        R[f].sort(key=lambda r: sheet_rank[r["_sheet"]])
    R["customer_master.db"].sort(key=lambda r: r["_table"])
    R["snapshots_servicing_replica.db"].sort(key=lambda r: r["_table"])

    # data quality log (record-level quarantine) ---------------------------------
    pos = {}
    for f, rows in R.items():
        for i, r in enumerate(rows):
            r["_recno"] = i + 1
    for f in set(certified.values()):
        for r in R[f]:
            pos[(f, r["acct"], r["month"])] = r["_recno"]
    dq = []
    used_dq = set()
    quarantine = set()
    for acct, mo, mode in W.censor_drop:
        a = W.acct_by_id[acct]
        f = certified.get((mo, a["market"]))
        if mode == "quarantine" and f and (f, acct, mo) in pos:
            dq.append((f, pos[(f, acct, mo)], "QUARANTINE"))
    ev_pos = {}
    for f in [x for x in R if W.meta[x]["kind"] == "SCORE"]:
        for r in R[f]:
            ev_pos[r["event_id"]] = (f, r["_recno"])
    for ev in rng.sample([e for e in W.events if e["kind"] == "decision"], W.n(160, 3)):
        dq.append(ev_pos[ev["event_id"]] + ("QUARANTINE",))
    app_pos = []
    for f in APP_FILES.values():
        for r in R[f]:
            if r["rev"] == 2:
                app_pos.append((f, r["_recno"]))
    for f, rn in rng.sample(app_pos, min(len(app_pos), W.n(25, 2))):
        dq.append((f, rn, "QUARANTINE"))
    data_files = [n for n, *_ in FILES if W.meta[n]["kind"] in ("SNAP", "SCORE", "APP") and R[n]]
    while len(dq) < W.n(5100, 60):
        f = rng.choice(data_files)
        rn = rng.randint(1, len(R[f]))
        disp = wchoice(rng, [("ACCEPTED", 55), ("FIXED-IN-SOURCE", 35), ("QUARANTINE", 10)])
        if disp == "QUARANTINE":
            r = R[f][rn - 1]
            if W.meta[f]["kind"] == "APP" or r.get("acct") in W.acct_by_id:
                continue
        dq.append((f, rn, disp))
    rng.shuffle(dq)
    seen_q = set()
    R["data_quality_issue_log.md"] = []
    for f, rn, disp in dq:
        if disp == "QUARANTINE":
            if (f, rn) in seen_q:
                continue
            seen_q.add((f, rn))
            quarantine.add((f, rn))
        R["data_quality_issue_log.md"].append({"issue": f"DQ-{_digits(rng, used_dq, 100000, 999999):06d}", "file": f,
                                               "recno": rn, "disp": disp, "_h": 0})
    for r in R["data_quality_issue_log.md"]:
        r["_h"] = digits_of(r["issue"])
    F["quarantine"] = quarantine
    for i, r in enumerate(R["data_quality_issue_log.md"]):
        r["_recno"] = i + 1

    # delivery manifest + controls ----------------------------------------------
    used_dlv = set()
    names = [n for n, *_ in FILES]
    cids = {n: f"DLV-{_digits(rng, used_dlv, 1000, 9999):04d}" for n in names}
    order = list(names)
    rng.shuffle(order)
    W.ring_order = order
    W.cids = cids
    base_ts = secs_of_dt(_dt.datetime(2026, 6, 1, 6, 0))
    deliv = []
    for i, n in enumerate(order):
        deliv.append({"delivery": cids[n], "file": n, "cycle": CYCLE, "delivered": base_ts + i * 3571, "status": "DELIVERED"})
    hist_names = [n.replace("2025", "2024").replace("2026", "2025") for n in names]
    k = 0
    while len(deliv) < W.n(5100, 160):
        n = rng.choice(hist_names)
        cyc = f"{2019 + k % 7}-Q{1 + k % 4}-MON"
        deliv.append({"delivery": f"HDL-{100000 + k}", "file": n, "cycle": cyc,
                      "delivered": base_ts - (k + 1) * 86400 // 3, "status": rng.choice(["DELIVERED", "WITHDRAWN"])})
        k += 1
    rng.shuffle(deliv)
    for r in deliv:
        r["_h"] = digits_of(r["delivery"])
    R["delivery_manifest.json"] = deliv
    W.delivered_rank = {n: i for i, n in enumerate(order)}
    for f, rows in R.items():
        for i, r in enumerate(rows):
            r["_recno"] = i + 1


def build_L(W):
    """The clean logical estate a perfect reader of the shipped files recovers."""
    F, R = W.facts, W.recs
    L = {}
    L["quarantine"] = set(F["quarantine"])
    rank = W.delivered_rank
    apps = []
    for f in APP_FILES.values():
        for r in R[f]:
            local = f in LOCAL_APP_FILES
            apps.append({"acct": r["acct"], "cust": r["cust"], "app_id": r["app_id"], "branch": r["branch"],
                         "product_code": r["code"],
                         "product_basis": "current" if f == "applications_2025_05.xlsx" else "decision",
                         "decision_utc": None if local else r["decision_utc"],
                         "decision_local": r["local"] if local else None,
                         "limit": r["limit"], "revision": r["rev"], "received_utc": r["received"],
                         "order": rank[f] * 1000000 + r["_recno"], "file": f, "recno": r["_recno"]})
    L["apps"] = apps
    L["branch_xwalk"] = {r["new"]: r["old"] for r in R["branch_directory_2026.html"]}
    br = {}
    for r in R["branch_directory.html"]:
        br.setdefault(r["code"], []).append((r["market"], r["from"], r["to"]))
    L["branches"] = br
    L["prodmap"] = {r["code"]: r["product"] for r in R["product_code_crosswalk.ini"]}
    mig = {}
    for r in R["product_migrations_2025.xlsx"]:
        mig.setdefault(r["acct"], []).append((r["from"], r["to"], r["date"], r["id"]))
    L["migrations"] = mig
    wd = {}
    for r in R["application_withdrawals.json"]:
        wd.setdefault(r["acct"], []).append(r["date"])
    L["withdrawals"] = wd
    L["withdrawal_reversed"] = {r["acct"] for r in R["applications_master_2025h1.parquet"] if r["reversed"]}
    L["alias"] = {r["alias"]: r["master"] for r in R["customer_master.db"] if r["_table"] == "customer_alias"}
    legacy = {r["legacy"]: r["cust"] for r in R["merge_candidates_ml.xlsx"] if r["_sheet"] == "legacy_refs"}
    approved = []
    for f in ("customer_merge_decisions.docx", "customer_merges_2026.tsv"):
        for r in R[f]:
            if r["status"] == "APPROVED":
                approved.append((r["date"], legacy.get(r["merged"], r["merged"]), legacy.get(r["survivor"], r["survivor"])))
    mm = {}
    for _d, m, s in sorted(approved):
        mm[m] = s
    L["merge_map"] = mm
    scores = []
    for f, meta in W.meta.items():
        if meta["kind"] in ("SCORE", "REPLAY"):
            for r in R[f]:
                if r.get("kind", "SCORE") != "SCORE":
                    continue
                scores.append({"event_id": r["event_id"], "event_num": r["event_num"], "acct": "" if r.get("null_acct") else r["acct"],
                               "run_id": r["run_id"], "score_ts": r["ts"], "score": r["score"], "file": f,
                               "recno": r["_recno"]})
    L["scores"] = scores
    L["runs"] = {r["run_id"]: (r["node"], r["version"], r["status"])
                 for f in ("model_registry_v4.toml", "scoring_runs_2025q2.toml") for r in R[f]}
    L["void_runs"] = {r["run_id"] for r in R["scoring_engine_node9.log"] if r["kind"] == "VOID"}
    L["skew"] = {r["run_id"]: r["offset"] for r in R["score_clock_skew_corrections.json"]}
    L["approvals"] = [(v, set(s), a, b) for v, s, a, b in F["approvals"]]
    L["version_withdrawals"] = list(F["withdrawals_ver"])
    ss, sl = {}, {}
    for r in R["exclusion_policy.docx"]:
        ss.setdefault(r["emp"], []).append((r["cust"], r["date"]))
    for r in R["employee_leavers.tsv"]:
        sl.setdefault(r["emp"], []).append(r["date"])
    L["staff_starts"], L["staff_leaves"] = ss, sl
    holds = {}
    for r in R["litigation_hold_register.html"]:
        holds.setdefault(r["acct"], []).append((r["from"], r["to"]))
    L["holds"] = holds
    L["insolvency"] = {r["acct"]: r["date"] for r in R["regulatory_exclusion_letter_2026.pdf"]}
    L["redress"] = {r["acct"] for r in R["consumer_redress_programme.pdf"]}
    dec = [(r["cust"], r["date"]) for r in R["deceased_notifications_register.pdf"]]
    dec += [(r["cust"], r["date"]) for r in R["deceased_notifications_feed.xml"]]
    dec += [(r["subject"], r["date"]) for r in R["status_events_consolidated.json"]
            if r["type"] == "DECEASED" and r["source"] == "CIVIL_REGISTRY"]
    L["deceased"] = dec
    L["fraud_alerts"] = [(r["case"], r["acct"], r["date"]) for f in ("fraud_alerts_2025.jsonl", "fraud_alerts_2026.xml")
                         for r in R[f]]
    L["fraud_disp"] = {r["case"]: r["status"] for r in R["fraud_case_dispositions.json"]}
    snaps = []
    for f, meta in W.meta.items():
        if meta["kind"] in ("SNAP", "REPLICA"):
            for r in R[f]:
                if "month" not in r:
                    continue
                dpd, status = r["dpd"], r["status"]
                if dpd == -1:
                    dpd = None
                elif dpd == 999:
                    dpd, status = 180, "CO"
                snaps.append({"acct": r["acct"], "month": r["month"], "dpd": dpd, "status": status,
                              "file": f, "recno": r["_recno"]})
    L["snaps"] = snaps
    L["certified"] = dict(F["certified"])
    L["forbear_grants"] = {r["gid"]: (r["acct"], r["start"], r["end"]) for r in R["bad_definition_standard.docx"]}
    ext = {}
    for r in R["forbearance_extensions_register.pdf"]:
        ext.setdefault(r["gid"], []).append(r["end"])
    L["forbear_ext"] = ext
    L["forbear_revoked"] = {r["gid"] for r in R["bad_definition_standard_v5.docx"]}
    legacy_a = {r["legacy"]: r["acct"] for r in R["legacy_account_map.ini"]}
    L["co_events"] = [(r["eid"], legacy_a.get(r["ref"], r["ref"]), r["date"])
                      for f in ("status_events_chargeoff_2025.csv", "chargeoff_events_2026.parquet") for r in R[f]]
    L["co_reversals"] = {r["ref"]: r["date"] for r in R["status_events_consolidated.json"] if r["type"] == "CO_REVERSAL"}
    L["closures"] = [(r["acct"], r["date"]) for f in ("account_closures_2025.json", "account_closures_2026h1.csv")
                     for r in R[f]]
    L["thresholds"] = dict(F["thresholds"])
    er = {}
    for r in sorted(R["errata_register.md"], key=lambda r: (r["date"], r["id"])):
        if r["status"] == "APPLIED":
            er[(r["acct"], r["month"])] = r["dpd"]
    L["errata"] = er
    xc = {}
    for r in sorted(R["snapshot_corrections_feed.xml"], key=lambda r: r["seq"]):
        xc[(r["acct"], r["month"])] = r["dpd"]
    L["xml_corr"] = xc
    retracted = {m["target"] for m in R["ops_corrections.mbox"] if m["kind"] == "retract"}
    mc = {}
    for m in sorted((m for m in R["ops_corrections.mbox"] if m["kind"] == "corr"), key=lambda m: (m["ts"], m["msgid"])):
        if m["msgid"] not in retracted:
            mc[m["key"]] = m["dpd"]
    L["mail_corr"] = mc
    L["system_error"] = {(r["acct"], r["month"]) for r in R["snapshots_2025_10_b_restated.tsv"] if r["reason"] == "SYSTEM_ERROR"}
    L["audit"] = {r["acct"]: r["label"] for r in R["audit_label_confirmations.pdf"]}
    L["pi_override"] = {r["acct"]: r["pi"] for r in R["sampling_methodology.docx"] if r["status"] == "APPROVED"}
    pi, pi_app = {}, {}
    for f in ("sampling_inclusion_gb_pl_se.yaml", "sampling_inclusion_cz_hu_ch.yaml", "sampling_inclusion_dk_no.yaml"):
        for r in R[f]:
            (pi_app if r["cohort"] == "2025-04" else pi)[r["key"]] = r["pi"]
    for r in R["sampling_design_v2.yaml"]:
        if r["cohort"] == "2025-06":
            pi[r["key"]] = r["pi"]
    L["pi"], L["pi_by_appid"] = pi, pi_app
    L["appid_xwalk"] = {r["app_id"]: r["acct"] for r in R["applications_2025_04_reextract.csv"]}
    la = {}
    for f in ("limit_amendments_2025.xlsx", "limit_management_policy.docx"):
        for r in R[f]:
            la.setdefault(r["acct"], []).append((r["date"], r["limit"], r["id"]))
    L["limit_amends"] = la
    L["redenom"] = {r["acct"]: r["ccy"] for r in R["currency_redenomination.ini"]}
    hol = {}
    for r in R["market_holidays.ics"]:
        if r["cat"] in ("PUBLIC-HOLIDAY", "BANK-CLOSURE"):
            d = r["date"]
            while d < r.get("end", r["date"] + _dt.timedelta(days=1)):
                hol.setdefault(r["market"], set()).add(d)
                d += _dt.timedelta(days=1)
    L["holidays"] = hol
    fx = {}
    best = {}
    for r in R["treasury_fixings_2024_2026.xml"]:
        k = (r["ccy"], r["date"])
        if k not in best or r["rev"] > best[k]["rev"]:
            best[k] = r
    for (ccy, d), r in best.items():
        fx.setdefault(ccy, []).append((d, r["eur"], r["per"]))
    L["fx"] = {k: sorted(v) for k, v in fx.items()}
    L["cuts"] = {k: list(v) for k, v in F["cuts_eff"].items()}
    L["dev"] = {(r["seg"], r["score"]): r["count"] for r in R["monitoring_spec_v4.md"]}
    cal = {(r["seg"], r["score"]): r["pd"] for r in R["model_documentation_v4.pdf"]}
    for r in R["calibration_reissue_2026.pdf"]:
        if r["_part"] == "retro" and (r["seg"], r["score"]) in cal:
            cal[(r["seg"], r["score"])] = r["pd"]
    L["calib"] = cal
    L["ring"] = W.ring
    return L


def finalize(W):
    """Run the rules once to seal the cohort controls, then close the control ring."""
    R = W.recs
    rng = _random.Random(W.seed ^ 0xC0FFEE)
    W.ring = {"files": {}, "by_id": {}, "expected_ids": []}
    L = build_L(W)
    res = run_rules(L, ignore_gate=True)
    cohort = res.cohort
    ctl = []
    for seg in SEGMENTS + ["ALL"]:
        mem = [a for a in cohort.values() if seg == "ALL" or a["product"] == seg]
        ctl.append((CYCLE, seg, "cohort_accounts_hash", sum(digits_of(a["acct"]) for a in mem)))
        ctl.append((CYCLE, seg, "bad_accounts_hash", sum(digits_of(a["acct"]) for a in mem if a["bad"])))
    ctl.append((CYCLE, "ALL", "excluded_accounts_hash", sum(digits_of(k) for k in res.exclusions)))
    metrics = ["cohort_accounts_hash", "bad_accounts_hash", "excluded_accounts_hash", "scored_accounts",
               "psi_alert_flag", "auc_floor_breach", "drift_review_ticket", "override_rate_bp"]
    k = 0
    while len(ctl) < W.n(5100, 80):
        cyc = f"{2019 + (k // 28) % 7}-Q{1 + (k // 7) % 4}-MON"
        seg = (SEGMENTS + ["ALL"])[k % 7]
        ctl.append((cyc, seg, metrics[(k // 196) % len(metrics)] + ("" if k < 1568 else f"_{k // 1568}"),
                    rng.randint(10 ** 8, 10 ** 11)))
        k += 1
    ctl_recs = [{"_table": "cycle_controls", "cycle": cyc, "segment": seg, "metric": metric, "value": value,
                 "_h": value % 10000000} for cyc, seg, metric, value in ctl]
    R["snapshots_servicing_replica.db"] = ctl_recs + R["snapshots_servicing_replica.db"]
    for i, r in enumerate(R["snapshots_servicing_replica.db"]):
        r["_recno"] = i + 1
    W.cohort_controls = ctl[:15]
    # control ring
    order = W.ring_order
    files = {}
    for n in order:
        files[n] = {"control_id": W.cids[n], "rows": len(R[n]), "hash": sum(r["_h"] for r in R[n]), "acks": []}
    N = len(order)
    for i, n in enumerate(order):
        prev1, prev2 = order[(i - 1) % N], order[(i - 2) % N]
        files[n]["acks"] = [(W.cids[prev1], "rows", files[prev1]["rows"]), (W.cids[prev2], "hash", files[prev2]["hash"])]
    W.ring = {"files": files, "by_id": {v["control_id"]: v for v in files.values()},
              "expected_ids": sorted(W.cids[n] for n in order)}
    W.L = build_L(W)
    W.result = run_rules(W.L)
    W.outputs = render_outputs(W.L, W.result)
    return W


# ---------------------------------------------------------------------------
# Writers: serialize every file in its documented dialect, planting the
# representation traps and the delivery-control block.
# ---------------------------------------------------------------------------
import io as _io
import sqlite3 as _sqlite3
import struct as _struct
import zipfile as _zipfile
from xml.sax.saxutils import escape as _xesc, quoteattr as _xattr

ZIP_TS = (2026, 6, 30, 12, 0, 0)


class Planter:
    """Deterministic placement of representation traps across 500-record bands."""

    def __init__(self, W, name, n):
        self.W = W
        self.name = name
        self.rng = _random.Random((W.seed * 1000003) ^ sum(ord(c) * (i + 1) for i, c in enumerate(name)))
        self.n = n
        self.plan = {}

    def scatter(self, code, family, rate=0.004, minimum=None, desc="", rule="", direction="", eligible=None):
        n = self.n
        if n == 0:
            return set()
        bands = max(1, (n + 499) // 500)
        picks = set()
        for b in range(bands):
            lo, hi = b * 500, min(n, (b + 1) * 500)
            cands = [i for i in range(lo, hi) if eligible is None or eligible(i)]
            if cands and (self.rng.random() < 0.5 or len(picks) < 1):
                picks.add(self.rng.choice(cands))
        k = int(n * rate)
        allc = [i for i in range(n) if eligible is None or eligible(i)] if eligible else None
        for _ in range(k):
            i = self.rng.choice(allc) if allc else self.rng.randrange(n)
            picks.add(i)
        if minimum and len(picks) < minimum and n:
            pool = allc or list(range(n))
            while len(picks) < min(minimum, len(pool)):
                picks.add(self.rng.choice(pool))
        for i in picks:
            self.plan.setdefault(i, []).append(code)
        rows = self.W.recs.get(self.name, [])
        for i in sorted(picks):
            acct = rows[i].get("acct") if i < len(rows) and isinstance(rows[i], dict) else None
            accts = [acct] if acct in self.W.acct_by_id else []
            self.W.trap(self.name, family, code, recno=i + 1, accts=accts, desc=desc, rule=rule, direction=direction)
        return picks

    def has(self, i, code):
        return code in self.plan.get(i, ())

    def cover(self, code=None):
        """Guarantee at least one planted trap in every 500-record band."""
        codes = sorted(getattr(self, "codes", set()) | {c for v in self.plan.values() for c in v})
        if not codes or self.n == 0:
            return
        code = code or codes[0]
        for b in range(0, self.n, 500):
            if not any(i in self.plan for i in range(b, min(self.n, b + 500))):
                i = self.rng.randrange(b, min(self.n, b + 500))
                self.plan.setdefault(i, []).append(code)
                self.W.trap(self.name, "T1" if code.startswith("key_") else "T9", code, recno=i + 1,
                            desc="band coverage instance", rule="spec 4 conventions")


def fmt_key(acct, variants):
    prefix, digits = acct[:2], acct[2:]
    if "homo" in variants:
        prefix = "".join(HOMO.get(c, c) for c in prefix)
    if "lower" in variants:
        prefix = prefix.lower()
    if "zpad" in variants:
        digits = "0" + digits
    if "hyphen" in variants:
        prefix += "-"
    text = prefix + digits
    if "nbsp" in variants:
        text = text[:2] + "\u00a0" + text[2:]
    if "space" in variants:
        text = " " + text + " "
    if "zwsp" in variants:
        text = text + "\u200b"
    return text


KEY_TRAPS = [("key_space", "space"), ("key_lower", "lower"), ("key_homoglyph", "homo"), ("key_zero_pad", "zpad"),
             ("key_hyphen", "hyphen"), ("key_nbsp", "nbsp"), ("key_zwsp", "zwsp")]
ALL_KEYS = [c for c, _ in KEY_TRAPS]
KEY_FAMILY = {"key_nbsp": "T10", "key_zwsp": "T10"}


def plant_keys(P, codes):
    if not hasattr(P, "codes"):
        P.codes = set()
    decoy = P.W.meta[P.name]["decoy"]
    if decoy:
        codes = ALL_KEYS if not P.name.endswith(".txt") else codes
        if P.name.endswith(".log"):
            codes = [c for c in codes if c != "key_space"]
    cap = P.W.cap_for(P.name, 40 if decoy else 20)
    for code in codes:
        if code in P.codes:
            continue
        if len(P.codes | P.W.trap_codes(P.name)) >= cap:
            return
        P.scatter(code, KEY_FAMILY.get(code, "T1"), rate=0.002, desc="account/customer key written in a non-canonical form",
                  rule="spec 3.1 key normalisation")
        P.codes.add(code)


DATE_TRAPS = ["date_dmy_dot", "date_compact", "date_dmy_slash"]


def plant_dates(P, codes=DATE_TRAPS):
    for code in codes:
        P.scatter(code, "T3", rate=0.002, desc="date in an alternative documented form", rule="spec 4.5 dates")


def date_of(P, i, d):
    if d is None:
        if P.has(i, "open_end_word"):
            return "open"
        if P.has(i, "open_end_9999"):
            return "9999-12-31"
        return ""
    if P.has(i, "date_dmy_dot"):
        return f"{d.day:02d}.{d.month:02d}.{d.year:04d}"
    if P.has(i, "date_compact"):
        return d.strftime("%Y%m%d")
    if P.has(i, "date_dmy_slash"):
        return f"{d.day:02d}/{d.month:02d}/{d.year:04d}"
    return d.isoformat()


def plant_open(P, eligible):
    P.scatter("open_end_word", "T5", rate=0.01, desc="open end written as the word open", rule="spec 4.5", eligible=eligible)
    P.scatter("open_end_9999", "T5", rate=0.01, desc="open end written as 9999-12-31", rule="spec 4.5", eligible=eligible)


def plant_status(P):
    P.scatter("status_lowercase", "T1", rate=0.004, desc="status in lower case", rule="spec 3.1 case-insensitive codes")
    P.scatter("status_padded", "T9", rate=0.004, desc="status padded with spaces", rule="spec 3.1 trimming")


def status_of(P, i, s):
    if P.has(i, "status_lowercase"):
        s = s.lower()
    if P.has(i, "status_padded"):
        s = f"  {s} "
    return s


def plant_money(P, rows, field="limit"):
    def odd(i):
        v = rows[i][field]
        return int(v * 100) % 2 == 1 and v == v.quantize(Decimal("0.01"))
    P.scatter("money_three_decimals", "T12", rate=0.004, desc="amount written with a half-cent third decimal",
              rule="spec 4.6 money rounded half up on read", eligible=odd)


def money_of(P, i, v, comma=False):
    if P.has(i, "money_three_decimals"):
        text = f"{v - Decimal('0.005'):.3f}"
    else:
        text = str(v)
    return text.replace(".", ",") if comma else text


def key_of(P, i, acct):
    vs = {v for code, v in KEY_TRAPS if P.has(i, code)}
    return fmt_key(acct, vs) if vs else acct


def control_payload(W, name):
    info = W.ring["files"][name]
    (t1, _k1, v1), (t2, _k2, v2) = info["acks"]
    return {"control_id": info["control_id"], "ack_rows_of": t1, "ack_rows": v1, "ack_hash_of": t2, "ack_hash": v2}


def control_line(W, name):
    c = control_payload(W, name)
    return (f"control_id={c['control_id']} ack_rows_of={c['ack_rows_of']} ack_rows={c['ack_rows']} "
            f"ack_hash_of={c['ack_hash_of']} ack_hash={c['ack_hash']}")


def dec_comma(d):
    return str(d).replace(".", ",")


def thousands(d):
    whole, _, frac = f"{d:.2f}".partition(".")
    neg = whole.startswith("-")
    whole = whole.lstrip("-")
    groups = []
    while whole:
        groups.insert(0, whole[-3:])
        whole = whole[:-3]
    return ("-" if neg else "") + ",".join(groups) + "." + frac


def local_str(secs, fmt="%Y-%m-%d %H:%M:%S"):
    return (EPOCH + _dt.timedelta(seconds=secs)).strftime(fmt)


def iso_offset(ts, market):
    off = utc_offset(market, ts)
    loc = EPOCH + _dt.timedelta(seconds=ts + off)
    return loc.strftime("%Y-%m-%dT%H:%M:%S") + f"+{off // 3600:02d}:00"


def excel_serial(secs):
    return Fraction(secs, 86400) + 25569


def ser_str(secs, dp=8):
    return frac_round(excel_serial(secs), dp, "up")


def csv_cell(v, delim):
    s = "" if v is None else str(v)
    if any(c in s for c in (delim, '"', "\n", "\r")):
        return '"' + s.replace('"', '""') + '"'
    return s


NOTES = ["branch walk-in", "call centre, inbound", 'web "express" flow', "partner referral;\nsecond line",
         "renewal", "online", "mobile app", "broker, priority"]


def write_delimited(W, name, rows, header, delim, cells, *, encoding="utf-8", bom=False, crlf_tail=False,
                    comments=(), drift=None, P=None):
    """rows: records; cells(i, r) -> list aligned with header. drift: (index, new_header, reorder)."""
    out = []
    for c in comments:
        out.append("# " + c)
    out.append(delim.join(header))
    order = list(range(len(header)))
    for i, r in enumerate(rows):
        if drift is not None and i == drift[0]:
            order = drift[1]
            out.append(delim.join(header[j] for j in order))
            W.trap(name, "T8", "header_reemitted_reordered", recno=i + 1,
                   desc="extractor restart re-emits a reordered header mid-file", rule="spec 4.2 re-emitted headers")
        vals = cells(i, r)
        out.append(delim.join(csv_cell(vals[j], delim) for j in order))
    out.append("# CONTROL " + control_line(W, name))
    text = "\n".join(out) + "\n"
    data = text.encode(encoding)
    if crlf_tail and not bom:
        bom = True
    if bom:
        data = b"\xef\xbb\xbf" + data
        W.trap(name, "T10", "utf8_bom", recno=0, desc="UTF-8 byte order mark before the first header",
               rule="spec 4.2 encodings")
    return data


def zip_bytes(members):
    buf = _io.BytesIO()
    with _zipfile.ZipFile(buf, "w", _zipfile.ZIP_DEFLATED) as zf:
        for path, data in members:
            info = _zipfile.ZipInfo(path, ZIP_TS)
            info.compress_type = _zipfile.ZIP_DEFLATED
            info.external_attr = 0o644 << 16
            zf.writestr(info, data)
    return buf.getvalue()


def custom_props_xml(payload):
    props = []
    for i, (k, v) in enumerate(sorted(payload.items()), start=2):
        props.append(f'<property fmtid="{{D5CDD505-2E9C-101B-9397-08002B2CF9AE}}" pid="{i}" name="{k}">'
                     f"<vt:lpwstr>{_xesc(str(v))}</vt:lpwstr></property>")
    return ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
            '<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/custom-properties" '
            'xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes">' + "".join(props) +
            "</Properties>")


def col_letter(i):
    s = ""
    i += 1
    while i:
        i, r = divmod(i - 1, 26)
        s = chr(65 + r) + s
    return s


def write_xlsx(W, name, sheets):
    """sheets: list of (sheet_name, header, rows) where row cells are ("s", text) | ("n", number) | ("d", serial)."""
    strings, sidx = [], {}

    def si(t):
        if t not in sidx:
            sidx[t] = len(strings)
            strings.append(t)
        return sidx[t]

    sheet_xml = []
    for sname, header, rows in sheets:
        xr = []
        allrows = [[("s", h) for h in header]] + rows
        for ri, row in enumerate(allrows, start=1):
            cells = []
            for ci, (kind, val) in enumerate(row):
                ref = f"{col_letter(ci)}{ri}"
                if val is None or val == "":
                    continue
                if kind == "s":
                    cells.append(f'<c r="{ref}" t="s"><v>{si(str(val))}</v></c>')
                elif kind == "d":
                    cells.append(f'<c r="{ref}" s="1"><v>{val}</v></c>')
                else:
                    cells.append(f'<c r="{ref}"><v>{val}</v></c>')
            xr.append(f'<row r="{ri}">' + "".join(cells) + "</row>")
        sheet_xml.append('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
                         '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
                         "<sheetData>" + "".join(xr) + "</sheetData></worksheet>")
    sst = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
           f'<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="{len(strings)}" '
           f'uniqueCount="{len(strings)}">' + "".join(f"<si><t xml:space=\"preserve\">{_xesc(s)}</t></si>" for s in strings) + "</sst>")
    styles = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
              '<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
              '<numFmts count="1"><numFmt numFmtId="164" formatCode="yyyy-mm-dd hh:mm:ss"/></numFmts>'
              '<fonts count="1"><font><sz val="11"/><name val="Calibri"/></font></fonts>'
              '<fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills>'
              '<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>'
              '<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>'
              '<cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>'
              '<xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs>'
              "</styleSheet>")
    wb = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
          '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
          'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>' +
          "".join(f'<sheet name="{_xesc(s[0])}" sheetId="{i + 1}" r:id="rId{i + 1}"/>' for i, s in enumerate(sheets)) +
          "</sheets></workbook>")
    rels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' +
            "".join(f'<Relationship Id="rId{i + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" '
                    f'Target="worksheets/sheet{i + 1}.xml"/>' for i in range(len(sheets))) +
            f'<Relationship Id="rId{len(sheets) + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/sharedStrings" Target="sharedStrings.xml"/>'
            f'<Relationship Id="rId{len(sheets) + 2}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>'
            "</Relationships>")
    ct = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
          '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
          '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
          '<Default Extension="xml" ContentType="application/xml"/>'
          '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>' +
          "".join(f'<Override PartName="/xl/worksheets/sheet{i + 1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
                  for i in range(len(sheets))) +
          '<Override PartName="/xl/sharedStrings.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml"/>'
          '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'
          '<Override PartName="/docProps/custom.xml" ContentType="application/vnd.openxmlformats-officedocument.custom-properties+xml"/>'
          "</Types>")
    root_rels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
                 '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                 '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
                 '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/custom-properties" Target="docProps/custom.xml"/>'
                 "</Relationships>")
    members = [("[Content_Types].xml", ct), ("_rels/.rels", root_rels), ("xl/workbook.xml", wb),
               ("xl/_rels/workbook.xml.rels", rels), ("xl/sharedStrings.xml", sst), ("xl/styles.xml", styles),
               ("docProps/custom.xml", custom_props_xml(control_payload(W, name)))]
    members += [(f"xl/worksheets/sheet{i + 1}.xml", x) for i, x in enumerate(sheet_xml)]
    return zip_bytes([(p, d.encode("utf-8")) for p, d in members])


def docx_bytes(W, name, blocks, footnotes=()):
    """blocks: ("h", level, text) | ("p", text) | ("t", header, rows)."""
    body = []
    for b in blocks:
        if b[0] == "h":
            body.append(f'<w:p><w:pPr><w:pStyle w:val="Heading{b[1]}"/></w:pPr><w:r><w:t xml:space="preserve">{_xesc(b[2])}</w:t></w:r></w:p>')
        elif b[0] == "p":
            text = b[1]
            if "[^" in text:
                head, _, rest = text.partition("[^")
                fid, _, tail = rest.partition("]")
                body.append(f'<w:p><w:r><w:t xml:space="preserve">{_xesc(head)}</w:t></w:r>'
                            f'<w:r><w:rPr><w:vertAlign w:val="superscript"/></w:rPr><w:footnoteReference w:id="{fid}"/></w:r>'
                            f'<w:r><w:t xml:space="preserve">{_xesc(tail)}</w:t></w:r></w:p>')
            else:
                body.append(f'<w:p><w:r><w:t xml:space="preserve">{_xesc(text)}</w:t></w:r></w:p>')
        else:
            header, rows = b[1], b[2]

            def tr(cells, hdr=False):
                pr = "<w:trPr><w:tblHeader/></w:trPr>" if hdr else ""
                out = []
                for c in cells:
                    parts = str(c).split("\n")
                    runs = "<w:r><w:br/></w:r>".join(f'<w:r><w:t xml:space="preserve">{_xesc(p)}</w:t></w:r>' for p in parts)
                    out.append(f"<w:tc><w:p>{runs}</w:p></w:tc>")
                return f"<w:tr>{pr}" + "".join(out) + "</w:tr>"
            body.append("<w:tbl><w:tblPr><w:tblStyle w:val=\"TableGrid\"/></w:tblPr>" + tr(header, True) +
                        "".join(tr(r) for r in rows) + "</w:tbl>")
            body.append("<w:p/>")
    ns = ('xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" '
          'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"')
    doc = f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<w:document {ns}><w:body>' + "".join(body) + "<w:sectPr/></w:body></w:document>"
    fn = (f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<w:footnotes {ns}>'
          '<w:footnote w:type="separator" w:id="-1"><w:p><w:r><w:separator/></w:r></w:p></w:footnote>'
          '<w:footnote w:type="continuationSeparator" w:id="0"><w:p><w:r><w:continuationSeparator/></w:r></w:p></w:footnote>' +
          "".join(f'<w:footnote w:id="{fid}"><w:p><w:r><w:t xml:space="preserve">{_xesc(t)}</w:t></w:r></w:p></w:footnote>'
                  for fid, t in footnotes) + "</w:footnotes>")
    styles = (f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<w:styles {ns}>' +
              "".join(f'<w:style w:type="paragraph" w:styleId="Heading{i}"><w:name w:val="heading {i}"/><w:basedOn w:val="Normal"/></w:style>'
                      for i in (1, 2, 3)) +
              '<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/></w:style>'
              '<w:style w:type="table" w:styleId="TableGrid"><w:name w:val="Table Grid"/></w:style></w:styles>')
    rels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>'
            '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footnotes" Target="footnotes.xml"/>'
            "</Relationships>")
    ct = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
          '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
          '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
          '<Default Extension="xml" ContentType="application/xml"/>'
          '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
          '<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>'
          '<Override PartName="/word/footnotes.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.footnotes+xml"/>'
          '<Override PartName="/docProps/custom.xml" ContentType="application/vnd.openxmlformats-officedocument.custom-properties+xml"/>'
          "</Types>")
    root_rels = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n'
                 '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                 '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>'
                 '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/custom-properties" Target="docProps/custom.xml"/>'
                 "</Relationships>")
    members = [("[Content_Types].xml", ct), ("_rels/.rels", root_rels), ("word/document.xml", doc),
               ("word/_rels/document.xml.rels", rels), ("word/styles.xml", styles), ("word/footnotes.xml", fn),
               ("docProps/custom.xml", custom_props_xml(control_payload(W, name)))]
    return zip_bytes([(p, d.encode("utf-8")) for p, d in members])


def _pdf_escape(s):
    return s.replace("\\", "\\\\").replace("(", "\\(").replace(")", "\\)")


def pdf_bytes(lines_per_page):
    """lines_per_page: list of pages, each a list of text lines (latin-1 safe)."""
    objs = []

    def add(b):
        objs.append(b)
        return len(objs)

    font = add(b"<< /Type /Font /Subtype /Type1 /BaseFont /Courier /Encoding /WinAnsiEncoding >>")
    pages_id_placeholder = len(objs) + 1
    add(b"")
    page_ids = []
    for lines in lines_per_page:
        ops = ["BT", "/F1 7 Tf", "9 TL", "28 810 Td"]
        for ln in lines:
            ops.append(f"({_pdf_escape(ln)}) Tj T*")
        ops.append("ET")
        stream = "\n".join(ops).encode("latin-1")
        content = add(b"<< /Length " + str(len(stream)).encode() + b" >>\nstream\n" + stream + b"\nendstream")
        page_ids.append(add(f"<< /Type /Page /Parent {pages_id_placeholder} 0 R /MediaBox [0 0 595 842] "
                            f"/Resources << /Font << /F1 {font} 0 R >> >> /Contents {content} 0 R >>".encode()))
    objs[pages_id_placeholder - 1] = (f"<< /Type /Pages /Count {len(page_ids)} /Kids [" +
                                      " ".join(f"{p} 0 R" for p in page_ids) + "] >>").encode()
    catalog = add(f"<< /Type /Catalog /Pages {pages_id_placeholder} 0 R >>".encode())
    out = _io.BytesIO()
    out.write(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = []
    for i, body in enumerate(objs, start=1):
        offsets.append(out.tell())
        out.write(f"{i} 0 obj\n".encode() + body + b"\nendobj\n")
    xref = out.tell()
    out.write(f"xref\n0 {len(objs) + 1}\n0000000000 65535 f \n".encode())
    for off in offsets:
        out.write(f"{off:010d} 00000 n \n".encode())
    out.write(f"trailer\n<< /Size {len(objs) + 1} /Root {catalog} 0 R >>\nstartxref\n{xref}\n%%EOF\n".encode())
    return out.getvalue()


def paginate(title, prose, header, rows, per_page=80, page_header=None):
    pages = []
    cur = [title, ""] + [ln for p in prose for ln in (_wrap(p) + [""])]
    if len(cur) > per_page - 10:
        pages.append(cur[: per_page])
        cur = cur[per_page:]
    hdr = " | ".join(header)
    cur.append(hdr)
    for r in rows:
        if len(cur) >= per_page:
            pages.append(cur)
            cur = [page_header or title, hdr]
        cur.append(" | ".join(str(c) for c in r))
    pages.append(cur)
    total = len(pages)
    for i, p in enumerate(pages):
        p.append("")
        p.append(f"Page {i + 1} of {total}")
    return pages


def _wrap(text, width=110):
    words, lines, cur = text.split(), [], ""
    for w in words:
        if len(cur) + len(w) + 1 > width:
            lines.append(cur)
            cur = w
        else:
            cur = (cur + " " + w).strip()
    if cur:
        lines.append(cur)
    return lines


