def write_docx(W, name):
    blocks = list(DOCX_TEXT[name])
    header, rows = docx_rows(W, name)
    chunk = 4000
    for k in range(0, len(rows), chunk):
        blocks.append(("t", header, rows[k:k + chunk]))
    W.trap(name, "T8", "table_split_repeated_header", recno=chunk + 1, desc="appendix split into tables with repeated headers",
           rule="spec 2.2")
    W.trap(name, "T14", "rule_in_prose", recno=0, desc="binding rule lives in the document prose", rule="specification preamble")
    foot = ()
    if name == "bad_definition_standard_v5.docx":
        foot = [("1", f"Draft for consultation. Not in force until change request {W.facts['crs']['BDS-V5'][0]} is approved.")]
        W.trap(name, "T14", "draft_status_in_footnote", recno=0, desc="draft status declared only in a footnote",
               rule="governance 3.2", direction="push")
    if name == "sampling_methodology.docx":
        W.trap(name, "T6", "rejected_override", recno=1, desc="REJECTED overrides are ignored", rule="sampling 2.3")
    return docx_bytes(W, name, blocks, foot)


