def write_pdf(W, name):
    R = W.recs[name]
    title, prose = PDF_TEXT[name]
    pages = []
    if name == "model_documentation_v4.pdf":
        cuts = W.facts["cuts_doc"]
        cut_lines = ["segment | c1 | c2 | c3 | c4 | c5 | c6 | c7 | c8 | c9"] + [
            f"{s} | " + " | ".join(str(c) for c in cuts[s]) for s in SEGMENTS]
        pages.append([title, ""] + [ln for p in prose for ln in _wrap(p) + [""]] + ["Score band cut points"] + cut_lines)
        body = paginate(title + " - calibration grid", [], ["segment", "score", "pd"],
                        [[r["seg"], r["score"], r["pd"]] for r in R])
        pages += body
    elif name == "calibration_reissue_2026.pdf":
        main = [r for r in R if r["_part"] == "reissue"]
        retro = [r for r in R if r["_part"] == "retro"]
        pages += paginate(title, prose, ["segment", "score", "pd"], [[r["seg"], r["score"], r["pd"]] for r in main])
        pages += paginate("Appendix B - retrospective corrections", [], ["segment", "score", "pd"],
                          [[r["seg"], r["score"], r["pd"]] for r in retro])
        W.trap(name, "T16", "reissue_grid_newer", recno=1, desc="newer calibration grid not in force for 2025 decisions",
               rule="governance 3.15", direction="pull")
        W.trap(name, "T14", "appendix_b_retrospective", recno=len(main) + 1, desc="retrospective corrections hide in Appendix B",
               rule="governance 3.15", direction="push")
    else:
        hdr_rows = {
            "consumer_redress_programme.pdf": lambda: (["account", "programme"], [[r["acct"], r["programme"]] for r in R]),
            "deceased_notifications_register.pdf": lambda: (["customer", "notified"], [[r["cust"], ddmmyyyy(r["date"])] for r in R]),
            "audit_label_confirmations.pdf": lambda: (["account", "audited_label"], [[r["acct"], r["label"]] for r in R]),
            "regulatory_exclusion_letter_2026.pdf": lambda: (["account", "notice_date"], [[r["acct"], r["date"].isoformat()] for r in R]),
            "forbearance_extensions_register.pdf": lambda: (["grant", "new_to_month"], [[r["gid"], ym_str(r["end"])] for r in R]),
        }[name]()
        pages += paginate(title, prose, hdr_rows[0], hdr_rows[1])
        if name == "deceased_notifications_register.pdf":
            W.trap(name, "T3", "pdf_date_dd_mm_yyyy", recno=1, desc="dates DD.MM.YYYY", rule="catalogue")
    W.trap(name, "T8", "page_header_repeats", recno=80, desc="table header repeats on every page", rule="spec 2.2")
    pages[-1].append("Delivery control: " + control_line(W, name))
    return pdf_bytes(pages)


def write_md(W, name):
    if name == "monitoring_spec_v4.md":
        return spec_md(W)
    if name == "errata_register.md":
        return errata_md(W)
    return dq_md(W)


def write_file(W, name):
    kind = W.meta[name]["kind"]
    t = W.meta[name]["type"]
    if name in COLS:
        return write_register(W, name)
    custom = {"customer_master.db": write_db_v, "snapshots_servicing_replica.db": write_db_v, "merge_candidates_ml.xlsx": write_ml_v,
              "applications_master_2025h1.parquet": write_master_v, "chargeoff_events_2026.parquet": write_co26_v,
              "treasury_fixings_2024_2026.xml": write_fx_v, "fx_rates_ecb_mirror.xml": write_ecb_v,
              "model_documentation_v4.pdf": write_model_pdf_v, "calibration_reissue_2026.pdf": write_model_pdf_v,
              "monitoring_spec_v4.md": write_md_v, "errata_register.md": write_md_v, "data_quality_issue_log.md": write_md_v}
    if name in custom:
        return custom[name](W, name)
    if t == "yaml":
        return write_yaml_v(W, name)
    if t == "toml":
        return write_toml_v(W, name)
    if t == "ini":
        return write_ini_v(W, name)
    if kind == "APP":
        return write_applications(W, name)
    if kind in ("SNAP",) and name in SNAP_DIALECT:
        return write_snapshot(W, name)
    if kind in ("SCORE", "REPLAY"):
        return write_scores(W, name)
    if t == "docx":
        return write_docx(W, name)
    if t == "pdf":
        return write_pdf(W, name)
    if t == "html":
        return write_html(W, name)
    if t == "md":
        return write_md(W, name)
    return write_simple(W, name)


def write_estate(W, out_dir, passes=6):
    """Two passes: the first measures distinct traps per file, the second writes with adjusted variant caps."""
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    semantic_traps(W)
    base_traps = list(W.traps)
    base_codes = {k: set(v) for k, v in W.trap_codes_all().items()}
    W.cap_adj = {}
    for _pass in range(passes):
        W.traps = list(base_traps)
        W._codes = {k: set(v) for k, v in base_codes.items()}
        blobs = {name: write_file(W, name) for name, *_ in FILES}
        over = {name: len(W.trap_codes(name)) - 20 for name, *_ in FILES
                if not W.meta[name]["decoy"] and len(W.trap_codes(name)) > 20}
        if not over:
            break
        for name, excess in over.items():
            W.cap_adj[name] = W.cap_adj.get(name, 0) - excess
    for name, blob in blobs.items():
        (out_dir / name).write_bytes(blob)


# ---------------------------------------------------------------------------
# Shared field kinds: how every documented value is written and read back.
# ---------------------------------------------------------------------------
import datetime as _dtm
import re as _re
from decimal import Decimal as _Dec, ROUND_HALF_UP as _HUP
from fractions import Fraction as _Frac

_HOMO = {"\u0410": "A", "\u0421": "C"}
_INVIS = {"\u00a0", "\u200b", "\ufeff"}


def clean(text):
    return "".join(ch for ch in str(text) if not ch.isspace() and ch not in _INVIS)


def digits_of(text):
    run = "".join(ch for ch in str(text) if ch.isdigit())
    return int(run) if run else 0


def p_key(raw, prefix):
    s = clean(raw).upper()
    s = "".join(_HOMO.get(ch, ch) for ch in s).replace("-", "")
    if not s.startswith(prefix) or not s[len(prefix):].isdigit():
        return s
    return f"{prefix}{int(s[len(prefix):]):07d}"


def p_acct(raw):
    return p_key(raw, "AC")


def p_acctref(raw):
    s = clean(raw).upper()
    if s.startswith("L-"):
        return s
    return p_acct(raw)


def p_cust(raw):
    s = clean(raw).upper()
    if s.startswith("LCU"):
        return s
    return p_key(raw, "CU")


def p_id(raw):
    return clean(raw).upper()


def p_date(raw):
    if isinstance(raw, _dtm.datetime):
        return raw.date()
    if isinstance(raw, _dtm.date):
        return raw
    t = clean(raw)
    if _re.fullmatch(r"\d{4}-\d{2}-\d{2}", t):
        return _dtm.date(int(t[:4]), int(t[5:7]), int(t[8:]))
    if _re.fullmatch(r"\d{2}[./-]\d{2}[./-]\d{4}", t):
        return _dtm.date(int(t[6:]), int(t[3:5]), int(t[:2]))
    if _re.fullmatch(r"\d{8}", t):
        return _dtm.date(int(t[:4]), int(t[4:6]), int(t[6:]))
    raise ValueError(f"unrecognised date {raw!r}")


def p_enddate(raw):
    if raw is None:
        return None
    t = clean(raw).lower()
    if t in ("", "open", "9999-12-31", "31.12.9999", "99991231", "none"):
        return None
    return p_date(t)


def p_month(raw):
    t = clean(raw)
    m = _re.fullmatch(r"(\d{2})/(\d{4})", t)
    if m:
        return int(m.group(2)) * 12 + int(m.group(1)) - 1
    t = t.replace("-", "")
    return int(t[:4]) * 12 + int(t[4:6]) - 1


def p_dec(raw):
    if isinstance(raw, (int, _Dec)):
        return _Dec(raw)
    if isinstance(raw, float):
        return _Dec(repr(raw))
    t = clean(raw)
    neg = t.startswith("(") and t.endswith(")")
    t = t.strip("()")
    if "," in t and "." in t:
        t = t.replace(",", "")
    elif "," in t:
        t = t.replace(",", ".")
    v = _Dec(t)
    return -v if neg else v


def p_money(raw):
    return p_dec(raw).quantize(_Dec("0.01"), rounding=_HUP)


def p_int(raw):
    if isinstance(raw, int):
        return raw
    return int(clean(raw))


def p_status(raw):
    return clean(raw).upper()


def p_pi(raw):
    t = clean(raw).strip("'\"")
    if t.endswith("%"):
        return _Frac(p_dec(t[:-1])) / 100
    if "/" in t:
        a, b = t.split("/")
        return _Frac(int(a), int(b))
    return _Frac(p_dec(t))


def p_isoutc(raw):
    if isinstance(raw, int):
        return raw
    t = str(raw).strip()
    t = _re.sub(r"\.\d+(?=Z|[+-]\d{2}:\d{2}$|$)", "", t)
    if t.endswith("Z"):
        t = t[:-1] + "+00:00"
    if _re.search(r"[+-]\d{2}:\d{2}$", t):
        return int(_dtm.datetime.fromisoformat(t).timestamp())
    return int((_dtm.datetime.fromisoformat(t) - _dtm.datetime(1970, 1, 1)).total_seconds())


def p_text(raw):
    return "" if raw is None else str(raw)


PARSE = {"acct": p_acct, "acctref": p_acctref, "cust": p_cust, "id": p_id, "code": p_id, "status": p_status,
         "date": p_date, "enddate": p_enddate, "month": p_month, "money": p_money, "dec": p_dec, "int": p_int,
         "pi": p_pi, "isoutc": p_isoutc, "text": p_text}

