# ---------------------------------------------------------------------------
# Generic register writer with field-level representation traps.
# ---------------------------------------------------------------------------

VARIANTS = {
    "acct": [("key_space", "T1"), ("key_lower", "T1"), ("key_homoglyph", "T1"), ("key_zero_pad", "T1"), ("key_hyphen", "T1"),
             ("key_nbsp", "T10"), ("key_zwsp", "T10")],
    "acctref": [("key_space", "T1"), ("key_lower", "T1"), ("key_homoglyph", "T1")],
    "cust": [("cust_lower", "T1"), ("cust_homoglyph", "T1"), ("cust_zero_pad", "T1"), ("cust_space", "T1"), ("cust_zwsp", "T10")],
    "id": [("id_lower", "T1"), ("id_padded", "T9")],
    "code": [("code_lower", "T1"), ("code_padded", "T9")],
    "status": [("status_lowercase", "T1"), ("status_padded", "T9"), ("status_title", "T1")],
    "date": [("date_dmy_dot", "T3"), ("date_compact", "T3"), ("date_dmy_slash", "T3")],
    "enddate": [("open_end_word", "T5"), ("open_end_9999", "T5"), ("date_dmy_dot", "T3")],
    "month": [("month_compact", "T3"), ("month_slash", "T3")],
    "money": [("money_three_decimals", "T12"), ("money_thousands", "T4"), ("money_comma", "T4")],
    "dec": [],
    "int": [("int_signed_string", "T4"), ("int_padded", "T9")],
    "pi": [("pi_ratio", "T4"), ("pi_percent", "T4"), ("pi_comma", "T4")],
    "isoutc": [("iso_fraction", "T3"), ("iso_offset", "T3")],
    "serial": [],
    "text": [],
}
ROW_TRAPS = {
    "csv": [("csv_quoted_delimiter", "T9")],
    "tsv": [("tsv_trailing_empty_field", "T9")],
    "jsonl": [("jsonl_unicode_escapes", "T10")],
    "json": [("json_null_field", "T5"), ("json_unicode_escapes", "T10")],
    "xml": [("xml_entities", "T9"), ("xml_whitespace_text", "T9")],
    "xlsx": [("xlsx_numeric_text_cells", "T4")],
    "docx": [],
    "pdf": [],
    "html": [("html_entities_nbsp", "T10")],
}
FILE_TRAPS = {
    "csv": [("csv_utf8_bom", "T10"), ("csv_reemitted_header", "T8")],
    "tsv": [("tsv_utf8_bom", "T10"), ("tsv_reemitted_header", "T8")],
    "jsonl": [],
    "json": [],
    "xml": [],
    "xlsx": [],
    "docx": [("docx_table_split_repeated_header", "T8"), ("docx_rule_in_prose", "T14")],
    "pdf": [("pdf_page_header_repeats", "T8"), ("pdf_rule_in_prose", "T14")],
    "html": [("html_repeated_header_rows", "T8"), ("html_rule_in_prose", "T14")],
}


def emit(P, i, kind, v, sep=",", col=None):
    has = lambda c: P.has(i, c) or (col is not None and P.has(i, f"{c}@{col}"))
    if v == "":
        return ""
    if v is None:
        if kind == "enddate":
            return "open" if has("open_end_word") else ("9999-12-31" if has("open_end_9999") else "")
        return ""
    if kind in ("acct", "acctref"):
        if kind == "acctref" and str(v).startswith("L-"):
            return v
        if col is not None:
            vs = {x for c, x in KEY_TRAPS if has(c)}
            return fmt_key(v, vs) if vs else v
        return key_of(P, i, v)
    if kind == "cust":
        if str(v).startswith("LCU"):
            return v
        vs = {x for c, x in (("cust_lower", "lower"), ("cust_homoglyph", "homo"), ("cust_zero_pad", "zpad"),
                             ("cust_space", "space"), ("cust_zwsp", "zwsp")) if has(c)}
        return fmt_key(v, vs)
    if kind in ("id", "code"):
        t = str(v)
        if has(kind + "_lower"):
            t = t.lower()
        if has(kind + "_padded"):
            t = f" {t} "
        return t
    if kind == "status":
        t = str(v)
        if has("status_lowercase"):
            t = t.lower()
        elif has("status_title"):
            t = t.title()
        if has("status_padded"):
            t = f"  {t} "
        return t
    if kind in ("date", "enddate"):
        if has("date_dmy_dot"):
            return f"{v.day:02d}.{v.month:02d}.{v.year:04d}"
        if has("date_compact"):
            return v.strftime("%Y%m%d")
        if has("date_dmy_slash"):
            return f"{v.day:02d}/{v.month:02d}/{v.year:04d}"
        return v.isoformat()
    if kind == "month":
        y, m = ym_of_index(v)
        if has("month_compact"):
            return f"{y:04d}{m:02d}"
        if has("month_slash"):
            return f"{m:02d}/{y:04d}"
        return f"{y:04d}-{m:02d}"
    if kind == "money":
        if has("money_three_decimals"):
            return f"{v - Decimal('0.005'):.3f}"
        if has("money_thousands"):
            return thousands(v)
        if has("money_comma") and sep != ",":
            return dec_comma(v)
        return str(v)
    if kind == "int":
        if has("int_signed_string"):
            return f"{v:+d}"
        if has("int_padded"):
            return f" {v}"
        return str(v)
    if kind == "pi":
        if v == 1:
            return "1"
        num = Decimal(v.numerator) / Decimal(v.denominator)
        if has("pi_ratio"):
            return f"{v.numerator}/{v.denominator}"
        if has("pi_percent"):
            return f"{(num * 100).normalize()}%"
        if has("pi_comma"):
            return dec_comma(num.normalize())
        return str(num.normalize())
    if kind == "isoutc":
        if has("iso_fraction"):
            return iso_utc(v)[:-1] + ".000Z"
        if has("iso_offset"):
            return iso_utc(v)[:-1] + "+00:00"
        return iso_utc(v)
    if kind == "serial":
        return str((v - D(1899, 12, 30)).days)
    return str(v)


def money_eligible(rows, field):
    def ok(i):
        v = rows[i].get(field)
        return isinstance(v, Decimal) and v == v.quantize(Decimal("0.01")) and int(v * 100) % 2 == 1
    return ok


def plant_register(W, name, P, rows, cols, container, decoy):
    cap = W.cap_for(name, 40 if decoy else 20)
    qualify = decoy or len(cols) <= 3
    for col, field, kind in cols:
        for code, fam in VARIANTS.get(kind, []):
            q = f"{code}@{col}" if qualify else code
            if q in P.codes:
                continue
            if len(P.codes | W.trap_codes(name)) >= cap:
                break
            if container == "pdf" and code in ("key_homoglyph", "key_zwsp", "cust_homoglyph", "cust_zwsp"):
                continue
            if kind == "money":
                if code == "money_comma" and container in ("csv", "jsonl", "json"):
                    continue
                elig = money_eligible(rows, field) if code == "money_three_decimals" else None
                P.scatter(q, fam, rate=0.003, eligible=elig, desc=f"{kind} in column {col} written in a documented alternative form",
                          rule="spec 4 conventions")
            elif kind == "enddate":
                P.scatter(q, fam, rate=0.01, eligible=(lambda i, f=field: rows[i].get(f) is None) if code.startswith("open")
                          else None, desc=f"open or alternative end date in column {col}", rule="spec 4.5")
            else:
                P.scatter(q, fam, rate=0.003, desc=f"{kind} in column {col} written in a documented alternative form",
                          rule="spec 4 conventions")
            P.codes.add(q)
    base = container.split(":")[0]
    for code, fam in ROW_TRAPS.get(base, []):
        P.scatter(code, fam, rate=0.002, desc=f"{base} container convention", rule="spec 4 conventions")
        P.codes.add(code)
    anchor = {"csv_utf8_bom": 0, "tsv_utf8_bom": 0, "csv_reemitted_header": len(rows) * 9 // 20 + 1,
              "tsv_reemitted_header": len(rows) * 9 // 20 + 1, "docx_table_split_repeated_header": 3001,
              "pdf_page_header_repeats": 75, "html_repeated_header_rows": 101}
    for code, fam in FILE_TRAPS.get(base, []):
        W.trap(name, fam, code, recno=anchor.get(code, 0), desc=f"{base} layout convention", rule="spec 2.2 and 4")


def write_register(W, name):
    rows = W.recs[name]
    container, cols = COLS[name]
    base = container.split(":")[0]
    decoy = W.meta[name]["decoy"]
    P = Planter(W, name, len(rows))
    P.codes = set()
    plant_register(W, name, P, rows, cols, container, decoy)
    P.cover()
    sep = "\t" if base == "tsv" else ","
    text_rows = []
    for i, r in enumerate(rows):
        vals = []
        for col, field, kind in cols:
            v = r.get(field)
            if field == "reason" and v is None:
                v = ["customer request", "moved abroad, account consolidated", 'product "switch"',
                     "deceased; see register\nsecond line"][r["_h"] % 4]
            vals.append(emit(P, i, kind, v, sep, col))
        text_rows.append(vals)
    header = [c for c, _f, _k in cols]
    c = control_payload(W, name)
    if base in ("csv", "tsv"):
        delim = "\t" if base == "tsv" else ","
        comments = REGISTER_COMMENTS.get(name, [])
        drift_at = len(rows) * 9 // 20
        order = list(range(len(header)))
        if len(order) >= 3:
            order[1], order[2] = order[2], order[1]
        out = ["# " + x for x in comments] + [delim.join(header)]
        cur = list(range(len(header)))
        for i, vals in enumerate(text_rows):
            if i == drift_at:
                cur = order
                out.append(delim.join(header[j] for j in cur))
            line = delim.join(csv_cell(vals[j], delim) for j in cur)
            if base == "tsv" and P.has(i, "tsv_trailing_empty_field"):
                line += "\t"
            if base == "csv" and P.has(i, "csv_quoted_delimiter"):
                line = delim.join(('"' + vals[j].replace('"', '""') + '"') for j in cur)
            out.append(line)
        out.append("# CONTROL " + control_line(W, name))
        data = ("\n".join(out) + "\n").encode("utf-8")
        if base in ("csv", "tsv"):
            data = b"\xef\xbb\xbf" + data
        return data
    if base == "jsonl":
        out = []
        for i, vals in enumerate(text_rows):
            obj = dict(zip(header, vals))
            out.append(_json.dumps(obj, ensure_ascii=P.has(i, "jsonl_unicode_escapes") or i % 9 == 0))
        out.append(_json.dumps({"_control": c}))
        return ("\n".join(out) + "\n").encode("utf-8")
    if base == "json":
        key = container.split(":")[1]
        recs = []
        for i, vals in enumerate(text_rows):
            obj = dict(zip(header, vals))
            for (col, field, kind) in cols:
                if kind == "int" and not P.has(i, "int_signed_string") and not P.has(i, "int_padded"):
                    obj[col] = int(obj[col])
            if P.has(i, "json_null_field"):
                for col in header:
                    if obj[col] == "":
                        obj[col] = None
            recs.append(obj)
        obj = dict(JSON_META.get(name, {}))
        if name == "delivery_manifest.json":
            obj.update(manifest_meta(W))
        obj[key] = recs
        obj["control"] = c
        return (_json.dumps(obj, indent=1, ensure_ascii=False) + "\n").encode("utf-8")
    if base == "xml":
        tag = container.split(":")[1]
        root, ns = XML_ROOT[name]
        out = ['<?xml version="1.0" encoding="UTF-8"?>', f"<{root}{ns}>"]
        for i, vals in enumerate(text_rows):
            parts = []
            for h, v in zip(header, vals):
                t = _xesc(v)
                if P.has(i, "xml_entities"):
                    t = t.replace("A", "&#65;", 1).replace("C", "&#x43;", 1)
                if P.has(i, "xml_whitespace_text"):
                    t = f"\n      {t}\n    "
                parts.append(f"<{h}>{t}</{h}>")
            out.append(f"  <{tag}>" + "".join(parts) + f"</{tag}>")
        out.append("  <control " + " ".join(f'{k}="{v}"' for k, v in c.items()) + "/>")
        out.append(f"</{root}>")
        return ("\n".join(out) + "\n").encode("utf-8")
    if base == "xlsx":
        sheets_spec = container.split(":")[1].split(",")
        sheets = []
        for sh in sheets_spec:
            body = []
            for i, (r, vals) in enumerate(zip(rows, text_rows)):
                if len(sheets_spec) > 1 and r.get("_sheet") != sh:
                    continue
                cells = []
                for (col, field, kind), v in zip(cols, vals):
                    if kind in ("serial", "money") and not P.has(i, "xlsx_numeric_text_cells") and _re.fullmatch(r"-?\d+(\.\d+)?", v):
                        cells.append(("n", v))
                    else:
                        cells.append(("s", v))
                body.append(cells)
            sheets.append((sh, header, body))
        return write_xlsx(W, name, sheets)
    if base == "docx":
        blocks = list(DOCX_TEXT[name])
        chunk = 3000
        body = text_rows
        for k in range(0, len(body), chunk):
            blocks.append(("t", header, body[k:k + chunk]))
        foot = ()
        if name == "bad_definition_standard_v5.docx":
            foot = [("1", f"Draft for consultation. Not in force until change request {W.facts['crs']['BDS-V5'][0]} is approved.")]
        return docx_bytes(W, name, blocks, foot)
    if base == "pdf":
        title, prose = PDF_TEXT[name]
        pages = paginate(title, prose, header, text_rows)
        pages[-1].append("Delivery control: " + control_line(W, name))
        return pdf_bytes(pages)
    if base == "html":
        title, intro, rowspan_col, repeat = HTML_META[name]
        return html_doc(W, name, title, intro, header, text_rows, rowspan_col=rowspan_col, repeat=repeat,
                        key_col=header.index(HASHCOL[name]), nbsp=lambda i: P.has(i, "html_entities_nbsp"))
    raise ValueError(name)


