def manifest_meta(W):
    cert = []
    for ms, parts in SNAP_LAYOUT.items():
        for f, scope in parts:
            mk = {"ALL": MARKETS, "A": list(GROUP_A), "B": [m for m in MARKETS if m not in GROUP_A],
                  "A-CZ": ["GB", "PL", "SE"], "CZ": ["CZ"]}[scope]
            cert.append({"period": ms, "markets": mk, "file": f})
    return {"cycle": CYCLE, "ordering": "deliveries of the same cycle are ordered by delivered_at",
            "certified_snapshot_partitions": cert}


# ---------------------------------------------------------------------------
# Trap enrichment: field-level variants for the custom writers and the
# semantic trap census (instances located at the records they live in).
# ---------------------------------------------------------------------------
LATIN1_UNSAFE = {"key_homoglyph", "key_zwsp", "cust_homoglyph", "cust_zwsp"}
VARIANTS["intz"] = [("int_zero_pad", "T9")]


def plant_kinds(W, name, P, kinds, rate=0.003, latin1=False, no_comma=False, skip=(), cap=None):
    if not hasattr(P, "codes"):
        P.codes = set()
    cap = W.cap_for(name, cap or (40 if W.meta[name]["decoy"] else 20))
    for kind in kinds:
        for code, fam in VARIANTS.get(kind, []):
            if code in P.codes or code in skip or (latin1 and code in LATIN1_UNSAFE):
                continue
            if len(P.codes | W.trap_codes(name)) >= cap:
                return
            if no_comma and code == "money_comma":
                continue
            P.scatter(code, fam, rate=rate, desc=f"{kind} written in a documented alternative form", rule="spec 4 conventions")
            P.codes.add(code)


def emit_intz(P, i, v):
    return f"{v:04d}" if P.has(i, "int_zero_pad") else str(v)


def semantic_traps(W):
    decoy_packs(W)
    F, R = W.facts, W.recs
    acct_files = {}
    for f, rows in R.items():
        if W.meta[f]["kind"] in ("SNAP", "REPLICA"):
            for r in rows:
                if "month" in r:
                    acct_files[(f, r["acct"], r["month"])] = r["_recno"]
    for f, rn in sorted(F["quarantine"]):
        W.trap(f, "T6", "quarantined_record", recno=rn, desc="record quarantined in the data quality log", rule="dq log")
    certified = F["certified"]
    for src, keyset, fam, code in (("errata_register.md", [(r["acct"], r["month"]) for r in R["errata_register.md"] if r["status"] == "APPLIED"], "T7", "corrected_by_errata"),
                                   ("snapshot_corrections_feed.xml", [(r["acct"], r["month"]) for r in R["snapshot_corrections_feed.xml"]], "T7", "corrected_by_feed"),
                                   ("ops_corrections.mbox", [m["key"] for m in R["ops_corrections.mbox"] if m["kind"] == "corr"], "T7", "corrected_by_mail")):
        for acct, mo in keyset:
            a = W.acct_by_id.get(acct)
            if not a:
                continue
            f = certified.get((mo, a["market"]))
            rn = acct_files.get((f, acct, mo))
            if rn:
                W.trap(f, fam, code, recno=rn, accts=[acct], desc=f"value superseded by {src}", rule="governance 2.1")
    for gid, (acct, s, e) in F["grants"].items():
        a = W.acct_by_id.get(acct)
        if not a:
            continue
        for mo in range(s, e + 1):
            f = certified.get((mo, a["market"]))
            rn = acct_files.get((f, acct, mo))
            if rn:
                W.trap(f, "T14", "forborne_month", recno=rn, accts=[acct], desc="delinquency inside a forbearance grant",
                       rule="bad definition standard 3")
    for acct, mo in F["system_error"]:
        rn = acct_files.get(("snapshots_2025_10_b.tsv", acct, mo))
        if rn:
            W.trap("snapshots_2025_10_b.tsv", "T6", "system_error_voided", recno=rn, accts=[acct],
                   desc="certified DPD voided by a restatement flag", rule="governance 3.12")
    m11 = ym_index(2025, 11)
    for r in R["snapshots_2025_11_a_rev2.csv"]:
        if r["market"] == "CZ":
            W.trap("snapshots_2025_11_a_rev2.csv", "T13", "certified_only_for_cz", recno=r["_recno"], accts=[r["acct"]],
                   desc="row authoritative only because the manifest certifies CZ", rule="spec 5.1", direction="push")
    runs = F["runs"]
    void = F["void_runs"]
    for f, rows in R.items():
        if W.meta[f]["kind"] not in ("SCORE",):
            continue
        for r in rows:
            run = runs.get(r["run_id"])
            a = W.acct_by_id.get(r["acct"])
            if run is None or a is None:
                continue
            if r["run_id"] in void:
                W.trap(f, "T6", "event_in_void_run", recno=r["_recno"], accts=[r["acct"]], desc="event of a voided run",
                       rule="governance 3.4")
            elif run["status"] != "OK":
                W.trap(f, "T6", "event_in_aborted_run", recno=r["_recno"], accts=[r["acct"]], desc="event of an aborted run",
                       rule="spec 6.2")
            if run["version"] == "v4.0.2" and a["ddate"] >= D(2025, 5, 15):
                W.trap(f, "T13", "withdrawn_version_event", recno=r["_recno"], accts=[r["acct"]],
                       desc="model version withdrawn on the decision date", rule="governance 3.3")
            if "unapproved_version" in a["notes"] and run["version"] in ("v4.0.1", "v4.0.2"):
                W.trap(f, "T13", "version_not_approved_for_segment", recno=r["_recno"], accts=[r["acct"]],
                       desc="version not approved for the segment", rule="spec 6.3")
            if run["node"] in ("3", "6") and abs(r["ts"] - a["decision_utc"]) < 1200:
                W.trap(f, "T3", "clock_skew_near_decision", recno=r["_recno"], accts=[r["acct"]],
                       desc="skew correction moves the event across the decision instant", rule="spec 6.4")
            if r["score"] in (300, 1199):
                W.trap(f, "T15", "score_at_scale_bound", recno=r["_recno"], accts=[r["acct"]], desc="valid extreme score",
                       rule="model documentation scale")
    for f in APP_FILES.values():
        for r in R[f]:
            a = W.acct_by_id[r["acct"]]
            code = r["branch"] if not r["branch"].startswith("BR-") else F["branch_xwalk"][r["branch"]]
            if code in F["reused_branches"]:
                W.trap(f, "T13", "branch_code_reused", recno=r["_recno"], accts=[r["acct"]],
                       desc="branch code reused in another market", rule="spec 3.3")
            if r["limit"] >= Decimal("1000000"):
                W.trap(f, "T15", "large_limit_valid", recno=r["_recno"], accts=[r["acct"]], desc="very large but valid limit",
                       rule="limit policy")
            if any(x.startswith("dup_of:") for x in a["notes"]):
                W.trap(f, "T6", "duplicate_application_person", recno=r["_recno"], accts=[r["acct"]],
                       desc="second application by the same person", rule="spec 3.6")
            if r["acct"] in F["reversed_wd"]:
                W.trap(f, "T6", "withdrawal_reversed_elsewhere", recno=r["_recno"], accts=[r["acct"]],
                       desc="withdrawal reversed in the master extract", rule="governance 3.6")
    wd_rows = {r["acct"]: r["_recno"] for r in R["application_withdrawals.json"]}
    for acct, d in F["withdrawals"]:
        a = W.acct_by_id.get(acct)
        if a and acct in wd_rows:
            days = (d - a["ddate"]).days
            W.trap("application_withdrawals.json", "T11", "withdrawal_day_boundary" if days in (14, 15) else "withdrawal_window",
                   recno=wd_rows[acct], accts=[acct], desc=f"withdrawal {days} days after decision", rule="spec 3.5")
            if acct in F["reversed_wd"]:
                W.trap("application_withdrawals.json", "T6", "withdrawal_later_reversed", recno=wd_rows[acct], accts=[acct],
                       desc="withdrawal reversed", rule="governance 3.6")
    for f, rows in (("account_closures_2025.json", R["account_closures_2025.json"]), ("account_closures_2026h1.csv", R["account_closures_2026h1.csv"])):
        for r in rows:
            a = W.acct_by_id.get(r["acct"])
            if a and r["date"] == month_start(a["cmonth"] + 6):
                W.trap(f, "T11", "closure_on_month_six_start", recno=r["_recno"], accts=[r["acct"]],
                       desc="closure exactly on the first day of month c+6", rule="bad definition standard 4")
            elif a:
                W.trap(f, "T11", "closure_window", recno=r["_recno"], accts=[r["acct"]], desc="cohort closure", rule="bad definition standard 4")
    for f, field in (("litigation_hold_register.html", "to"),):
        for r in R[f]:
            a = W.acct_by_id.get(r["acct"])
            if a and r[field] == a["ddate"]:
                W.trap(f, "T11", "hold_ends_on_decision_date", recno=r["_recno"], accts=[r["acct"]], desc="inclusive end",
                       rule="erratum E-011")
            elif a and r["from"] > a["ddate"]:
                W.trap(f, "T11", "hold_starts_after_decision", recno=r["_recno"], accts=[r["acct"]], desc="hold after decision",
                       rule="exclusion policy 2.2")
    leaves = {}
    for r in R["employee_leavers.tsv"]:
        leaves.setdefault(r["emp"], []).append(r)
    staff_custs = {}
    for a in W.cohort_like:
        staff_custs[a["cust"]] = a
    for r in R["exclusion_policy.docx"]:
        a = staff_custs.get(r["cust"]) or staff_custs.get(F["alias"].get(r["cust"], ""))
        if a:
            W.trap("exclusion_policy.docx", "T13", "employee_customer_alias" if r["cust"] != a["cust"] else "employee_is_customer",
                   recno=r["_recno"], accts=[a["acct"]], desc="employee register names a cohort customer", rule="exclusion policy 2.1")
            for lv in leaves.get(r["emp"], ()):
                W.trap("employee_leavers.tsv", "T11", "leave_relative_to_decision", recno=lv["_recno"], accts=[a["acct"]],
                       desc="leave date relative to the decision date", rule="exclusion policy 2.1")
    for f, key, fam, code in (("regulatory_exclusion_letter_2026.pdf", "date", "T11", "notice_vs_window_end"),
                              ("deceased_notifications_feed.xml", "date", "T11", "notification_vs_window_end")):
        for r in R[f]:
            a = W.acct_by_id.get(r.get("acct", "")) if "acct" in r else None
            if a:
                W.trap(f, fam, code, recno=r["_recno"], accts=[a["acct"]], desc="date compared with the window end",
                       rule="exclusion policy 2")
    cust_acct = {a["cust"]: a for a in W.cohort_like}
    for f in ("deceased_notifications_feed.xml", "deceased_notifications_register.pdf"):
        for r in R[f]:
            a = cust_acct.get(r["cust"])
            if a:
                W.trap(f, "T11", "deceased_vs_window_end", recno=r["_recno"], accts=[a["acct"]], desc="notification vs window end",
                       rule="exclusion policy 2.5")
    for f in ("fraud_alerts_2025.jsonl", "fraud_alerts_2026.xml"):
        for r in R[f]:
            a = W.acct_by_id.get(r["acct"])
            if a:
                st = F["disp"][r["case"]]
                W.trap(f, "T6" if st != "CONFIRMED" else "T11", "alert_not_confirmed" if st != "CONFIRMED" else "confirmed_alert_vs_window",
                       recno=r["_recno"], accts=[a["acct"]], desc=f"fraud alert with disposition {st}", rule="exclusion policy 2.6")
    for r in R["customer_merges_2026.tsv"]:
        if r["merged"].startswith("LCU") or r["survivor"].startswith("LCU"):
            W.trap("customer_merges_2026.tsv", "T13", "legacy_customer_id", recno=r["_recno"], desc="legacy id needs the ML legacy sheet",
                   rule="governance 3.10")
        if r["status"] != "APPROVED":
            W.trap("customer_merges_2026.tsv", "T6", "merge_not_approved", recno=r["_recno"], desc="merge decision not approved",
                   rule="merge decisions")
    for r in R["customer_merge_decisions.docx"]:
        if r["status"] != "APPROVED":
            W.trap("customer_merge_decisions.docx", "T6", "merge_not_approved", recno=r["_recno"], desc="merge not approved",
                   rule="merge decisions")
    for r in R["sampling_methodology.docx"]:
        if r["status"] != "APPROVED" and r["acct"] in W.acct_by_id:
            W.trap("sampling_methodology.docx", "T6", "override_rejected", recno=r["_recno"], accts=[r["acct"]], desc="rejected override",
                   rule="sampling 2.3")
        if r["pi"] == Fraction(1, 8):
            W.trap("sampling_methodology.docx", "T15", "weight_eight_valid", recno=r["_recno"], desc="weight 8 is valid", rule="sampling 1")
    for r in R["limit_amendments_2025.xlsx"] + R["limit_management_policy.docx"]:
        a = W.acct_by_id.get(r["acct"])
        f = "limit_amendments_2025.xlsx" if "_sheet" in r else "limit_management_policy.docx"
        if a:
            mend = month_end(a["cmonth"])
            code = "amendment_on_month_end" if r["date"] == mend else ("amendment_after_month_end" if r["date"] > mend else
                                                                      ("amendment_before_decision" if r["date"] < a["ddate"] else "amendment_in_month"))
            W.trap(f, "T11", code, recno=r["_recno"], accts=[a["acct"]], desc="amendment relative to the exposure basis",
                   rule="limit policy 4.1")
    for r in R["product_migrations_2025.xlsx"]:
        a = W.acct_by_id.get(r["acct"])
        if a and r["date"] > a["ddate"]:
            W.trap("product_migrations_2025.xlsx", "T7", "migration_after_decision", recno=r["_recno"], accts=[a["acct"]],
                   desc="later product state must be rolled back", rule="spec 3.4")
    for r in R["currency_redenomination.ini"]:
        a = W.acct_by_id.get(r["acct"])
        if a:
            W.trap("currency_redenomination.ini", "T2", "currency_differs_from_market", recno=r["_recno"], accts=[a["acct"]],
                   desc="exposure currency differs from the market currency", rule="limit policy 4.2")
    for r in R["audit_label_confirmations.pdf"]:
        if r["acct"] in W.acct_by_id:
            W.trap("audit_label_confirmations.pdf", "T14", "audit_override", recno=r["_recno"], accts=[r["acct"]],
                   desc="audited label replaces the derived label", rule="bad definition standard 5")
    for r in R["forbearance_extensions_register.pdf"]:
        g = F["grants"].get(r["gid"])
        if g and g[0] in W.acct_by_id:
            W.trap("forbearance_extensions_register.pdf", "T7", "extension_moves_end", recno=r["_recno"], accts=[g[0]],
                   desc="extension supersedes the granted end month", rule="bad definition standard 3")
    for r in R["bad_definition_standard.docx"]:
        if r["acct"] in W.acct_by_id:
            W.trap("bad_definition_standard.docx", "T11", "grant_months_inclusive", recno=r["_recno"], accts=[r["acct"]],
                   desc="grant months are inclusive", rule="bad definition standard 3")
    for r in R["bad_definition_standard_v5.docx"]:
        if r["gid"] in F["grants"] and F["grants"][r["gid"]][0] in W.acct_by_id:
            W.trap("bad_definition_standard_v5.docx", "T6", "grant_revoked", recno=r["_recno"], accts=[F["grants"][r["gid"]][0]],
                   desc="revocation voids a grant", rule="governance 3.5", direction="push")
    co_cohort = {eid: acct for eid, acct, _d in F["co_all"] if acct in W.acct_by_id}
    for r in R["status_events_consolidated.json"]:
        if r["type"] == "CO_REVERSAL" and r["ref"] in co_cohort:
            W.trap("status_events_consolidated.json", "T6", "chargeoff_reversed", recno=r["_recno"], accts=[co_cohort[r["ref"]]],
                   desc="reversal voids a charge-off", rule="bad definition standard 2.4", direction="push")
        if r["type"] == "DECEASED" and r["source"] == "CIVIL_REGISTRY":
            W.trap("status_events_consolidated.json", "T13", "civil_registry_authoritative", recno=r["_recno"],
                   desc="authoritative row inside a non-authoritative feed", rule="governance 3.11", direction="push")
        if r["type"] == "FRAUD" and r["subject"] in W.acct_by_id:
            W.trap("status_events_consolidated.json", "T16", "fraud_alert_without_disposition", recno=r["_recno"], accts=[r["subject"]],
                   desc="alert labelled FRAUD without a confirmed disposition", rule="exclusion policy 2.6", direction="pull")
    for f in ("status_events_chargeoff_2025.csv", "chargeoff_events_2026.parquet"):
        for r in R[f]:
            if r["eid"] in co_cohort:
                rev = F["co_reversals"].get(r["eid"])
                W.trap(f, "T6" if rev and (rev - r["date"]).days <= 60 else "T11",
                       "chargeoff_reversed_elsewhere" if rev and (rev - r["date"]).days <= 60 else "chargeoff_in_window",
                       recno=r["_recno"], accts=[co_cohort[r["eid"]]], desc="charge-off event of a cohort account",
                       rule="bad definition standard 2.4")
    for i, r in enumerate(R["treasury_fixings_2024_2026.xml"]):
        if r["date"].day >= 27 and r["date"].month <= 6 and r["date"].year == 2025:
            W.trap("treasury_fixings_2024_2026.xml", "T11", "month_end_fixing", recno=r["_recno"], desc="fixing near a decision month end",
                   rule="limit policy 4.3")
    for r in R["market_holidays.ics"]:
        if r["date"].year == 2025 and r["date"].month <= 7 and r["cat"] != "SETTLEMENT-CUTOFF":
            W.trap("market_holidays.ics", "T11" if r["cat"] != "OBSERVANCE" else "T15",
                   "closure_in_cohort_period" if r["cat"] != "OBSERVANCE" else "observance_in_cohort_period", recno=r["_recno"],
                   desc=f"{r['cat']} in the cohort months", rule="limit policy 4.3")
    for r in R["data_quality_issue_log.md"]:
        if r["disp"] != "QUARANTINE":
            W.trap("data_quality_issue_log.md", "T6", "accepted_issue_no_action", recno=r["_recno"], desc="issue needing no action",
                   rule="dq log preamble")
    for r in R["errata_register.md"]:
        if r["acct"] in W.acct_by_id and r["status"] == "REJECTED":
            W.trap("errata_register.md", "T6", "rejected_erratum_cohort", recno=r["_recno"], accts=[r["acct"]], desc="rejected erratum",
                   rule="errata preamble")
    for r in R["snapshot_corrections_feed.xml"]:
        if r["acct"] in W.acct_by_id:
            W.trap("snapshot_corrections_feed.xml", "T7", "seq_supersedes", recno=r["_recno"], accts=[r["acct"]], desc="highest seq wins",
                   rule="governance 2.2")
    for r in R["ops_corrections.mbox"]:
        if r["kind"] == "retract":
            W.trap("ops_corrections.mbox", "T6", "retraction", recno=r["_recno"], desc="retracts an earlier correction", rule="governance 2.3")
    for f in ("sampling_inclusion_gb_pl_se.yaml", "sampling_inclusion_cz_hu_ch.yaml", "sampling_inclusion_dk_no.yaml"):
        for r in R[f]:
            if r["cohort"] == "2025-04":
                W.trap(f, "T13", "keyed_by_application_id", recno=r["_recno"], desc="April strata keyed by application id",
                       rule="sampling 2.1")
                break
        for r in R[f]:
            if r["pi"] == Fraction(1, 8):
                W.trap(f, "T15", "weight_eight", recno=r["_recno"], desc="largest design weight", rule="sampling 1")
                break


