def type_packs(W):
    for name, meta in W.meta.items():
        limit = 40 if meta["decoy"] else 17
        for fam, code in TYPE_PACKS.get(meta["type"], []):
            if len(W.trap_codes(name)) >= limit:
                break
            W.trap(name, fam, code, recno=0, desc=code.replace("_", " "), rule="specification catalogue")


def decoy_packs(W):
    for name, items in INSCOPE_PACKS.items():
        for fam, code, desc in items:
            W.trap(name, fam, code, recno=0, desc=desc, rule="specification and catalogue")
    for name, items in DECOY_PACKS.items():
        if name not in W.meta:
            continue
        for fam, code, desc, d in items:
            W.trap(name, fam, code, recno=0, desc=desc, rule="governance policy", direction=d)
    type_packs(W)


# ---------------------------------------------------------------------------
# Custom deliveries with field-level variants (configuration, documents,
# feeds and the decoys that need the richest trap coverage).
# ---------------------------------------------------------------------------
VARIANTS["pd"] = [("pd_comma", "T4"), ("pd_trailing_zeros", "T4"), ("pd_padded", "T9")]
VARIANTS["count"] = [("count_thousands", "T4"), ("count_padded", "T9")]
VARIANTS["yscalar"] = [("yaml_quoted_scalar", "T9"), ("yaml_trailing_comment", "T9"), ("yaml_flow_mapping", "T8")]


def emit_pd(P, i, v, col=None):
    has = lambda c: P.has(i, c) or (col is not None and P.has(i, f"{c}@{col}"))
    t = str(v)
    if has("pd_trailing_zeros"):
        t = t + "00"
    if has("pd_comma"):
        t = t.replace(".", ",")
    if has("pd_padded"):
        t = f" {t} "
    return t


def emit_count(P, i, v):
    if P.has(i, "count_thousands") and v >= 1000:
        return f"{v:,}"
    if P.has(i, "count_padded"):
        return f"{v:>6}"
    return str(v)


def P_for(W, name, rows, kinds, **kw):
    P = Planter(W, name, len(rows))
    P.codes = set()
    plant_kinds(W, name, P, kinds, **kw)
    return P


def plant_q(W, name, P, kind, col, latin1=False):
    cap = W.cap_for(name, 40 if W.meta[name]["decoy"] else 20)
    for code, fam in VARIANTS.get(kind, []):
        if latin1 and code in LATIN1_UNSAFE:
            continue
        q = f"{code}@{col}"
        if q in P.codes or len(P.codes | W.trap_codes(name)) >= cap:
            continue
        P.scatter(q, fam, rate=0.003, desc=f"{kind} in {col} written in a documented alternative form", rule="spec 4 conventions")
        P.codes.add(q)


def ftrap(W, name, family, code, desc, rule, recno=0, direction=""):
    W.trap(name, family, code, recno=recno, desc=desc, rule=rule, direction=direction)


def write_yaml_v(W, name):
    rows = W.recs[name]
    decoy = W.meta[name]["decoy"]
    P = Planter(W, name, len(rows))
    P.codes = set()
    plant_keys(P, ["key_space", "key_lower", "key_homoglyph", "key_zero_pad"])
    for kind in ("pi", "month", "yscalar", "id"):
        if decoy:
            plant_q(W, name, P, kind, "entry")
        else:
            plant_kinds(W, name, P, [kind])
    P.cover()
    has = lambda i, c: P.has(i, c) or P.has(i, f"{c}@entry")
    ftrap(W, name, "T5", "yaml_norway_bool", "market code NO parses as boolean under YAML 1.1", "spec 4.4")
    if decoy:
        for fam, code, desc in (("T16", "v2_design_newer_label", "design PSD-2025H1-v2 looks like the current design"),
                                ("T14", "v2_effective_cohorts_header", "effective cohorts declared only in the header"),
                                ("T16", "v2_backtest_values_for_earlier_cohorts", "planning values for 2025-01..05 accounts"),
                                ("T11", "v2_future_cohort_entries", "entries for the 2026-01 cohort"),
                                ("T8", "yaml_document_separator", "document starts with a --- separator"),
                                ("T13", "june_entries_authoritative", "2025-06 entries are the only June probabilities")):
            ftrap(W, name, fam, code, desc, "sampling methodology 2.1 / governance 3.14",
                  direction="pull" if fam == "T16" else "push")
    lines = ["---"] if decoy else []
    design = "PSD-2025H1-v2" if decoy else "PSD-2025H1"
    lines.append(f"design: {design}")
    if decoy:
        lines.append("effective_cohorts: from 2025-06 (approved under the v2 redesign)")
        lines.append("note: entries for earlier cohorts are planning values for the v2 back-test")
    lines.append("inclusion:")
    for i, r in enumerate(rows):
        key = r["key"]
        key = key_of(P, i, key) if key.startswith("AC") else (key.lower() if has(i, "id_lower") else key)
        pi = emit(P, i, "pi", r["pi"], ";", "entry")
        if pi == str(Fraction(r["pi"])) and pi_text(r["pi"], i) != pi:
            pi = pi_text(r["pi"], i)
        coh = emit(P, i, "month", ym_index(int(r["cohort"][:4]), int(r["cohort"][5:])), ";", "entry")
        mk = r["market"]
        q = has(i, "yaml_quoted_scalar")
        if q:
            key, pi, coh = f"'{key}'", f'"{pi}"', f"'{coh}'"
        if has(i, "yaml_flow_mapping"):
            pq = pi if pi.startswith('"') else f'"{pi}"'
            lines.append(f"  - {{key: {key}, pi: {pq}, cohort: {coh}, market: {mk}}}")
            continue
        lines.append(f"  - key: {key}")
        lines.append(f"    pi: {pi}" + ("  # redrawn stratum" if has(i, "yaml_trailing_comment") else ""))
        lines.append(f"    cohort: {coh}")
        lines.append(f"    market: {mk}")
    c = control_payload(W, name)
    lines.append("delivery_control:")
    for k, v in c.items():
        lines.append(f"  {k}: {v}")
    return ("\n".join(lines) + "\n").encode("utf-8")


def write_toml_v(W, name):
    rows = W.recs[name]
    decoy = W.meta[name]["decoy"]
    out = []
    if name == "model_registry_v4.toml":
        out += ['title = "PD-RETAIL v4 model registry (in force)"', 'registry_version = "4.0"', ""]
        for k, (ver, segs, start, end) in enumerate(W.facts["approvals"]):
            seg_txt = ", ".join(f'"{s.lower() if k == 1 else s}"' for s in SEGMENTS if s in segs)
            out += ["[[approval]]", f'model = "{ver}"', f"segments = [{seg_txt}]",
                    f'effective_from = "{start.isoformat()}"' if k == 2 else f"effective_from = {start.isoformat()}"]
            if end:
                out.append(f"effective_to = {end.isoformat()}")
            out.append("")
        ftrap(W, name, "T1", "approval_segments_lowercase", "segment names in lower case", "spec 3.1")
        ftrap(W, name, "T3", "approval_date_as_string", "effective_from written as a string", "catalogue")
    if not decoy:
        P = Planter(W, name, len(rows))
        P.codes = set()
        plant_kinds(W, name, P, ["id", "status"])
        P.cover()
        if name == "scoring_runs_2025q2.toml":
            out += ['title = "Scoring run register from 2025-04-01"', ""]
        ftrap(W, name, "T5", "node_int_vs_string", "node written as integer or string", "catalogue")
        nodes = set()
        for i, r in enumerate(rows):
            node = r["node"]
            node_txt = node if node.isdigit() and i % 3 else f'"{node}"'
            started = iso_utc(r["start"]) if i % 7 else f'"{iso_utc(r["start"])}"'
            out += ["[[run]]", f'run_id = "{emit(P, i, "id", r["run_id"])}"', f"node = {node_txt}", f'model = "{r["version"]}"',
                    f'status = "{emit(P, i, "status", r["status"])}"', f"started = {started}", ""]
            if r["status"] != "OK":
                W.trap(name, "T6", "aborted_run", recno=i + 1, desc="run status not OK", rule="spec 6.2")
            if node == "9" and "9" not in nodes:
                W.trap(name, "T13", "dr_replay_host_runs", recno=i + 1, desc="node 9 runs are replays", rule="spec 6.2")
            if r["version"] == "v4.1-rc" and "rc" not in nodes:
                W.trap(name, "T13", "shadow_version_runs", recno=i + 1, desc="run version never approved", rule="spec 6.3")
                nodes.add("rc")
            if not W.facts["runs"][r["run_id"]]["events"] and "empty" not in nodes:
                W.trap(name, "T15", "run_without_events", recno=i + 1, desc="registered run without events", rule="spec 6.1")
                nodes.add("empty")
            nodes.add(node)
        ftrap(W, name, "T3", "started_string_or_datetime", "started as TOML datetime or string", "catalogue")
    else:
        P = Planter(W, name, len(rows))
        P.codes = set()
        for kind, col in (("status", "segment"), ("intz", "score"), ("pd", "pd")):
            plant_q(W, name, P, kind, col)
        P.cover()
        crs = W.facts["crs"]
        out += ['# APPROVED registry - supersedes v4.0 on 2025-06-01', 'title = "PD-RETAIL v4.1 model registry - APPROVED FOR PRODUCTION \u2713"',
                'meta.owner = "model-risk"', 'meta.contact = { team = "MRM", room = "4.12" }', 'registry_version = "4.1"',
                f'change_request = "{crs["REG-V41"][0].lower()}"', "", "[[approval]]", 'model = "v4.1-rc"',
                "segments = [" + ", ".join(f'"{s}"' for s in SEGMENTS) + "]", "effective_from = 2025-06-01", ""]
        for ver, d in W.facts["withdrawals_ver"]:
            out += ["[[withdrawal]]", f'model = "{ver}"', f"withdrawn_from = {d.isoformat()}",
                    f'change_request = "{crs["REG-V402-WD"][0]}"',
                    'reason = """hotfix produced "non-monotone" scores\nfor thin-file applicants"""', ""]
        for fam, code, desc, d in (("T16", "newer_registry_version", "v4.1 registry looks newer and complete", "pull"),
                                   ("T14", "approved_label_in_title", "title claims production approval", "pull"),
                                   ("T13", "draft_change_request", "registry change request is DRAFT", "push"),
                                   ("T6", "withdrawal_authoritative", "only publication of the v4.0.2 withdrawal", "push"),
                                   ("T1", "cr_id_lower_case", "change request id in lower case", ""),
                                   ("T9", "multiline_basic_string", "reason is a multi-line string with quotes", ""),
                                   ("T3", "withdrawal_local_date", "withdrawn_from is a TOML local date", ""),
                                   ("T7", "calibration_points_superseded", "v4.1 points never in force", "pull"),
                                   ("T15", "points_cover_scale_bounds", "points at 300 and 1199", ""),
                                   ("T11", "approval_from_june", "approval would start 2025-06-01", "pull")):
            ftrap(W, name, fam, code, desc, "governance 3.3", direction=d)
        for i, r in enumerate(rows):
            score_txt = f'"{r["score"]:04d}"' if P.has(i, "int_zero_pad@score") else str(r["score"])
            out += ["[[calibration_point]]", f'segment = "{emit(P, i, "status", r["seg"], ";", "segment")}"',
                    f"score = {score_txt}", f'pd = "{emit_pd(P, i, r["pd"], "pd")}"', ""]
    c = control_payload(W, name)
    out.append("[delivery_control]")
    for k, v in c.items():
        out.append(f'{k} = "{v}"' if isinstance(v, str) else f"{k} = {v}")
    return ("\n".join(out) + "\n").encode("utf-8")


def write_ini_v(W, name):
    rows = W.recs[name]
    P = Planter(W, name, len(rows))
    P.codes = set()
    c = control_payload(W, name)
    out = []
    if name == "product_code_crosswalk.ini":
        plant_kinds(W, name, P, ["code"])
        P.scatter("ini_colon_delimiter", "T9", rate=0.004, desc="key: value form", rule="catalogue ini rules")
        P.scatter("ini_inline_comment", "T9", rate=0.004, desc="value followed by ; comment", rule="catalogue ini rules")
        P.codes |= {"ini_colon_delimiter", "ini_inline_comment"}
        P.cover()
        for fam, code, desc in (("T9", "ini_default_section_propagates", "DEFAULT keys appear in every section"),
                                ("T1", "section_names_case", "one section header in lower case"),
                                ("T9", "comment_lines_hash", "# comment lines between keys"),
                                ("T13", "current_codes_from_migrations", "codes reached only through migrations")):
            ftrap(W, name, fam, code, desc, "catalogue ini rules")
        out += ["; legacy product code to monitoring segment", "[DEFAULT]", "owner = retail-risk", "review = annual", ""]
        for si, seg in enumerate(SEGMENTS):
            out.append(f"[{seg.lower() if si == 3 else seg}]")
            out.append("# codes issued by the product factory")
            for i, r in enumerate(rows):
                if r["product"] == seg:
                    code = emit(P, i, "code", r["code"]).strip()
                    sep = ":" if P.has(i, "ini_colon_delimiter") else "="
                    tail = " ; retail book" if P.has(i, "ini_inline_comment") else ""
                    out.append(f"{code} {sep} {seg.lower()} product line{tail}")
            out.append("")
    elif name == "legacy_account_map.ini":
        plant_kinds(W, name, P, ["acct", "id"])
        P.scatter("ini_inline_comment", "T9", rate=0.004, desc="value followed by ; comment", rule="catalogue ini rules")
        P.codes.add("ini_inline_comment")
        P.cover()
        ftrap(W, name, "T9", "ini_percent_interpolation", "a literal % breaks default interpolation", "catalogue ini rules")
        ftrap(W, name, "T13", "default_key_looks_like_legacy_number", "DEFAULT holds L-0000000 = unknown", "catalogue ini rules")
        out += ["[DEFAULT]", "note = mapping 100% verified by migration team", "L-0000000 = unknown", "", "[legacy_accounts]"]
        for i, r in enumerate(rows):
            key = r["legacy"].lower() if P.has(i, "id_lower") else r["legacy"]
            tail = " ; migrated 2019" if P.has(i, "ini_inline_comment") else ""
            out.append(f"{key} = {key_of(P, i, r['acct'])}{tail}")
        out.append("")
    else:
        plant_kinds(W, name, P, ["acct"], skip=("key_space",))
        P.scatter("iso_numeric_zero_padded", "T13", rate=0.004, desc="numeric code with a leading zero", rule="governance 3.8")
        P.scatter("ini_inline_comment", "T9", rate=0.004, desc="value followed by ; comment", rule="catalogue ini rules")
        P.codes |= {"iso_numeric_zero_padded", "ini_inline_comment"}
        P.cover()
        for fam, code, desc in (("T13", "iso_numeric_currency", "numeric currency codes resolve via the ECB mirror crosswalk"),
                                ("T15", "non_market_currency_codes", "USD and EUR denominations are valid"),
                                ("T9", "ini_colon_delimiter_file", "some keys use ':'")):
            ftrap(W, name, fam, code, desc, "governance 3.8")
        out += ["; account level currency of denomination, ISO 4217 numeric", "[redenominated]"]
        iso = W.facts["iso_num"]
        for i, r in enumerate(rows):
            num = iso[r["ccy"]]
            if P.has(i, "iso_numeric_zero_padded"):
                num = "0" + num
            sep = ":" if i % 211 == 7 else "="
            tail = " ; per contract" if P.has(i, "ini_inline_comment") else ""
            out.append(f"{key_of(P, i, r['acct'])} {sep} {num}{tail}")
        out.append("")
    out.append("[delivery_control]")
    for k, v in c.items():
        out.append(f"{k} = {v}")
    return ("\n".join(out) + "\n").encode("utf-8")


def write_fx_v(W, name):
    rows = W.recs[name]
    P = Planter(W, name, len(rows))
    P.codes = set()
    for code, fam, desc in (("ccy_lowercase", "T1", "currency attribute in lower case"), ("value_padded", "T9", "value with surrounding spaces"),
                            ("value_decimal_comma", "T4", "value with a decimal comma"), ("rev_omitted", "T5", "rev omitted means 1"),
                            ("per_omitted", "T5", "per omitted means 1")):
        P.scatter(code, fam, rate=0.004, desc=desc, rule="limit policy 4.4")
        P.codes.add(code)
    P.cover()
    for fam, code, desc in (("T9", "xml_comments", "comments between fixings"), ("T9", "cdata_value", "a value wrapped in CDATA")):
        ftrap(W, name, fam, code, desc, "catalogue")
    out = ['<?xml version="1.0" encoding="UTF-8"?>', '<fixings source="group-treasury" quote="EUR value of per units of currency">',
           "  <!-- rev and per default to 1 when omitted -->"]
    seen = set()
    for i, r in enumerate(rows):
        if r["rev"] == 2:
            W.trap(name, "T7", "fixing_revision", recno=i + 1, desc="revision 2 supersedes the published fixing", rule="limit policy 4.4")
        if r["ccy"] == "HUF" and "HUF" not in seen:
            seen.add("HUF")
            W.trap(name, "T2", "huf_per_100", recno=i + 1, desc="HUF quoted per 100 units", rule="limit policy 4.4")
        ccy = r["ccy"].lower() if P.has(i, "ccy_lowercase") else r["ccy"]
        val = str(r["eur"])
        if P.has(i, "value_decimal_comma"):
            val = val.replace(".", ",")
        if P.has(i, "value_padded"):
            val = f"  {val} "
        if i == 17:
            val = f"<![CDATA[{val}]]>"
        attrs = f'ccy="{ccy}" date="{r["date"].isoformat()}"'
        if not (P.has(i, "per_omitted") and r["per"] == 1):
            attrs += f' per="{r["per"]}"'
        if not (P.has(i, "rev_omitted") and r["rev"] == 1):
            attrs += f' rev="{r["rev"]}"'
        out.append(f"  <fixing {attrs}>{val}</fixing>")
        if i % 997 == 500:
            out.append("  <!-- end of publication batch -->")
    for ccy, d in W.facts["fx_gaps"]:
        W.trap(name, "T15", "publication_gap", recno=None, desc=f"no fixing for {ccy} on {d}", rule="limit policy 4.4 as-of")
    c = control_payload(W, name)
    out.append("  <control " + " ".join(f'{k}="{v}"' for k, v in c.items()) + "/>")
    out.append("</fixings>")
    return ("\n".join(out) + "\n").encode("utf-8")


def write_ecb_v(W, name):
    rows = W.recs[name]
    P = Planter(W, name, len(rows))
    P.codes = set()
    codes = [("ccy_lowercase", "T1"), ("ccy_padded", "T9"), ("rate_decimal_comma", "T4"), ("rate_padded", "T9"),
             ("rate_char_reference", "T9"), ("rate_not_available", "T5"), ("rate_scientific", "T4"), ("rate_extra_decimals", "T12"),
             ("rate_cdata", "T9")]
    for code, fam in codes:
        P.scatter(code, fam, rate=0.003, desc=code.replace("_", " "), rule="governance 3.8 (values not used)", direction="push")
        P.codes.add(code)
    P.cover()
    for fam, code, desc, d in (("T16", "rates_forward_filled_weekends", "calendar days forward-filled including weekends", "pull"),
                               ("T16", "rates_on_market_holidays", "rates published on market holidays", "pull"),
                               ("T2", "inverted_quotation", "units of currency per EUR, inverse of treasury", ""),
                               ("T13", "iso_numeric_crosswalk_only_here", "only list of ISO numeric codes", "push"),
                               ("T13", "iso_numeric_with_leading_zero", "AUD is 036", ""),
                               ("T16", "complete_coverage_label", "provider label suggests completeness", "pull"),
                               ("T14", "reference_only_declared", "mirror is reference-only per governance", "push"),
                               ("T6", "withdrawn_currency_codes", "codes of withdrawn currencies", ""),
                               ("T9", "xml_default_namespace", "elements in a default namespace", ""),
                               ("T10", "utf8_bom", "byte order mark", ""),
                               ("T10", "currency_names_diacritics", "currency names with diacritics", ""),
                               ("T15", "eur_rate_is_one", "EUR listed at 1", ""),
                               ("T7", "sections_unsorted", "currency sections not in date order", ""),
                               ("T9", "xml_comments", "comments inside the rate list", ""),
                               ("T8", "two_element_types", "rates and code list share one document", "")):
        ftrap(W, name, fam, code, desc, "governance 3.8", direction=d)
    out = ['<?xml version="1.0" encoding="UTF-8"?>',
           '<rates xmlns="urn:example-bank:refrates:v1" provider="ECB reference mirror - complete daily series" '
           'quote="units of currency per 1 EUR" fill="calendar days forward-filled">',
           "  <!-- mirror refreshed 2026-06-30; reference only -->"]
    for i, r in enumerate(rows):
        ccy = r["ccy"]
        if P.has(i, "ccy_lowercase"):
            ccy = ccy.lower()
        if P.has(i, "ccy_padded"):
            ccy = f" {ccy} "
        val = str(r["rate"])
        if P.has(i, "rate_decimal_comma"):
            val = val.replace(".", ",")
        elif P.has(i, "rate_scientific"):
            val = f"{float(r['rate']):.6e}"
        elif P.has(i, "rate_extra_decimals"):
            val = val + "0137"
        elif P.has(i, "rate_not_available"):
            val = "N/A"
        if P.has(i, "rate_char_reference"):
            val = val.replace("1", "&#49;", 1)
        if P.has(i, "rate_padded"):
            val = f"  {val}  "
        if P.has(i, "rate_cdata"):
            val = f"<![CDATA[{val}]]>"
        out.append(f'  <rate ccy="{ccy}" date="{r["date"].isoformat()}">{val}</rate>')
    names = {"PLN": "z\u0142oty", "CZK": "koruna \u010desk\u00e1", "HUF": "forint", "SEK": "krona", "DKK": "krone", "NOK": "krone",
             "CHF": "Franken", "GBP": "pound sterling", "EUR": "euro"}
    out.append("  <isoCodes>")
    for alpha, num in W.ecb_codes:
        out.append(f'    <currency alpha="{alpha}" numeric="{num}" name="{names.get(alpha, alpha)}"/>')
    for alpha, num in (("LTL", "440"), ("EEK", "233"), ("LVL", "428")):
        out.append(f'    <currency alpha="{alpha}" numeric="{num}" withdrawn="2015"/>')
    out.append("  </isoCodes>")
    c = control_payload(W, name)
    out.append("  <control " + " ".join(f'{k}="{v}"' for k, v in c.items()) + "/>")
    out.append("</rates>")
    return b"\xef\xbb\xbf" + ("\n".join(out) + "\n").encode("utf-8")


def write_db_v(W, name):
    rows = W.recs[name]
    decoy = W.meta[name]["decoy"]
    P = Planter(W, name, len(rows))
    P.codes = set()
    if name == "customer_master.db":
        for col in ("alias", "master", "customer"):
            plant_q(W, name, P, "cust", col)
        plant_q(W, name, P, "date", "customer_since")
        P.cover()
        ftrap(W, name, "T13", "alias_targets_merged_customer", "alias master later merged", "spec 3.6")
        ftrap(W, name, "T8", "two_tables_one_delivery", "records counted across both tables", "spec 2.2")
        cust = [(emit(P, i, "cust", r["cust"], ",", "customer"), emit(P, i, "date", r["since"], ",", "customer_since"))
                for i, r in enumerate(rows) if r["_table"] == "customers"]
        idx = [i for i, r in enumerate(rows) if r["_table"] == "customer_alias"]
        alias = [(emit(P, i, "cust", rows[i]["alias"], ",", "alias"), emit(P, i, "cust", rows[i]["master"], ",", "master")) for i in idx]
        return sqlite_bytes(W, name, {"customer_alias": (["alias", "master"], alias), "customers": (["customer", "customer_since"], cust)})
    plant_keys(P, ALL_KEYS)
    for kind, col in (("status", "status"), ("month", "period")):
        plant_q(W, name, P, kind, col)
    P.cover()
    for fam, code, desc, d in (("T16", "replica_complete_months", "replica holds every account for three months", "pull"),
                               ("T13", "cycle_controls_only_copy", "current cycle cohort controls exist only here", "push"),
                               ("T7", "cycle_controls_history", "controls of earlier cycles share the table", ""),
                               ("T8", "metric_names_suffixed", "historical metric names carry suffixes", ""),
                               ("T4", "control_value_text", "control values stored as text", ""),
                               ("T4", "balance_text_point", "balance as text", ""),
                               ("T14", "replica_not_value_source", "governance 1.3 forbids replica values", "push"),
                               ("T5", "dpd_minus_one", "-1 means not reported", ""),
                               ("T11", "replica_months_outside_certification", "months certified in other deliveries", "")):
        ftrap(W, name, fam, code, desc, "governance 1.3", direction=d)
    tables = {}
    for i, r in enumerate(rows):
        if r["_table"] == "cycle_controls":
            tables.setdefault("cycle_controls", []).append((r["cycle"], r["segment"], r["metric"], str(r["value"])))
        else:
            tables.setdefault(r["_table"], []).append((key_of(P, i, r["acct"]), emit(P, i, "month", r["month"], ",", "period"), r["dpd"],
                                                       emit(P, i, "status", r["status"], ",", "status"), str(r["balance"])))
    spec = {t: ((["cycle", "segment", "metric", "value"] if t == "cycle_controls" else ["account", "period", "dpd", "status", "balance"]), v)
            for t, v in sorted(tables.items())}
    return sqlite_bytes(W, name, spec)


def write_ml_v(W, name):
    rows = W.recs[name]
    P = Planter(W, name, len(rows))
    P.codes = set()
    for col in ("customer_a", "customer_b", "customer"):
        plant_q(W, name, P, "cust", col)
    for kind, col in (("id", "candidate_id"), ("id", "legacy_customer"), ("status", "suggestion")):
        plant_q(W, name, P, kind, col)
    P.cover()
    for fam, code, desc, d in (("T16", "auto_merge_label", "AUTO-MERGE suggestions that were never decided", "pull"),
                               ("T13", "legacy_sheet_authoritative", "legacy_refs is the only legacy id mapping", "push"),
                               ("T4", "probability_as_text_or_percent", "match probability as number, text or percent", ""),
                               ("T8", "two_sheets_one_delivery", "records counted across both sheets", ""),
                               ("T15", "probability_near_one", "probabilities of 0.995", "pull")):
        ftrap(W, name, fam, code, desc, "governance 3.10", direction=d)
    cand, leg = [], []
    for i, r in enumerate(rows):
        if r["_sheet"] == "candidates":
            prob = ("n", str(r["p"])) if i % 3 else (("s", f"{r['p'] * 100}%") if i % 2 else ("s", str(r["p"])))
            sug = emit(P, i, "status", "AUTO-MERGE" if r["p"] >= Decimal("0.99") else "REVIEW", ",", "suggestion")
            cand.append([("s", emit(P, i, "id", r["cand"], ",", "candidate_id")), ("s", emit(P, i, "cust", r["a"], ",", "customer_a")),
                         ("s", emit(P, i, "cust", r["b"], ",", "customer_b")), prob, ("s", sug)])
        else:
            leg.append([("s", emit(P, i, "id", r["legacy"], ",", "legacy_customer")), ("s", emit(P, i, "cust", r["cust"], ",", "customer"))])
    return write_xlsx(W, name, [("candidates", ["candidate_id", "customer_a", "customer_b", "match_probability", "suggestion"], cand),
                                ("legacy_refs", ["legacy_customer", "customer"], leg)])


def write_master_v(W, name):
    import pyarrow as pa
    rows = W.recs[name]
    P = Planter(W, name, len(rows))
    P.codes = set()
    plant_keys(P, ALL_KEYS)
    for kind, col in (("cust", "customer"), ("code", "branch"), ("code", "product_code"), ("money", "limit")):
        plant_q(W, name, P, kind, col)
    P.cover()
    for fam, code, desc, d in (("T6", "withdrawal_reversed_flag_only_here", "only evidence of withdrawal reversals", "push"),
                               ("T16", "master_cleansed_values", "cleansed limits and branches", "pull"),
                               ("T14", "description_metadata", "parquet metadata calls the extract cleansed", "pull"),
                               ("T13", "master_lacks_application_id", "no application id column", ""),
                               ("T3", "decision_epoch_seconds", "decision instants in epoch seconds", ""),
                               ("T7", "master_is_latest_snapshot", "master reflects latest revisions only", "pull")):
        ftrap(W, name, fam, code, desc, "governance 3.6", direction=d)
    for i, r in enumerate(rows):
        if r["reversed"]:
            W.trap(name, "T6", "withdrawal_reversed_flag", recno=i + 1, accts=[r["acct"]],
                   desc="only evidence that a cooling-off withdrawal was reversed", rule="governance 3.6")
    tbl = pa.table({"account": pa.array([key_of(P, i, r["acct"]) for i, r in enumerate(rows)]),
                    "customer": pa.array([emit(P, i, "cust", r["cust"], ";", "customer") for i, r in enumerate(rows)]),
                    "branch": pa.array([emit(P, i, "code", r["branch"], ";", "branch") for i, r in enumerate(rows)]),
                    "product_code": pa.array([emit(P, i, "code", r["code"], ";", "product_code") for i, r in enumerate(rows)]),
                    "limit": pa.array([emit(P, i, "money", r["limit"], ";", "limit") for i, r in enumerate(rows)]),
                    "decision_utc_s": pa.array([r["decision_utc"] for r in rows], pa.int64()),
                    "withdrawal_reversed": pa.array([r["reversed"] for r in rows], pa.bool_())})
    meta = {b"delivery_control": _json.dumps(control_payload(W, name), sort_keys=True).encode(),
            b"description": b"H1 2025 application master - cleansed, latest revision per account"}
    import pyarrow.parquet as pq
    tbl = tbl.replace_schema_metadata(meta)
    buf = pa.BufferOutputStream()
    pq.write_table(tbl, buf, compression="snappy", row_group_size=4096)
    return buf.getvalue().to_pybytes()


def write_co26_v(W, name):
    import pyarrow as pa
    rows = W.recs[name]
    P = Planter(W, name, len(rows))
    P.codes = set()
    plant_keys(P, ["key_lower", "key_zero_pad", "key_space", "key_homoglyph", "key_hyphen"])
    plant_kinds(W, name, P, ["id"])
    P.cover()
    ftrap(W, name, "T2", "amount_minor_units", "amount in minor units", "catalogue")
    ftrap(W, name, "T3", "date32_column", "dates stored as a date type", "catalogue")
    tbl = pa.table({"event_id": pa.array([emit(P, i, "id", r["eid"]) for i, r in enumerate(rows)]),
                    "account": pa.array([key_of(P, i, r["ref"]) for i, r in enumerate(rows)]),
                    "chargeoff_date": pa.array([r["date"] for r in rows], pa.date32()),
                    "amount_minor": pa.array([int(r["amount"] * 100) for r in rows], pa.int64())})
    return parquet_bytes(W, name, tbl)


def calib_rows_v(W, name, rows):
    P = Planter(W, name, len(rows))
    P.codes = set()
    for kind, col in (("status", "segment"), ("intz", "score"), ("pd", "pd")):
        plant_q(W, name, P, kind, col, latin1=True)
    P.cover()
    out = [[emit(P, i, "status", r["seg"], ";", "segment"), (f"{r['score']:04d}" if P.has(i, "int_zero_pad@score") else str(r["score"])),
            emit_pd(P, i, r["pd"], "pd")] for i, r in enumerate(rows)]
    return P, out


def write_model_pdf_v(W, name):
    R = W.recs[name]
    title, prose = PDF_TEXT[name]
    if name == "model_documentation_v4.pdf":
        P, rows = calib_rows_v(W, name, R)
        cuts = W.facts["cuts_doc"]
        cut_lines = ["segment | c1 | c2 | c3 | c4 | c5 | c6 | c7 | c8 | c9"] + [f"{s} | " + " | ".join(str(c) for c in cuts[s]) for s in SEGMENTS]
        approvals = ["Approved model versions: v4.0.0 all segments from 2024-10-01; v4.0.1 CARD and BNPL from 2025-02-01; "
                     "v4.0.2 CARD, PLOAN and OVDR from 2025-03-01 (the registry is authoritative)."]
        pages = [[title, ""] + [ln for p in prose + approvals for ln in _wrap(p) + [""]] + ["Score band cut points"] + cut_lines]
        pages += paginate(title + " - calibration grid", [], ["segment", "score", "pd"], rows)
        for fam, code, desc in (("T8", "pdf_page_header_repeats", "table header repeats on every page"),
                                ("T14", "approvals_in_prose", "approved versions restated in prose; registry wins"),
                                ("T14", "cut_points_amended_by_errata", "cut points subject to approved errata"),
                                ("T13", "cut_table_before_grid", "cut point table precedes the calibration grid")):
            ftrap(W, name, fam, code, desc, "spec 8.1")
    else:
        main = [r for r in R if r["_part"] == "reissue"]
        retro = [r for r in R if r["_part"] == "retro"]
        P, rows = calib_rows_v(W, name, R)
        rows_main, rows_retro = rows[: len(main)], rows[len(main):]
        pages = paginate(title, prose, ["segment", "score", "pd"], rows_main)
        pages += paginate("Appendix B - retrospective corrections", [], ["segment", "score", "pd"], rows_retro)
        for fam, code, desc, d in (("T16", "reissue_grid_newer", "newer calibration grid not in force for 2025 decisions", "pull"),
                                   ("T14", "appendix_b_retrospective", "retrospective corrections hide in Appendix B", "push"),
                                   ("T11", "reissue_effective_2026", "effective for decisions from 2026-01-01", ""),
                                   ("T13", "approved_change_request_label", "approved CR makes the reissue look in force", "pull"),
                                   ("T7", "retro_rows_unsorted", "Appendix B rows are not in grid order", ""),
                                   ("T15", "retro_pd_above_grid", "retrospective PDs exceed the original grid", ""),
                                   ("T8", "two_tables_same_header", "grid and Appendix B share a header", ""),
                                   ("T8", "pdf_page_header_repeats", "table header repeats on every page", ""),
                                   ("T14", "pdf_rule_in_prose", "scope stated in prose", "")):
            ftrap(W, name, fam, code, desc, "governance 3.15", recno=len(main) + 1 if "retro" in code else 0, direction=d)
    pages[-1].append("Delivery control: " + control_line(W, name))
    return pdf_bytes(pages)


def write_md_v(W, name):
    rows = W.recs[name]
    P = Planter(W, name, len(rows))
    P.codes = set()
    if name == "monitoring_spec_v4.md":
        plant_q(W, name, P, "status", "segment")
        plant_q(W, name, P, "intz", "score")
        plant_kinds(W, name, P, ["count"])
        P.cover()
        for fam, code, desc in (("T8", "appendix_table_split_repeated_header", "appendix table restarts with a repeated header"),
                                ("T14", "rules_in_prose", "binding rules live in the prose sections"),
                                ("T9", "catalogue_cells_with_semicolons", "catalogue cells carry semicolons and quotes")):
            ftrap(W, name, fam, code, desc, "spec 2.2", recno=901)
        W.md_rows = [[emit(P, i, "status", r["seg"], ";", "segment"), f"{r['score']:04d}" if P.has(i, "int_zero_pad@score") else str(r["score"]),
                      emit_count(P, i, r["count"])] for i, r in enumerate(rows)]
        return spec_md(W)
    if name == "errata_register.md":
        plant_kinds(W, name, P, ["acct", "month", "int", "status", "date", "id"], skip=("int_signed_string",))
        P.cover()
        W.md_rows = [[emit(P, i, "id", r["id"]), key_of(P, i, r["acct"]), emit(P, i, "month", r["month"]), emit(P, i, "int", r["dpd"]),
                      emit(P, i, "status", r["status"]), emit(P, i, "date", r["date"])] for i, r in enumerate(rows)]
        return errata_md(W)
    plant_kinds(W, name, P, ["id", "status"])
    for code, fam, desc in (("delivery_name_case", "T1", "delivery name in another letter case"),
                            ("record_number_zero_padded", "T9", "record number with leading zeros")):
        P.scatter(code, fam, rate=0.004, desc=desc, rule="dq log preamble")
        P.codes.add(code)
    P.cover()
    for fam, code, desc in (("T9", "note_with_escaped_pipe", "notes contain escaped pipe characters"),
                            ("T13", "historical_delivery_names", "issues against deliveries of other cycles")):
        ftrap(W, name, fam, code, desc, "dq log preamble")
    out = []
    for i, r in enumerate(rows):
        f = r["file"].upper() if P.has(i, "delivery_name_case") else r["file"]
        rn = f"{r['recno']:06d}" if P.has(i, "record_number_zero_padded") else str(r["recno"])
        note = "value outside range | checked" if i % 23 == 0 else "-"
        out.append([emit(P, i, "id", r["issue"]), f, rn, emit(P, i, "status", r["disp"]), note])
    W.md_rows = out
    return dq_md(W)


def plant_tie_fixtures(W):
    """Hidden estates only: one graded case for each ordering rule that random placement never triggers.

    Each fixture leaves the documented answer unchanged and makes the opposite reading of the rule
    change a graded row: WINDOW before WITHDRAWN and INSOLVENCY before REDRESS (exclusion policy 1),
    migration ties by id (spec 3.4), duplicate-walk ties by acct (spec 3.6), row-errata ties by
    erratum id (errata register) and mailbox ties by Message-ID (governance 2.3). A fixture with no
    eligible account is skipped, so the generator never fails because of it.
    """
    F, R = W.facts, W.recs
    W.ring = {"files": {}, "by_id": {}, "expected_ids": []}
    L = build_L(W)
    res = run_rules(L, ignore_gate=True)
    dec, excl, finals = res.decisions, res.exclusions, res.final_recs
    used = set()
    touched = set()

    # WINDOW before WITHDRAWN: an out-of-window account with an unreversed withdrawal 7 days after decision.
    for acct in sorted(a for a, why in excl.items() if why == "WINDOW"):
        if acct in L["withdrawals"] or acct in L["withdrawal_reversed"]:
            continue
        R["application_withdrawals.json"].append({"acct": acct, "date": dec[acct]["ddate"] + _dt.timedelta(days=7),
                                                  "_h": digits_of(acct)})
        touched.add("application_withdrawals.json")
        used.add(acct)
        break

    # INSOLVENCY before REDRESS: an account excluded as INSOLVENCY also joins the redress programme.
    for acct in sorted(a for a, why in excl.items() if why == "INSOLVENCY"):
        if acct in L["redress"]:
            continue
        R["consumer_redress_programme.pdf"].append({"acct": acct, "programme": "RDR-FEES-2024", "_h": digits_of(acct)})
        R["consumer_redress_programme.pdf"].sort(key=lambda r: r["acct"])
        touched.add("consumer_redress_programme.pdf")
        used.add(acct)
        break

    # Migration ties by id: a cohort account on a current-basis partition gets a second migration on the
    # day of its first, with a higher id, continuing the chain into another code of the same segment.
    mig_ids = {digits_of(r["id"]) for r in R["product_migrations_2025.xlsx"]}
    for acct in sorted(res.cohort):
        rec, moves = finals[acct], L["migrations"].get(acct, [])
        if rec["product_basis"] != "current" or len(moves) != 1:
            continue
        frm, to, day, mid = moves[0]
        if (not day > dec[acct]["ddate"] or day > EXTRACT_DATE or frm not in L["prodmap"] or to not in L["prodmap"]
                or L["prodmap"][frm] == L["prodmap"][to]):
            continue
        nxt = digits_of(mid) + 1
        while nxt in mig_ids:
            nxt += 1
        if nxt > 999999:
            continue
        new_code = next(c for c in sorted(L["prodmap"]) if L["prodmap"][c] == L["prodmap"][to] and c != to)
        new_id = f"MIG{nxt:06d}"
        R["product_migrations_2025.xlsx"].append({"acct": acct, "from": to, "to": new_code, "date": day, "id": new_id,
                                                  "_h": digits_of(acct)})
        F["migrations"].append((acct, to, new_code, day, new_id))
        F["mig_by_acct"].setdefault(acct, []).append((acct, to, new_code, day, new_id))
        for r in R["applications_2025_05.xlsx"]:
            if r["acct"] == acct and r["code"] == to:
                r["code"] = new_code
        touched.add("product_migrations_2025.xlsx")
        used.add(acct)
        break

    # Duplicate-walk ties by acct: the later account of a duplicate pair is moved onto the decision instant
    # of the kept account, which has the lower acct.
    groups = {}
    for acct in sorted(dec):
        if excl.get(acct) not in ("WINDOW", "WITHDRAWN"):
            groups.setdefault((dec[acct]["cust"], dec[acct]["product"]), []).append(acct)
    done = False
    for key in sorted(groups):
        members = sorted(groups[key], key=lambda x: (dec[x]["decision_utc"], x))
        for first, second in zip(members, members[1:]):
            a, b = dec[first], dec[second]
            if (done or excl.get(first) == "DUPLICATE" or excl.get(second) != "DUPLICATE" or first > second
                    or a["market"] != b["market"] or second in L["withdrawals"] or second in L["migrations"]
                    or first in used or second in used
                    or sum(dec[x]["decision_utc"] in (a["decision_utc"], b["decision_utc"]) for x in members) != 2):
                continue
            rec = finals[second]
            branch = rec["branch"]
            if branch.startswith("BR-"):
                branch = L["branch_xwalk"].get(branch, branch)
            local = utc_to_local(b["market"], a["decision_utc"])
            if local_to_utc(b["market"], local) != a["decision_utc"]:
                continue
            spans = L["branches"].get(branch, ())
            ok = True
            for day in (date_of_secs(a["decision_utc"]), date_of_secs(local)):
                hit = None
                for mkt, start, end in spans:
                    if start <= day and (end is None or day <= end):
                        hit = mkt
                ok = ok and hit == b["market"]
            if not ok:
                continue
            delta = a["decision_utc"] - b["decision_utc"]
            for name in [*APP_FILES.values(), "applications_master_2025h1.parquet", "applications_2025_04_reextract.csv"]:
                for r in R[name]:
                    if r["acct"] == second:
                        r["decision_utc"] = a["decision_utc"]
                        r["local"] = local
                        r["received"] += delta
                        touched.add(name)
            used.update((first, second))
            done = True
        if done:
            break

    # Row-errata and mailbox ties: a cohort account-month whose corrected DPD decides its window row gets a
    # second correction raised on the same date (same Date instant) with a lower erratum id (lower Message-ID),
    # listed after the winning one, carrying a DPD above the account's maximum.
    snaps = {}
    for r in L["snaps"]:
        if (r["file"], r["recno"]) not in L["quarantine"]:
            snaps.setdefault((r["acct"], r["month"]), set()).add(r["file"])
    forborne = {}
    for gid, (acct, start, end) in L["forbear_grants"].items():
        if gid not in L["forbear_revoked"]:
            forborne.setdefault(acct, set()).update(range(start, max([end] + L["forbear_ext"].get(gid, [])) + 1))

    def eligible(key):
        acct, mo = key
        a = res.cohort.get(acct)
        return (a is not None and acct not in used and a["cmonth"] < mo <= a["cmonth"] + 12
                and L["certified"].get((mo, a["market"])) in snaps.get(key, ())
                and mo not in forborne.get(acct, ()))

    er_ids = {digits_of(r["id"]) for r in R["errata_register.md"]}
    for key in sorted(k for k in L["errata"] if eligible(k)):
        rows = [r for r in R["errata_register.md"] if (r["acct"], r["month"]) == key and r["status"] == "APPLIED"]
        win = max(rows, key=lambda r: (r["date"], r["id"]))
        low = digits_of(win["id"]) - 1
        while low in er_ids:
            low -= 1
        if low < 10000:
            continue
        new_id = f"ER-{low:05d}"
        R["errata_register.md"].append({"id": new_id, "acct": key[0], "month": key[1], "status": "APPLIED",
                                        "dpd": max(win["dpd"], res.window_rows[key[0]][3]) + 30, "date": win["date"],
                                        "_h": digits_of(new_id)})
        touched.add("errata_register.md")
        used.add(key[0])
        break

    box = R["ops_corrections.mbox"]
    msg_ids = {digits_of(m["msgid"]) for m in box}
    retracted = {m["target"] for m in box if m["kind"] == "retract"}
    for key in sorted(k for k in L["mail_corr"] if eligible(k) and k not in L["errata"] and k not in L["xml_corr"]):
        live = [m for m in box if m["kind"] == "corr" and m["key"] == key and m["msgid"] not in retracted]
        win = max(live, key=lambda m: (m["ts"], m["msgid"]))
        low = digits_of(win["msgid"]) - 1
        while low in msg_ids:
            low -= 1
        if low < 10000000:
            continue
        new_id = f"<corr.{low:08d}@servicing.example-bank.eu>"
        box.append({"kind": "corr", "key": key, "dpd": max(win["dpd"], res.window_rows[key[0]][3]) + 30,
                    "ts": win["ts"], "msgid": new_id, "_h": digits_of(new_id)})
        touched.add("ops_corrections.mbox")
        used.add(key[0])
        break

    for name in sorted(touched):
        for i, r in enumerate(R[name]):
            r["_recno"] = i + 1
    W.tie_fixtures = sorted(used)


def build_eval(seed, scale, out_dir, variant=None):
    """Write a fresh estate under the documented rules and return its exact expected artifacts."""
    W = build_world(seed, scale)
    assemble(W)
    if variant is None:
        plant_tie_fixtures(W)
    finalize(W)
    if variant == "truncated":
        rng = _random.Random(seed ^ 0x7E57)
        victims = sorted(n for n in COLS if COLS[n][0].split(":")[0] in ("csv", "tsv", "jsonl", "json"))
        victim = rng.choice(victims)
        W.recs[victim] = W.recs[victim][:-2]
        info = W.ring["files"][victim]
        info["rows"] = len(W.recs[victim])
        info["hash"] = sum(r["_h"] for r in W.recs[victim])
        W.L["ring"] = W.ring
        W.result = run_rules(W.L)
        W.outputs = render_outputs(W.L, W.result)
    write_estate(W, out_dir, passes=1)
    return {n: W.outputs[n].decode("utf-8") for n in OUTPUT_NAMES}
